// AUTO-GENERATED by /tmp/namelock/build.js, do not hand-edit.
window.NL_CARDS=[{"id":"stroop-effect","name":"Stroop effect","cat":"effect","area":"cognitive","who":"J. Ridley Stroop","year":"1935","def":"It takes longer to name the ink colour of a word when the word spells a different colour.","detail":"Reading is automatic, so the word meaning interferes with the slower colour-naming task; incongruent trials (RED in blue ink) are slower and more error-prone than congruent ones. Used to test selective attention and frontal (anterior cingulate) function.","example":"Saying 'blue' for the word GREEN printed in blue ink is slow and you often blurt 'green'.","look":"Cocktail party effect","tell":"Stroop = automatic READING interferes with colour naming; cocktail party = your NAME breaks through unattended sound.","aliases":["stroop"],"lookId":"cocktail-party-effect"},{"id":"zeigarnik-effect","name":"Zeigarnik effect","cat":"effect","area":"memory","who":"Bluma Zeigarnik","year":"1927","def":"Unfinished or interrupted tasks are remembered better than finished ones.","detail":"A student of Kurt Lewin, Zeigarnik found interrupted tasks were recalled roughly twice as often as completed ones; Lewin's field theory explains it as unresolved task tension.","example":"A waiter remembers unpaid orders in detail but forgets them once the bill is settled.","look":"Ovsiankina effect","tell":"Zeigarnik = you REMEMBER the unfinished task; Ovsiankina = you go back to FINISH it.","aliases":["zeigarnik","zeigarnick","zeigarnic"],"lookId":"ovsiankina-effect"},{"id":"ovsiankina-effect","name":"Ovsiankina effect","cat":"effect","area":"cognitive","who":"Maria Ovsiankina","year":"1928","def":"People feel an urge to resume and complete a task that was interrupted.","detail":"Another of Lewin's students; when given free time, most participants spontaneously went back to the interrupted task. It is about behaviour (resumption), not recall.","example":"You keep returning to a half-solved crossword even though nobody asked you to.","look":"Zeigarnik effect","tell":"Ovsiankina = O for 'Over again' (resume it); Zeigarnik = memory of it.","aliases":["ovsiankina","ovsyankina","ovsiankin"],"lookId":"zeigarnik-effect"},{"id":"primacy-effect","name":"Primacy effect","cat":"effect","area":"memory","who":"Hermann Ebbinghaus (memory); Solomon Asch (impressions)","year":"","def":"Items at the start of a list, or first information about a person, are remembered or weighted more.","detail":"In free recall it reflects extra rehearsal that moves early items into long-term memory; it survives a delay. Asch (1946) showed 'intelligent... envious' is judged better than the same traits in reverse order.","example":"You remember the first few names in a long introduction round.","look":"Recency effect","tell":"Primacy = FIRST items, long-term memory, survives delay; recency = LAST items, short-term memory, wiped by delay.","aliases":["primacy effect"],"lookId":"recency-effect"},{"id":"recency-effect","name":"Recency effect","cat":"effect","area":"memory","who":"Glanzer & Cunitz (delay study)","year":"1966","def":"Items at the end of a list are recalled well when recall is immediate.","detail":"The last items are still in short-term memory; Glanzer and Cunitz showed a 30-second distractor delay wipes out recency but leaves primacy intact.","example":"After hearing a phone number you can easily repeat its last few digits.","look":"Primacy effect","tell":"Recency = Recent, still in STM; kill it with a distractor delay.","aliases":["recency effect"],"lookId":"primacy-effect"},{"id":"serial-position-effect","name":"Serial position effect","cat":"effect","area":"memory","who":"Hermann Ebbinghaus (first noted); Bennet Murdock (free-recall curve)","year":"1962","def":"Recall of a list depends on item position: first and last items are best remembered, middle items worst.","detail":"Produces a U-shaped curve combining primacy (LTM) and recency (STM); Murdock's 1962 free-recall curves are the classic data and support the Atkinson-Shiffrin two-store model.","example":"From a grocery list you recall bread (first) and eggs (last) but forget the middle items.","look":"Von Restorff effect","tell":"Serial position = WHERE in the list (U-curve); von Restorff = WHAT stands out (odd one out).","aliases":["serial position","serial-position","list position effect","sequence memory effect","order recall effect","primacy-recency effect","primacy recency effect","primacy and recency"],"lookId":"von-restorff-effect"},{"id":"von-restorff-effect","name":"Von Restorff effect (isolation effect)","cat":"effect","area":"memory","who":"Hedwig von Restorff","year":"1933","def":"An item that stands out from the rest of a list is remembered better.","detail":"Also called the isolation or distinctiveness effect; a single number in a list of syllables, or a red word among black words, is recalled far better.","example":"In a list of fruits, the single word 'tractor' is the one everyone remembers.","look":"Serial position effect","tell":"Von Restorff = the ODD one out stands out; serial position = first and last win.","aliases":["von restorff","restorff","isolation effect","distinctiveness effect"],"lookId":"serial-position-effect"},{"id":"self-reference-effect","name":"Self-reference effect","cat":"effect","area":"memory","who":"Rogers, Kuiper & Kirker","year":"1977","def":"Information related to oneself is remembered better than other information.","detail":"Asking 'Does this word describe you?' produced better recall than semantic ('Does it mean X?') or structural judgements, extending levels of processing: self is a rich encoding scheme.","example":"You remember the trait words from a quiz that asked whether each word describes you.","look":"Levels-of-processing effect","tell":"Self-reference = deepest level, linked to ME; levels of processing = the general shallow-to-deep framework.","aliases":["self-reference effect","self reference effect","self-referential effect"],"lookId":"levels-of-processing-effect"},{"id":"testing-effect","name":"Testing effect (retrieval practice effect)","cat":"effect","area":"memory","who":"Roediger & Karpicke","year":"2006","def":"Taking a test on material improves long-term memory more than re-reading it.","detail":"Students who practised retrieval recalled far more after one week than those who restudied, even though restudy felt better in the short run. Retrieval itself strengthens memory.","example":"Doing PYQ mocks instead of re-reading notes leads to better exam recall.","look":"Spacing effect","tell":"Testing = RETRIEVE it; spacing = SPREAD it out over time.","aliases":["testing effect","retrieval practice","test-enhanced learning","retrieval practice effect"],"lookId":"spacing-effect"},{"id":"spacing-effect","name":"Spacing effect","cat":"effect","area":"memory","who":"Hermann Ebbinghaus","year":"1885","def":"Study spread out over several sessions is remembered better than the same study crammed into one session.","detail":"Distributed practice beats massed practice for long-term retention; Ebbinghaus found fewer total repetitions were needed when they were spaced over days.","example":"Revising a chapter for 20 minutes on 3 days beats one 60-minute cram the night before.","look":"Testing effect","tell":"Spacing = WHEN you study (spread out); testing = HOW you study (recall it).","aliases":["spacing effect","distributed practice","spaced practice","massed versus distributed","spaced repetition"],"lookId":"testing-effect"},{"id":"generation-effect","name":"Generation effect","cat":"effect","area":"memory","who":"Slamecka & Graf","year":"1978","def":"Information you produce yourself is remembered better than information you just read.","detail":"Completing 'hot: c_ _ _' (cold) gave better recall of 'cold' than reading 'hot: cold'.","example":"Making your own mnemonic sticks better than copying someone else's.","look":"Testing effect","tell":"Generation = CREATE the item at study; testing = RETRIEVE the item later.","aliases":["generation effect"],"lookId":"testing-effect"},{"id":"levels-of-processing-effect","name":"Levels-of-processing effect","cat":"effect","area":"memory","who":"Craik & Lockhart (theory); Craik & Tulving (experiment)","year":"1972","def":"The more deeply (meaningfully) you process information, the better you remember it.","detail":"Three levels: structural (Is it in capitals?), phonemic (Does it rhyme with...?), semantic (Does it fit the sentence?); semantic gives the best recall (Craik & Tulving, 1975).","example":"Thinking about what 'catharsis' means beats noticing how it is spelled.","look":"Self-reference effect","tell":"Levels of processing = general shallow-to-deep rule; self-reference = the special 'relates to me' deep level.","aliases":["levels of processing","levels-of-processing","depth of processing","depth-of-processing"],"lookId":"self-reference-effect"},{"id":"picture-superiority-effect","name":"Picture superiority effect","cat":"effect","area":"memory","who":"Allan Paivio (dual-coding explanation)","year":"1970s","def":"Pictures are remembered better than the words that name them.","detail":"Paivio's dual-coding theory: pictures get both an image code and a verbal code. Standing (1973) showed people recognise thousands of pictures with high accuracy.","example":"You recall the diagram of the neuron from a book better than its text description.","look":"Word superiority effect","tell":"Picture superiority = pictures beat WORDS in memory; word superiority = a WORD beats a single letter in perception.","aliases":["picture superiority","pictorial superiority","picture-superiority"],"lookId":"word-superiority-effect"},{"id":"word-superiority-effect","name":"Word superiority effect","cat":"effect","area":"perception","who":"Reicher; Wheeler","year":"1969","def":"A letter is identified more accurately when it appears inside a real word than alone or in a non-word.","detail":"In the Reicher-Wheeler task, D or K is detected better in WORD than in ORWD or as a lone letter, showing top-down influence of word knowledge on perception.","example":"You spot the letter 'K' faster in 'WORK' than in a random string 'ROWK'.","look":"Picture superiority effect","tell":"Word superiority = PERCEPTION of a letter in context; picture superiority = MEMORY for images.","aliases":["word superiority","word-superiority","reicher-wheeler"],"lookId":"picture-superiority-effect"},{"id":"misinformation-effect","name":"Misinformation effect","cat":"effect","area":"memory","who":"Elizabeth Loftus (with Palmer)","year":"1974","def":"Misleading information received after an event distorts memory of the event.","detail":"Loftus and Palmer: asking how fast cars 'smashed' vs 'hit' raised speed estimates, and a week later 'smashed' participants falsely reported seeing broken glass. Popular 'Mandela effect' examples are shared false memories of this kind.","example":"A leading police question ('Did you see the knife?') makes a witness later remember a knife that was not there.","look":"Source amnesia (source monitoring error)","tell":"Misinformation = AFTER-the-event info rewrites memory; source amnesia = you remember the fact but forget where it came from.","aliases":["misinformation effect","mandela effect","post-event information","post event misinformation","smashed into"],"lookId":"source-amnesia"},{"id":"weapon-focus-effect","name":"Weapon focus effect","cat":"effect","area":"memory","who":"Loftus, Loftus & Messo","year":"1987","def":"When a weapon is present, witnesses attend to it and remember the culprit's face and other details poorly.","detail":"Eye-tracking showed more and longer fixations on a gun than on a cheque; face identification fell. Explained by narrowing of attention under threat (Easterbrook cue utilisation).","example":"A bank teller can describe the gun in detail but cannot identify the robber.","look":"Misinformation effect","tell":"Weapon focus = error at ENCODING (attention on the gun); misinformation = error AFTER encoding (leading info).","aliases":["weapon focus","weapon-focus"],"lookId":"misinformation-effect"},{"id":"own-race-bias","name":"Own-race bias (cross-race effect)","cat":"effect","area":"memory","who":"Malpass & Kravitz","year":"1969","def":"People recognise faces of their own racial group more accurately than faces of other groups.","detail":"Reflects greater perceptual expertise with frequently seen face types; it is a major source of eyewitness misidentification in cross-race cases.","example":"A witness confidently picks the wrong person from a line-up of another ethnic group.","look":"Out-group homogeneity effect","tell":"Own-race bias = poorer FACE RECOGNITION; out-group homogeneity = belief that 'they are all alike' in traits.","aliases":["own-race bias","own race bias","cross-race effect","cross race effect","other-race effect","other race effect","own-race effect"],"lookId":"out-group-homogeneity"},{"id":"google-effect","name":"Google effect (digital amnesia)","cat":"effect","area":"memory","who":"Sparrow, Liu & Wegner","year":"2011","def":"People are less likely to remember information they expect to be able to look up online.","detail":"Participants who believed typed facts would be saved remembered them worse, but remembered WHERE they were saved better; the internet acts as transactive (external) memory.","example":"You do not memorise a phone number because it is saved in your contacts.","look":"Transactive memory","tell":"Google effect = forgetting because the machine stores it; transactive memory = the general sharing of memory across people or tools.","aliases":["google effect","digital amnesia"]},{"id":"mcgurk-effect","name":"McGurk effect","cat":"effect","area":"perception","who":"Harry McGurk & John MacDonald","year":"1976","def":"What we see a speaker's lips do changes the speech sound we hear.","detail":"Audio 'ba' dubbed onto lips saying 'ga' is heard as 'da'; a classic demonstration of audiovisual integration in speech perception.","example":"A badly dubbed film makes you hear a different syllable than the one actually spoken.","look":"Cocktail party effect","tell":"McGurk = EYES change what the ears hear; cocktail party = picking ONE voice out of many.","aliases":["mcgurk","mc gurk"],"lookId":"cocktail-party-effect"},{"id":"cocktail-party-effect","name":"Cocktail party effect","cat":"effect","area":"cognitive","who":"E. Colin Cherry","year":"1953","def":"The ability to focus on one conversation in a noisy room, yet still notice your own name in an unattended one.","detail":"Cherry studied it with dichotic listening and shadowing; Moray (1959) showed one's own name breaks through, supporting Treisman's attenuation model over Broadbent's strict filter.","example":"In a loud wedding hall you hear someone across the room say your name.","look":"Bottleneck (attentional bottleneck)","tell":"Cocktail party = the named EXPERIENCE (your name pops out); bottleneck = the structural limited-capacity STAGE.","aliases":["cocktail party","cocktail-party","cocktail phenomenon"],"lookId":"attentional-bottleneck"},{"id":"attentional-bottleneck","name":"Bottleneck effect (attentional bottleneck)","cat":"effect","area":"cognitive","who":"Donald Broadbent (filter theory)","year":"1958","def":"Attention has a narrow, limited-capacity stage through which only some information can pass at a time.","detail":"Broadbent's filter model placed the bottleneck early; Deutsch and Deutsch placed it late; Treisman made it an attenuator. (In genetics, a 'bottleneck effect' is a sharp population drop reducing variation, a different idea.)","example":"Two people talking to you at once: you can only follow one fully.","look":"Cocktail party effect","tell":"Bottleneck = the narrow NECK of the attention bottle (a model concept), not a named everyday experience.","aliases":["bottleneck effect","attentional bottleneck","attention bottleneck"],"lookId":"cocktail-party-effect"},{"id":"purkinje-shift","name":"Purkinje shift (Purkinje effect)","cat":"effect","area":"perception","who":"Jan Evangelista Purkinje","year":"1820s","def":"As light dims, reds look darker and blues/greens look relatively brighter.","detail":"Caused by the switch from cone (photopic, peak about 555 nm) to rod (scotopic, peak about 505 nm) vision at dusk.","example":"At twilight a red rose looks almost black while its green leaves still look bright.","look":"Bezold-Brucke effect","tell":"Purkinje = DIM light shifts brightness from red to blue (rods take over); Bezold-Brucke = changing INTENSITY shifts the HUE seen.","aliases":["purkinje shift","purkinje effect","purkyne shift"],"lookId":"bezold-brucke-effect"},{"id":"bezold-brucke-effect","name":"Bezold-Brucke effect","cat":"effect","area":"perception","who":"Wilhelm von Bezold; Ernst Brucke","year":"1870s","def":"The perceived hue of a light changes as its intensity changes, even with wavelength held constant.","detail":"As intensity rises, most hues shift toward yellow or blue; a few invariant hues (pure yellow, green, blue) do not shift.","example":"A dim orange light looks more reddish, and the same light made very bright looks more yellow.","look":"Purkinje shift","tell":"Bezold-Brucke = HUE changes with intensity; Purkinje = relative BRIGHTNESS of colours changes in dim light.","aliases":["bezold-brucke","bezold-brücke","bezold brucke","bezold-bruecke"],"lookId":"purkinje-shift"},{"id":"baader-meinhof-phenomenon","name":"Baader-Meinhof phenomenon (frequency illusion)","cat":"effect","area":"cognitive","who":"Arnold Zwicky (term 'frequency illusion')","year":"2005","def":"After you first notice something, you suddenly seem to see it everywhere.","detail":"Selective attention makes you notice it more, and confirmation bias makes you take each sighting as proof it is now more common.","example":"After learning the word 'anhedonia' you see it in every paper you open.","look":"Mere exposure effect","tell":"Baader-Meinhof = you NOTICE it more; mere exposure = you LIKE it more.","aliases":["baader-meinhof","baader meinhof","frequency illusion"],"lookId":"mere-exposure-effect"},{"id":"hawthorne-effect","name":"Hawthorne effect","cat":"effect","area":"research","who":"Elton Mayo (Hawthorne studies); term by Henry Landsberger","year":"1924-1932","def":"People change their behaviour simply because they know they are being observed or studied.","detail":"At Western Electric's Hawthorne Works, worker productivity rose with almost any change in lighting or breaks, apparently because of the attention received. Landsberger named it in 1958.","example":"Staff work harder in the week the inspection team visits the hospital.","look":"John Henry effect","tell":"Hawthorne = the STUDIED group improves because watched; John Henry = the CONTROL group works harder to compete.","aliases":["hawthorne"],"lookId":"john-henry-effect"},{"id":"pygmalion-effect","name":"Pygmalion effect (Rosenthal effect)","cat":"effect","area":"research","who":"Robert Rosenthal & Lenore Jacobson","year":"1968","def":"Higher expectations from others lead to better performance by the person expected to do well.","detail":"Teachers told that randomly chosen pupils were 'late bloomers' saw those pupils gain more IQ points over a year (Pygmalion in the Classroom); a self-fulfilling prophecy.","example":"A coach who believes a new player is gifted gives more practice, and the player improves.","look":"Golem effect","tell":"Pygmalion = HIGH expectations raise performance; Golem = LOW expectations drag it down.","aliases":["pygmalion","rosenthal effect","teacher expectancy effect","teacher expectancy"],"roots":"Pygmalion: Greek myth of a sculptor whose statue (Galatea) came to life","lookId":"golem-effect"},{"id":"golem-effect","name":"Golem effect","cat":"effect","area":"research","who":"Babad, Inbar & Rosenthal","year":"1982","def":"Low expectations placed on a person lead to poorer performance.","detail":"The negative mirror of the Pygmalion effect; supervisors or teachers who expect little give less support and feedback, so performance drops.","example":"A teacher who has written off the back bench calls on them less, and their marks fall.","look":"Pygmalion effect","tell":"Golem = a clay monster, LOW expectations; Pygmalion = HIGH expectations.","aliases":["golem effect","golem"],"lookId":"pygmalion-effect"},{"id":"galatea-effect","name":"Galatea effect","cat":"effect","area":"research","who":"","year":"","def":"A person's OWN high expectations of themselves improve their performance.","detail":"Self-expectancy version of the Pygmalion effect, studied mainly in organisations (e.g. Dov Eden's work on self-efficacy and performance).","example":"A student who believes she can crack NIMHANS puts in the hours and does well.","look":"Pygmalion effect","tell":"Galatea = SELF-expectation (the statue believes in herself); Pygmalion = OTHERS' expectation.","aliases":["galatea"],"lookId":"pygmalion-effect"},{"id":"placebo-effect","name":"Placebo effect","cat":"effect","area":"research","who":"Henry K. Beecher (popularised, 'The Powerful Placebo')","year":"1955","def":"Improvement that occurs because a person believes they are receiving an effective treatment, even if it is inactive.","detail":"Beecher estimated about 35% of patients improve on placebo; placebo analgesia involves endogenous opioids and can be blocked by naloxone. Controlled for with double-blind designs.","example":"A sugar pill labelled 'strong painkiller' reduces a patient's headache.","look":"Nocebo effect","tell":"Placebo = 'I will please' (positive expectation helps); nocebo = 'I will harm' (negative expectation hurts).","aliases":["placebo"],"roots":"placebo (Latin) = 'I shall please'","lookId":"nocebo-effect"},{"id":"nocebo-effect","name":"Nocebo effect","cat":"effect","area":"clinical","who":"Walter Kennedy (coined term)","year":"1961","def":"Negative expectations about a treatment produce real negative symptoms or side effects.","detail":"Patients warned about side effects of an inert pill report those side effects; a key reason informed-consent wording matters.","example":"After reading the leaflet, a patient on a dummy tablet complains of nausea and dizziness.","look":"Placebo effect","tell":"Nocebo = 'I shall harm'; placebo = 'I shall please'.","aliases":["nocebo"],"roots":"nocebo (Latin) = 'I shall harm'","lookId":"placebo-effect"},{"id":"john-henry-effect","name":"John Henry effect","cat":"effect","area":"research","who":"Gary Saretsky","year":"1972","def":"Members of a control group work extra hard to outperform the experimental group because they feel they are competing.","detail":"Named after the folk hero who raced a steam drill and won; it shrinks the apparent difference between groups (compensatory rivalry).","example":"The class that did NOT get the new teaching method studies harder to prove the old method is fine.","look":"Hawthorne effect","tell":"John Henry = CONTROL group competes; Hawthorne = observed group improves.","aliases":["john henry"],"lookId":"hawthorne-effect"},{"id":"ceiling-effect","name":"Ceiling effect","cat":"effect","area":"research","who":"","year":"","def":"A test is too easy, so most people score near the maximum and real differences cannot be seen.","detail":"Scores pile up at the top, giving a negatively skewed distribution and restricted variance; the independent variable may look ineffective when it is not.","example":"Every student scores 48-50 on a 50-mark test, so the test cannot separate good from excellent.","look":"Floor effect","tell":"Ceiling = everyone hits the TOP (test too easy); floor = everyone stuck at the BOTTOM (too hard).","aliases":["ceiling effect"],"lookId":"floor-effect"},{"id":"floor-effect","name":"Floor effect","cat":"effect","area":"research","who":"","year":"","def":"A test is too hard, so most people score near the minimum and real differences cannot be seen.","detail":"Scores bunch at the bottom, giving a positively skewed distribution and restricted range.","example":"A memory test so difficult that both patients and controls recall almost nothing.","look":"Ceiling effect","tell":"Floor = stuck at the BOTTOM (too hard); ceiling = squeezed at the TOP (too easy).","aliases":["floor effect"],"lookId":"ceiling-effect"},{"id":"practice-effect","name":"Practice effect","cat":"effect","area":"research","who":"","year":"","def":"Scores improve on a repeated test simply because the person has done it before.","detail":"A threat to test-retest reliability and to within-subjects designs; controlled with alternate forms or longer retest intervals.","example":"A patient scores higher on the same memory test the second week because he remembers the items.","look":"Fatigue effect","tell":"Practice = later performance BETTER from familiarity; fatigue = later performance WORSE from tiredness.","aliases":["practice effect","practice effects","testing practice effect"]},{"id":"order-effect","name":"Order effect (carryover effect)","cat":"effect","area":"research","who":"","year":"","def":"In a repeated-measures design, performance in a condition is influenced by the condition that came before it.","detail":"Order effects include practice and fatigue effects; carryover effects are when a specific earlier condition leaves a lasting influence. Controlled by counterbalancing (e.g. ABBA, Latin square).","example":"Participants rate the second soft drink sweeter because the first one was sour.","look":"Practice effect","tell":"Order/carryover = effect of SEQUENCE between conditions (fix with counterbalancing); practice = just getting better at the same test.","aliases":["order effect","order effects","carryover effect","carry-over effect","carry over effect","sequence effect","sequencing effect"],"lookId":"practice-effect"},{"id":"experimenter-expectancy-effect","name":"Experimenter expectancy effect","cat":"effect","area":"research","who":"Robert Rosenthal (with Kermit Fode)","year":"1963","def":"A researcher's expectations unintentionally influence participants' responses or the recorded results.","detail":"Students told their rats were 'maze-bright' recorded faster learning than those told 'maze-dull', though the rats were identical. Controlled by double-blind procedures.","example":"An experimenter who expects a drug to work smiles more when the drug group answers.","look":"Demand characteristics","tell":"Experimenter expectancy = cue comes from the RESEARCHER's expectations; demand characteristics = participant reads cues from the SITUATION.","aliases":["experimenter expectancy","experimenter bias","experimenter effect","researcher bias","observer-expectancy","observer expectancy","expectancy effect"],"lookId":"demand-characteristics"},{"id":"demand-characteristics","name":"Demand characteristics","cat":"effect","area":"research","who":"Martin Orne","year":"1962","def":"Cues in a study that let participants guess its purpose, so they change their behaviour to fit what they think is expected.","detail":"Orne showed participants would add up random numbers for hours because they assumed it was meaningful; the 'good subject' role. Controlled with deception, single-blind designs and post-experimental inquiry.","example":"A participant guesses the study is about prejudice and answers in an unusually tolerant way.","look":"Experimenter expectancy effect","tell":"Demand characteristics = PARTICIPANT figures out the hypothesis; experimenter expectancy = RESEARCHER's hopes leak out.","aliases":["demand characteristic","demand characteristics"],"lookId":"experimenter-expectancy-effect"},{"id":"halo-effect","name":"Halo effect","cat":"effect","area":"social","who":"Edward L. Thorndike","year":"1920","def":"One good trait leads us to rate the person positively on other, unrelated traits too.","detail":"Thorndike found officers' ratings of soldiers' physique, intelligence and leadership were too highly correlated; a classic rating error in appraisals and interviews.","example":"An attractive, well-spoken candidate is assumed also to be honest and hard-working.","look":"Horns effect","tell":"Halo = one GOOD trait shines on everything; horns = one BAD trait darkens everything.","aliases":["halo effect","halo error"],"lookId":"horns-effect"},{"id":"horns-effect","name":"Horns effect (reverse halo)","cat":"effect","area":"social","who":"","year":"","def":"One negative trait leads us to rate the person negatively on other, unrelated traits.","detail":"The negative counterpart of Thorndike's halo effect; also called the devil effect or reverse halo.","example":"A candidate who arrives late is then also judged lazy and incompetent.","look":"Halo effect","tell":"Horns = devil's horns, one BAD trait spreads; halo = angel's halo, one GOOD trait spreads.","aliases":["horns effect","horn effect","reverse halo","devil effect","horns and halo"],"lookId":"halo-effect"},{"id":"contrast-effect","name":"Contrast effect (contrast error)","cat":"effect","area":"social","who":"","year":"","def":"A person or stimulus is judged better or worse than it is because of comparison with what came just before.","detail":"In ratings, an average candidate looks poor after an outstanding one; in perception, lukewarm water feels hot after cold water. Distinct from assimilation, where judgments move toward the anchor.","example":"An average interviewee seems excellent because the previous three were very weak.","look":"Halo effect","tell":"Contrast = judged against the PREVIOUS person; halo = one trait of the SAME person spreads.","aliases":["contrast effect","contrast error"],"lookId":"halo-effect"},{"id":"central-tendency-error","name":"Central tendency error","cat":"effect","area":"research","who":"","year":"","def":"A rater gives everyone middle ratings and avoids the extremes of the scale.","detail":"Produces restricted range and makes good and poor performers look alike; reduced by forced-choice or forced-distribution formats.","example":"A manager rates every employee '3' on a 1-5 scale.","look":"Leniency error","tell":"Central tendency = everyone in the MIDDLE; leniency = everyone at the TOP.","aliases":["central tendency error","central tendency effect","central tendency bias","error of central tendency"],"lookId":"leniency-error"},{"id":"leniency-error","name":"Leniency error","cat":"effect","area":"research","who":"","year":"","def":"A rater gives consistently higher ratings than people deserve.","detail":"Also called generosity error; ratings pile up at the high end, producing a negatively skewed distribution.","example":"A soft examiner gives every viva candidate 9 out of 10.","look":"Severity error","tell":"Leniency = too KIND (all high); severity = too HARSH (all low).","aliases":["leniency error","leniency effect","leniency bias","generosity error","error of leniency"],"lookId":"severity-error"},{"id":"severity-error","name":"Severity error (strictness error)","cat":"effect","area":"research","who":"","year":"","def":"A rater gives consistently lower ratings than people deserve.","detail":"The opposite of leniency error; ratings bunch at the low end of the scale.","example":"A strict examiner never gives anyone more than 5 out of 10.","look":"Leniency error","tell":"Severity = too HARSH; leniency = too KIND.","aliases":["severity error","severity effect","strictness error","harshness error","error of severity"],"lookId":"leniency-error"},{"id":"similar-to-me-error","name":"Similar-to-me error (similarity error)","cat":"effect","area":"research","who":"","year":"","def":"A rater judges people who resemble them (background, attitudes, interests) more favourably.","detail":"A rating and interview error rooted in similarity-attraction; it inflates ratings of in-group members.","example":"An interviewer rates a candidate from his own college higher than an equally good outsider.","look":"Halo effect","tell":"Similar-to-me = liked because like ME; halo = liked because of one good TRAIT.","aliases":["similar-to-me","similar to me error","similar-to-me error","similarity error"],"lookId":"halo-effect"},{"id":"social-desirability-effect","name":"Social desirability effect (bias)","cat":"effect","area":"research","who":"Allen L. Edwards (SD scale); Crowne & Marlowe (scale)","year":"1957","def":"Respondents answer in a way that makes them look good rather than truthfully.","detail":"Edwards showed endorsement of personality items correlates with how desirable they are; measured by the Marlowe-Crowne scale (1960) and lie scales such as MMPI L.","example":"A survey respondent under-reports alcohol use and over-reports voting.","look":"Acquiescence","tell":"Social desirability = answer to LOOK GOOD; acquiescence = answer 'YES' regardless of content.","aliases":["social desirability","social-desirability","faking good"],"lookId":"acquiescence-effect"},{"id":"acquiescence-effect","name":"Acquiescence (yea-saying) response set","cat":"effect","area":"research","who":"Lee J. Cronbach (response sets)","year":"1946","def":"A tendency to agree with statements regardless of their content.","detail":"A response style that inflates scores on positively keyed items; controlled by balancing positively and negatively worded items (reverse keying).","example":"A respondent ticks 'agree' for both 'I love crowds' and 'I avoid crowds'.","look":"Social desirability effect","tell":"Acquiescence = always 'YES'; social desirability = whatever LOOKS GOOD.","aliases":["acquiescence","yea-saying","yea saying","acquiescent response"],"lookId":"social-desirability-bias"},{"id":"social-facilitation","name":"Social facilitation (Triplett effect)","cat":"effect","area":"social","who":"Norman Triplett","year":"1898","def":"The presence of others improves performance on simple or well-learned tasks.","detail":"Triplett found cyclists rode faster with pacers or competitors and children reeled fishing line faster together; the first social psychology experiment. Zajonc (1965): presence raises arousal, helping dominant responses on easy tasks but hurting hard ones (social inhibition). F. H. Allport coined 'social facilitation'.","example":"A trained sprinter runs a personal best in front of a stadium crowd.","look":"Social loafing (Ringelmann effect)","tell":"Facilitation = INDIVIDUAL effort visible, so do better; loafing = effort POOLED, so slack off.","aliases":["social facilitation","triplett effect","triplett","coaction effect","co-action effect"],"lookId":"social-loafing"},{"id":"audience-effect","name":"Audience effect","cat":"effect","area":"social","who":"Robert Zajonc (drive explanation)","year":"1965","def":"Performance changes when passive spectators are watching.","detail":"One of two forms of social facilitation: audience effect (passive watchers) and coaction effect (others doing the same task alongside). Easy tasks improve, hard tasks get worse.","example":"A beginner stammers through a speech when the whole department is watching.","look":"Coaction effect","tell":"Audience = others just WATCHING; coaction = others DOING the same task beside you.","aliases":["audience effect"],"lookId":"social-facilitation"},{"id":"ringelmann-effect","name":"Ringelmann effect","cat":"effect","area":"social","who":"Maximilien Ringelmann","year":"1913","def":"Individual effort drops as group size increases.","detail":"In rope-pulling, groups pulled less than the sum of individuals (about 93% for two, 85% for three, 49% for eight). Latane, Williams and Harkins (1979) later named the motivation part social loafing.","example":"In a tug of war with eight people, each pulls far less hard than when alone.","look":"Social facilitation","tell":"Ringelmann = more people, LESS effort each (rope); Triplett = others present, MORE effort (bicycle).","aliases":["ringelmann","ringlemann","ringelman"],"lookId":"social-facilitation"},{"id":"kohler-effect","name":"Kohler effect","cat":"effect","area":"social","who":"Otto Kohler","year":"1920s","def":"A weaker member works harder in a group because their performance determines the group's result.","detail":"Kohler found weaker rowers and weightlifters held on longer when paired with a stronger partner on a conjunctive task; the opposite of social loafing.","example":"In a relay where the team time depends on the slowest runner, the weakest runner pushes harder.","look":"Social loafing","tell":"Kohler = weak link tries HARDER; loafing = everyone tries LESS.","aliases":["kohler effect","köhler effect","koehler effect"],"lookId":"social-loafing"},{"id":"free-rider-effect","name":"Free-rider effect","cat":"effect","area":"social","who":"Norbert Kerr","year":"1983","def":"A group member contributes less because they believe others' efforts will carry the group anyway.","detail":"Kerr and Bruun showed members slack when they see their own contribution as dispensable; a cause of social loafing.","example":"In a group project one student lets the others write everything and still shares the grade.","look":"Sucker effect","tell":"Free rider = I LET others do it; sucker = I STOP working because I will not be exploited by the free rider.","aliases":["free-rider","free rider","freeriding","free-riding","free riding"],"lookId":"sucker-effect"},{"id":"sucker-effect","name":"Sucker effect","cat":"effect","area":"social","who":"Norbert Kerr","year":"1983","def":"A capable group member reduces their effort to avoid being exploited by others who are slacking.","detail":"A reaction to free riders; people would rather lower output than be 'the sucker' doing all the work.","example":"A hardworking student stops contributing after noticing teammates are coasting.","look":"Free-rider effect","tell":"Sucker = reacting TO free riders; free rider = BEING the one who slacks.","aliases":["sucker effect"],"lookId":"free-rider-effect"},{"id":"barnum-effect","name":"Barnum effect (Forer effect)","cat":"effect","area":"personality","who":"Bertram Forer (experiment); Paul Meehl (named it)","year":"1949","def":"People accept vague, general personality descriptions as accurately describing them personally.","detail":"Forer's students rated an identical horoscope-like sketch about 4.3 out of 5 for accuracy; Meehl (1956) named it after P. T. Barnum. Explains belief in astrology and pop personality tests.","example":"'You have a great deal of unused potential' feels uniquely true to everyone who reads it.","look":"Confirmation bias","tell":"Barnum = VAGUE description feels personal; confirmation bias = seeking evidence that fits your belief.","aliases":["barnum","forer effect","forer","personal validation"],"lookId":"confirmation-bias"},{"id":"spotlight-effect","name":"Spotlight effect","cat":"effect","area":"social","who":"Thomas Gilovich, Victoria Medvec & Kenneth Savitsky","year":"2000","def":"Overestimating how much other people notice our appearance and behaviour.","detail":"Students wearing an embarrassing Barry Manilow T-shirt guessed about half the room noticed; under a quarter actually did.","example":"You think everyone saw you trip on the stairs, but almost nobody did.","look":"Illusion of transparency","tell":"Spotlight = others notice my LOOKS/actions; illusion of transparency = others can read my FEELINGS.","aliases":["spotlight effect"]},{"id":"false-consensus-effect","name":"False consensus effect","cat":"effect","area":"social","who":"Lee Ross, David Greene & Pamela House","year":"1977","def":"Overestimating how many other people share our opinions and behaviours.","detail":"Students who agreed to walk around campus wearing a sandwich-board sign estimated most others would agree; those who refused thought most would refuse.","example":"A smoker assumes most adults smoke.","look":"False uniqueness effect","tell":"False consensus = 'everyone is LIKE me' (opinions, faults); false uniqueness = 'few are as GOOD as me' (abilities, virtues).","aliases":["false consensus","false-consensus"],"lookId":"false-uniqueness-effect"},{"id":"overjustification-effect","name":"Overjustification effect","cat":"effect","area":"social","who":"Mark Lepper, David Greene & Richard Nisbett","year":"1973","def":"Giving an external reward for something people already enjoy reduces their intrinsic motivation to do it.","detail":"Nursery children promised a 'good player' award for drawing with markers later drew less in free play than unrewarded children. Linked to Deci's cognitive evaluation theory.","example":"A child who loved reading reads less once parents start paying per book.","look":"Insufficient justification","tell":"Overjustification = TOO MUCH reward kills liking; insufficient justification = TOO LITTLE reward raises liking (dissonance).","aliases":["overjustification","over-justification","over justification"],"lookId":"cognitive-dissonance"},{"id":"sleeper-effect","name":"Sleeper effect","cat":"effect","area":"social","who":"Carl Hovland (with Weiss)","year":"1951","def":"A message from a low-credibility source becomes more persuasive over time, as the source is forgotten.","detail":"First seen in Hovland, Lumsdaine and Sheffield's WWII film studies (1949); the message and the discounting cue separate in memory (dissociation hypothesis).","example":"A claim you first dismissed because it came from a tabloid seems believable a month later.","look":"Mere exposure effect","tell":"Sleeper = persuasion GROWS with time as SOURCE is forgotten; mere exposure = liking grows with REPEATED exposure.","aliases":["sleeper effect"],"lookId":"mere-exposure-effect"},{"id":"mere-exposure-effect","name":"Mere exposure effect","cat":"effect","area":"social","who":"Robert Zajonc","year":"1968","def":"Repeated exposure to something makes us like it more.","detail":"Zajonc showed nonsense words and Chinese characters were rated more positively the more often they were seen, even without conscious recognition (subliminal exposure works too).","example":"A song you disliked at first grows on you after hearing it daily on the radio.","look":"Propinquity effect","tell":"Mere exposure = REPEATED SEEING breeds liking; propinquity = PHYSICAL NEARNESS breeds friendship.","aliases":["mere exposure","mere-exposure","exposure effect","familiarity principle"],"lookId":"propinquity-effect"},{"id":"propinquity-effect","name":"Propinquity effect","cat":"effect","area":"social","who":"Leon Festinger, Stanley Schachter & Kurt Back","year":"1950","def":"We tend to form friendships and relationships with people who are physically near us.","detail":"In the Westgate housing study, residents were far more likely to befriend next-door neighbours, and people living near stairways and mailboxes made more friends (functional distance).","example":"Your closest hostel friends are the ones in the rooms on either side of yours.","look":"Mere exposure effect","tell":"Propinquity = NEARNESS in space; mere exposure = FREQUENCY of seeing.","aliases":["propinquity","proximity effect"],"roots":"propinquus (Latin) = near","lookId":"mere-exposure-effect"},{"id":"pratfall-effect","name":"Pratfall effect","cat":"effect","area":"social","who":"Elliot Aronson (with Willerman & Floyd)","year":"1966","def":"A highly competent person becomes more likeable after making a small mistake.","detail":"Listeners rated a highly competent quiz contestant as more attractive after he spilled coffee; the same blunder made an average contestant less liked.","example":"A topper who admits forgetting an easy formula seems more relatable.","look":"Ben Franklin effect","tell":"Pratfall = a competent person's BLUNDER raises liking; Ben Franklin = DOING a favour for someone raises your liking for them.","aliases":["pratfall"],"lookId":"ben-franklin-effect"},{"id":"ben-franklin-effect","name":"Ben Franklin effect","cat":"effect","area":"social","who":"Benjamin Franklin (anecdote); Jecker & Landy (experiment)","year":"1969","def":"We come to like a person more after we have done them a favour.","detail":"Explained by cognitive dissonance: 'I helped him, so I must like him.' Franklin won over a rival by asking to borrow a rare book.","example":"After lending a classmate your notes, you start thinking of him as a friend.","look":"Foot-in-the-door technique","tell":"Ben Franklin = favour changes LIKING; foot-in-the-door = small favour increases later COMPLIANCE.","aliases":["ben franklin effect","benjamin franklin effect","franklin effect"],"lookId":"foot-in-the-door"},{"id":"foot-in-the-door","name":"Foot-in-the-door technique","cat":"effect","area":"social","who":"Jonathan Freedman & Scott Fraser","year":"1966","def":"Getting someone to agree to a small request makes them more likely to agree to a larger one later.","detail":"Homeowners who first signed a small 'drive safely' petition were far more likely to later allow a large ugly sign in their yard; explained by self-perception.","example":"First asking to borrow a pen, then later asking to borrow the whole notebook.","look":"Door-in-the-face technique","tell":"Foot-in-the-door = SMALL first, then big; door-in-the-face = HUGE first (refused), then the real one.","aliases":["foot-in-the-door","foot in the door","fitd"],"lookId":"door-in-the-face"},{"id":"door-in-the-face","name":"Door-in-the-face technique","cat":"effect","area":"social","who":"Robert Cialdini and colleagues","year":"1975","def":"Making a large request that will be refused, then a smaller one, increases agreement to the smaller one.","detail":"Students who refused to counsel delinquents for two years weekly were much more likely to then agree to chaperone them to the zoo once; explained by reciprocal concessions.","example":"Asking parents for a new car, then 'settling' for a new phone.","look":"Foot-in-the-door technique","tell":"Door-in-the-face = BIG ask refused first; foot-in-the-door = small ask accepted first.","aliases":["door-in-the-face","door in the face","rejection-then-retreat","rejection then retreat"],"lookId":"foot-in-the-door"},{"id":"lowball-technique","name":"Lowball technique","cat":"effect","area":"social","who":"Robert Cialdini, Cacioppo, Bassett & Miller","year":"1978","def":"Getting agreement to an attractive deal, then raising the cost once the person has committed.","detail":"Students agreed to a study, then learned it started at 7 a.m.; most still turned up because the commitment was already made.","example":"A car dealer agrees a low price, then 'the manager' adds charges after you have decided.","look":"That's-not-all technique","tell":"Lowball = commit FIRST, cost goes UP later; that's-not-all = deal gets SWEETER before you answer.","aliases":["lowball","low-ball","low ball"],"lookId":"thats-not-all"},{"id":"thats-not-all","name":"That's-not-all technique","cat":"effect","area":"social","who":"Jerry Burger","year":"1986","def":"Sweetening an offer with an extra bonus or discount before the person has decided increases compliance.","detail":"Cupcakes sold better when 'two cookies are included' was added after the price than when the cookies were included from the start.","example":"A TV seller says 'and that's not all, you also get a second knife free!'.","look":"Lowball technique","tell":"That's-not-all = offer IMPROVES before you decide; lowball = offer WORSENS after you commit.","aliases":["that's-not-all","that's not all","thats not all","that is not all"],"lookId":"lowball-technique"},{"id":"bandwagon-effect","name":"Bandwagon effect","cat":"effect","area":"social","who":"","year":"","def":"People adopt a belief or behaviour because many others are already doing so.","detail":"Popularity is taken as a sign of correctness; related to informational conformity and herd behaviour, often seen in voting, fashion and markets.","example":"A candidate leading in the polls gains extra votes simply for being in the lead.","look":"False consensus effect","tell":"Bandwagon = I copy the CROWD; false consensus = I assume the crowd copies ME.","aliases":["bandwagon","band-wagon","herd effect"],"lookId":"false-consensus-effect"},{"id":"dunning-kruger-effect","name":"Dunning-Kruger effect","cat":"effect","area":"social","who":"Justin Kruger & David Dunning","year":"1999","def":"People with low ability in a skill overestimate their competence, because they lack the skill to see their mistakes.","detail":"Participants in the bottom quartile on logic, grammar and humour tests scored around the 12th percentile but estimated themselves near the 62nd; training improved both skill and self-assessment.","example":"A first-year student who has read one chapter is sure he knows all of psychiatry.","look":"Better-than-average effect","tell":"Dunning-Kruger = the LEAST skilled overrate MOST (skill-linked); better-than-average = MOST people rate themselves above average.","aliases":["dunning-kruger","dunning kruger"],"lookId":"better-than-average-effect"},{"id":"glass-ceiling","name":"Glass ceiling effect","cat":"effect","area":"social","who":"Marilyn Loden (coined term)","year":"1978","def":"An invisible barrier that stops women and minorities from rising to the top positions in organisations.","detail":"Popularised by a 1986 Wall Street Journal article; the barrier is at the TOP of the ladder, despite qualifications.","example":"A woman reaches senior management but is repeatedly passed over for CEO.","look":"Sticky floor","tell":"Glass ceiling = blocked at the TOP; sticky floor = stuck at the BOTTOM.","aliases":["glass ceiling","glass-ceiling"],"lookId":"sticky-floor"},{"id":"glass-cliff","name":"Glass cliff effect","cat":"effect","area":"social","who":"Michelle Ryan & Alexander Haslam","year":"2005","def":"Women are more likely to be appointed to leadership roles when an organisation is in crisis, making failure likely.","detail":"Ryan and Haslam found FTSE 100 companies appointed women to boards more often after periods of poor performance.","example":"A struggling company appoints its first woman CEO just as it is about to collapse.","look":"Glass ceiling","tell":"Glass cliff = given the top job at the EDGE of failure; glass ceiling = cannot REACH the top job.","aliases":["glass cliff","glass-cliff"],"lookId":"glass-ceiling"},{"id":"sticky-floor","name":"Sticky floor effect","cat":"effect","area":"social","who":"Catherine White Berheide","year":"1992","def":"Women and minorities are kept in low-paying, low-mobility jobs at the bottom of the hierarchy.","detail":"Unlike the glass ceiling, the barrier is at the entry level; workers are 'stuck' in roles with no promotion path.","example":"Women in a factory are kept in clerical grades with no route into supervisor posts.","look":"Glass ceiling","tell":"Sticky floor = stuck at the BOTTOM; glass ceiling = blocked at the TOP; glass cliff = placed at the EDGE.","aliases":["sticky floor","sticky-floor"],"lookId":"glass-ceiling"},{"id":"flynn-effect","name":"Flynn effect","cat":"effect","area":"developmental","who":"James R. Flynn","year":"1984","def":"Average IQ test scores have risen steadily across generations.","detail":"About 3 IQ points per decade in many countries during the 20th century, largest on fluid tests like Raven's; too fast to be genetic, so nutrition, schooling and test familiarity are proposed. Tests must be re-normed.","example":"Today's average child would score well above 100 on IQ norms from the 1950s.","look":"Mozart effect","tell":"Flynn = real, generational IQ RISE; Mozart = brief, disputed spatial boost after music.","aliases":["flynn effect","flynn"],"lookId":"mozart-effect"},{"id":"mozart-effect","name":"Mozart effect","cat":"effect","area":"cognitive","who":"Frances Rauscher, Gordon Shaw & Katherine Ky","year":"1993","def":"A claimed short-term improvement in spatial reasoning after listening to Mozart.","detail":"College students did better on spatial tasks for about 10-15 minutes after a Mozart sonata; later studies attribute it to arousal and mood and failed to show lasting IQ gains.","example":"Parents play Mozart to babies believing it will make them smarter.","look":"Flynn effect","tell":"Mozart = 10-15 minute SPATIAL boost (overhyped); Flynn = decades-long IQ RISE.","aliases":["mozart effect"],"lookId":"flynn-effect"},{"id":"matthew-effect","name":"Matthew effect","cat":"effect","area":"developmental","who":"Robert K. Merton (science); Keith Stanovich (reading)","year":"1968","def":"Those who start with an advantage gain more advantage over time: 'the rich get richer'.","detail":"Merton: famous scientists get more credit for similar work; Stanovich (1986): early good readers read more and pull further ahead, poor readers fall further behind. Named after a verse in Matthew's Gospel.","example":"A child who reads well in class 1 reads more books and the gap with weak readers widens every year.","look":"Pygmalion effect","tell":"Matthew = early ADVANTAGE snowballs; Pygmalion = others' EXPECTATIONS shape performance.","aliases":["matthew effect"],"lookId":"pygmalion-effect"},{"id":"garcia-effect","name":"Garcia effect (conditioned taste aversion)","cat":"effect","area":"learning","who":"John Garcia & Robert Koelling","year":"1966","def":"Learning to avoid a taste after it is followed by illness, often after a single pairing.","detail":"Rats linked taste with nausea but not with shock, and lights/sounds with shock but not nausea (biological preparedness); works even with hours between taste and illness, challenging classical conditioning's contiguity rule.","example":"After getting food poisoning from biryani once, you feel sick at its smell for years.","look":"Classical conditioning (Pavlov)","tell":"Garcia = ONE trial, LONG delay, taste-illness only; ordinary classical conditioning = many trials, short gap.","aliases":["garcia effect","taste aversion","conditioned taste aversion","bait shyness","bait-shyness"],"lookId":"pavlov-dogs"},{"id":"coolidge-effect","name":"Coolidge effect","cat":"effect","area":"biological","who":"Frank A. Beach (named it)","year":"1950s","def":"Renewed sexual interest and performance when a new mate is introduced, after satiation with the old one.","detail":"Shown in male rats and many other mammals; a sexually exhausted male resumes mating when a new receptive female appears. Named after an anecdote about U.S. President Calvin Coolidge.","example":"A satiated male rat ignores its partner but immediately mates when a new female is added.","look":"Westermarck effect","tell":"Coolidge = NOVEL partner revives desire; Westermarck = FAMILIAR childhood companions kill desire.","aliases":["coolidge effect","coolidge"],"lookId":"westermarck-effect"},{"id":"westermarck-effect","name":"Westermarck effect","cat":"effect","area":"developmental","who":"Edvard Westermarck","year":"1891","def":"People raised closely together in early childhood tend not to feel sexual attraction to each other later.","detail":"Proposed as a natural incest-avoidance mechanism; supported by Israeli kibbutz peers (who almost never married each other) and Taiwanese 'minor marriages'.","example":"Children raised together in a kibbutz see each other as siblings and rarely marry.","look":"Coolidge effect","tell":"Westermarck = early FAMILIARITY turns off attraction; Coolidge = NOVELTY turns it on.","aliases":["westermarck","reverse sexual imprinting"],"lookId":"coolidge-effect"},{"id":"baldwin-effect","name":"Baldwin effect","cat":"effect","area":"biological","who":"James Mark Baldwin","year":"1896","def":"Learned behaviours can, over many generations, shape which genes are favoured, so a learned trait may eventually become inborn.","detail":"Not Lamarckian: learning does not alter genes directly; individuals who learn useful behaviour survive, and selection then favours genes that make the behaviour easier to acquire ('organic selection').","example":"A species that learns to crack a new seed gradually evolves stronger beaks suited to it.","look":"Lamarckism (inheritance of acquired characteristics)","tell":"Baldwin = learning guides NATURAL SELECTION; Lamarck = acquired traits passed DIRECTLY to offspring.","aliases":["baldwin effect"]},{"id":"fundamental-attribution-error","name":"Fundamental attribution error","cat":"bias","area":"social","who":"Ross","year":"1977","def":"Over-blaming a person's character and under-weighting the situation when explaining someone else's behaviour.","detail":"Named by Lee Ross (1977). Builds on Jones & Harris (1967): people judged essay writers as truly pro-Castro even when told the side was assigned.","example":"A waiter is slow, so you decide he is lazy, ignoring that he is covering six tables alone.","look":"Actor-observer bias","tell":"FAE is about OTHERS only (dispositional overkill); actor-observer is the SELF vs OTHER contrast (situation for me, trait for you).","aliases":["fundamental attribution error","fundamental attribution","fundamental error","attribution error"],"lookId":"actor-observer-bias"},{"id":"correspondence-bias","name":"Correspondence bias","cat":"bias","area":"social","who":"Jones & Harris; Gilbert & Malone","year":"1967","def":"Inferring that a behaviour corresponds to a matching inner disposition even when the situation clearly caused it.","detail":"Jones & Harris (1967) Castro essay study: observers attributed pro-Castro attitudes to writers who had no choice. Gilbert & Malone (1995) reviewed it as correspondence bias; often treated as a synonym of the FAE.","example":"A debater assigned the 'for' side is assumed to personally hold that view.","look":"Fundamental attribution error","tell":"Correspondence = behaviour 'corresponds' to a trait (Jones & Harris essays); FAE is Ross's 1977 label for the same tendency.","aliases":["correspondence bias","correspondent inference","jones and harris","castro essay"],"lookId":"fundamental-attribution-error"},{"id":"actor-observer-bias","name":"Actor-observer bias","cat":"bias","area":"social","who":"Jones & Nisbett","year":"1971","def":"Explaining your own actions by the situation but other people's identical actions by their personality.","detail":"Jones & Nisbett (1971): actors see the situation, observers see the actor. Storms (1973) reversed it by swapping camera viewpoints on videotape.","example":"I tripped because the floor was wet; you tripped because you are clumsy.","look":"Self-serving bias","tell":"Actor-observer is about perspective (me = situation, any outcome); self-serving depends on OUTCOME (success = me, failure = situation).","aliases":["actor-observer","actor observer","actor-observer bias","actor/observer","actor observer effect"],"lookId":"self-serving-bias"},{"id":"self-serving-bias","name":"Self-serving bias","cat":"bias","area":"social","who":"Miller & Ross","year":"1975","def":"Taking personal credit for successes but blaming outside factors for failures.","detail":"Reviewed by Miller & Ross (1975); protects self-esteem. Classic exam case: students credit ability for a good grade and blame an unfair paper for a bad one.","example":"'I topped because I studied hard; I failed because the questions were out of syllabus.'","look":"Actor-observer bias","tell":"Self-serving flips with success vs failure; actor-observer flips with self vs other.","aliases":["self-serving bias","self serving bias","self-serving attribution","self serving attributional","self-serving"],"lookId":"actor-observer-bias"},{"id":"ultimate-attribution-error","name":"Ultimate attribution error","cat":"bias","area":"social","who":"Pettigrew","year":"1979","def":"The fundamental attribution error applied at group level: out-group failures blamed on their nature, out-group successes explained away.","detail":"Pettigrew (1979) extended Ross's FAE to prejudice: in-group good acts are dispositional, out-group good acts are luck, special advantage or exception.","example":"A minority student tops the class and prejudiced peers say 'he must have got lucky or had help'.","look":"Fundamental attribution error","tell":"Ultimate = group-serving (us vs them, prejudice); fundamental = any single other person.","aliases":["ultimate attribution error","ultimate attribution","pettigrew"],"lookId":"fundamental-attribution-error"},{"id":"defensive-attribution","name":"Defensive attribution","cat":"bias","area":"social","who":"Walster; Shaver","year":"1966","def":"Blaming victims or assigning more responsibility as an accident becomes more serious, to protect our sense that it could not happen to us.","detail":"Walster (1966): the more severe an accident's outcome, the more responsibility observers assigned the driver. Shaver (1970) added that blame drops when the observer feels similar to the person.","example":"After hearing of a serious road crash, people insist the driver must have been reckless.","look":"Just-world bias","tell":"Defensive = self-protection from feeling vulnerable ('could that be me?'); just-world = belief that people get what they deserve.","aliases":["defensive attribution","defensive attribution hypothesis","walster"],"lookId":"just-world-bias"},{"id":"hostile-attribution-bias","name":"Hostile attribution bias","cat":"bias","area":"social","who":"Dodge","year":"1980","def":"Reading hostile intent into others' ambiguous actions.","detail":"Dodge (1980): aggressive boys interpreted ambiguous provocations (e.g., a peer knocking over their blocks) as deliberate; central to his social information processing model of aggression.","example":"A child bumped in a queue assumes it was on purpose and hits back.","look":"Fundamental attribution error","tell":"Hostile attribution = specifically assumes bad INTENT (aggression link, Dodge); FAE = assumes a trait, not necessarily hostile.","aliases":["hostile attribution bias","hostile attribution","hostile attributional bias","hostile intent"],"lookId":"fundamental-attribution-error"},{"id":"confirmation-bias","name":"Confirmation bias","cat":"bias","area":"cognitive","who":"Wason","year":"1960","def":"Seeking, noticing and remembering information that supports what you already believe, and ignoring what contradicts it.","detail":"Wason's 2-4-6 task (1960): people tested only number triples that fit their guessed rule and rarely tried to disconfirm it. Wason selection task (1966) showed the same failure to seek falsifying cards.","example":"A person convinced a colleague dislikes them notices every curt reply and forgets the friendly ones.","look":"Belief perseverance","tell":"Confirmation = how you SEARCH for evidence; perseverance = clinging to a belief AFTER its basis is discredited.","aliases":["confirmation bias","confirmatory bias","2-4-6","wason selection task","myside bias"],"lookId":"belief-perseverance"},{"id":"belief-bias","name":"Belief bias","cat":"bias","area":"cognitive","who":"Evans, Barston & Pollard","year":"1983","def":"Judging an argument's logical validity by whether its conclusion sounds believable.","detail":"Evans, Barston & Pollard (1983): people accepted invalid syllogisms with believable conclusions and rejected valid ones with unbelievable conclusions.","example":"'All flowers need water; roses need water; so roses are flowers' is accepted as valid because the conclusion is true.","look":"Confirmation bias","tell":"Belief bias is about LOGIC (syllogism validity); confirmation bias is about evidence gathering.","aliases":["belief bias","belief-bias effect","syllogistic reasoning bias"],"lookId":"confirmation-bias"},{"id":"belief-perseverance","name":"Belief perseverance","cat":"bias","area":"cognitive","who":"Ross, Lepper & Hubbard","year":"1975","def":"Holding on to a belief even after the evidence that created it has been shown to be false.","detail":"Ross, Lepper & Hubbard (1975): participants given fake feedback on a suicide-note task kept their self-views after debriefing. Anderson, Lepper & Ross (1980) firefighter study: explaining a theory makes it stick. Remedy: explain the opposite.","example":"Told a study linking vaccines to autism was retracted, a parent still believes the link.","look":"Confirmation bias","tell":"Perseverance survives DEBUNKING; confirmation is biased searching before any debunking.","aliases":["belief perseverance","belief persistence","perseverance effect"],"lookId":"confirmation-bias"},{"id":"hindsight-bias","name":"Hindsight bias","cat":"bias","area":"memory","who":"Fischhoff","year":"1975","def":"After learning an outcome, believing you knew it all along.","detail":"Fischhoff (1975): people told an outcome of a historical event rated it as having been more predictable. Also called the I-knew-it-all-along phenomenon (Myers).","example":"After the results, a friend says 'I always knew that team would win.'","look":"Overconfidence","tell":"Hindsight = judging the PAST after the outcome; overconfidence = too sure of judgments BEFORE the outcome.","aliases":["hindsight bias","hindsight effect","knew it all along","i-knew-it-all-along","creeping determinism"],"lookId":"overconfidence"},{"id":"overconfidence","name":"Overconfidence bias","cat":"bias","area":"cognitive","who":"Lichtenstein & Fischhoff","year":"1977","def":"Being more confident in your judgments or knowledge than your accuracy justifies.","detail":"Calibration studies (Lichtenstein, Fischhoff & Phillips): when people say they are 98% sure of an answer, they are wrong far more than 2% of the time.","example":"A student is 'certain' of 20 answers but gets only 14 right.","look":"Planning fallacy","tell":"Overconfidence = accuracy of knowledge/judgments in general; planning fallacy = specifically underestimating task TIME.","aliases":["overconfidence","overconfidence bias","overconfidence effect","miscalibration"],"lookId":"planning-fallacy"},{"id":"optimism-bias","name":"Optimism bias (unrealistic optimism)","cat":"bias","area":"social","who":"Weinstein","year":"1980","def":"Believing good events are more likely and bad events less likely to happen to you than to others.","detail":"Weinstein (1980): students rated themselves as less likely than peers to have a heart attack or get divorced. Linked to risk-taking (no seatbelt, unsafe sex).","example":"'Smokers get cancer, but it won't happen to me.'","look":"Illusion of control","tell":"Optimism bias = rosy ODDS for me; illusion of control = believing I can INFLUENCE chance outcomes.","aliases":["optimism bias","unrealistic optimism","optimistic bias","illusion of invulnerability","personal fable"],"lookId":"illusion-of-control"},{"id":"planning-fallacy","name":"Planning fallacy","cat":"bias","area":"cognitive","who":"Kahneman & Tversky","year":"1979","def":"Underestimating how long, costly or risky a task will be, even when past similar tasks overran.","detail":"Named by Kahneman & Tversky (1979). Buehler, Griffin & Ross (1994): students' thesis completion took far longer than even their 'worst-case' estimates.","example":"You plan to finish a chapter in two hours; as usual it takes six.","look":"Optimism bias","tell":"Planning fallacy = TIME/cost estimates for your own tasks; optimism bias = chances of life events.","aliases":["planning fallacy"],"lookId":"optimism-bias"},{"id":"sunk-cost-fallacy","name":"Sunk cost fallacy","cat":"bias","area":"cognitive","who":"Arkes & Blumer","year":"1985","def":"Continuing to invest in something because of what you have already spent, not because of future value.","detail":"Arkes & Blumer (1985): people who paid more for theatre season tickets attended more plays; ski-trip dilemma. Related to escalation of commitment (Staw, 1976).","example":"You sit through a terrible movie because you paid for the ticket.","look":"Status quo bias","tell":"Sunk cost looks BACK at past investment; status quo prefers no change regardless of past spending.","aliases":["sunk cost","sunk-cost","sunk cost fallacy","sunk cost effect","escalation of commitment","concorde fallacy"],"lookId":"status-quo-bias"},{"id":"status-quo-bias","name":"Status quo bias","cat":"bias","area":"cognitive","who":"Samuelson & Zeckhauser","year":"1988","def":"Preferring things to stay as they are; the current state or default option is chosen disproportionately.","detail":"Samuelson & Zeckhauser (1988) named it. Default effects in organ donation (opt-out countries have far higher consent) show its power.","example":"Employees stay with the default pension plan rather than compare alternatives.","look":"Endowment effect","tell":"Status quo = favouring the current STATE/default; endowment = valuing an OBJECT more because you own it.","aliases":["status quo bias","status-quo bias","default effect","default bias"],"lookId":"endowment-effect"},{"id":"endowment-effect","name":"Endowment effect","cat":"bias","area":"cognitive","who":"Thaler","year":"1980","def":"Valuing something more simply because you own it.","detail":"Named by Thaler (1980). Kahneman, Knetsch & Thaler (1990) mug study: owners demanded about twice what buyers would pay. Explained by loss aversion.","example":"You refuse to sell your old phone for a price you would never pay to buy it.","look":"Loss aversion","tell":"Endowment = the observed owner-price gap; loss aversion = the underlying rule that losses hurt more than gains please.","aliases":["endowment effect","mere ownership effect","mug experiment","wta-wtp"],"lookId":"loss-aversion"},{"id":"loss-aversion","name":"Loss aversion","cat":"bias","area":"cognitive","who":"Kahneman & Tversky","year":"1979","def":"Losses feel roughly twice as powerful as equal-sized gains.","detail":"Core of prospect theory (Kahneman & Tversky, 1979): the value function is steeper for losses. Explains endowment effect, status quo bias and risk-seeking to avoid losses.","example":"Losing Rs 500 upsets you more than finding Rs 500 pleases you.","look":"Framing effect","tell":"Loss aversion = asymmetry in how losses and gains FEEL; framing = the SAME outcome described as loss vs gain changes the choice.","aliases":["loss aversion","loss-aversion","prospect theory","losses loom larger"],"lookId":"framing-effect"},{"id":"framing-effect","name":"Framing effect","cat":"bias","area":"cognitive","who":"Tversky & Kahneman","year":"1981","def":"Making different choices about identical options depending on how they are worded.","detail":"Tversky & Kahneman (1981) Asian disease problem: '200 saved' framing makes people risk-averse; '400 will die' framing makes them risk-seeking, though outcomes are identical.","example":"Surgery with '90% survival' is preferred to surgery with '10% mortality'.","look":"Anchoring and adjustment heuristic","tell":"Framing = WORDING (gain vs loss) of the same facts; anchoring = a starting NUMBER pulls the estimate.","aliases":["framing effect","framing","asian disease problem","gain frame","loss frame"],"lookId":"anchoring-adjustment"},{"id":"anchoring-adjustment","name":"Anchoring and adjustment heuristic","cat":"bias","area":"cognitive","who":"Tversky & Kahneman","year":"1974","def":"Estimating by starting from an initial value (the anchor) and adjusting too little away from it.","detail":"Tversky & Kahneman (1974): a rigged wheel showing 10 or 65 shifted estimates of the percentage of African countries in the UN. Even irrelevant anchors work.","example":"A shop shows Rs 9,999 crossed out, so Rs 4,999 feels cheap.","look":"Framing effect","tell":"Anchoring is driven by a NUMBER you start from; framing is driven by WORDING.","aliases":["anchoring","anchoring heuristic","anchoring and adjustment","anchoring-and-adjustment","anchoring effect","anchoring bias"],"lookId":"framing-effect"},{"id":"availability-heuristic","name":"Availability heuristic","cat":"bias","area":"cognitive","who":"Tversky & Kahneman","year":"1973","def":"Judging how frequent or likely something is by how easily examples come to mind.","detail":"Tversky & Kahneman (1973): people said more words START with K than have K in third position (the reverse is true), because first-letter words are easier to recall. Vivid media events (plane crashes) inflate risk estimates.","example":"After news of a shark attack, people overestimate the danger of swimming at the beach.","look":"Representativeness heuristic","tell":"Availability = ease of RECALL ('how many examples can I think of?'); representativeness = SIMILARITY to a prototype.","aliases":["availability heuristic","availability bias","ease of retrieval","letter k"],"lookId":"representativeness-heuristic"},{"id":"representativeness-heuristic","name":"Representativeness heuristic","cat":"bias","area":"cognitive","who":"Kahneman & Tversky","year":"1972","def":"Judging the probability of something by how much it resembles a typical case, ignoring actual odds.","detail":"Kahneman & Tversky (1972, 1973): the Tom W. and engineer-lawyer problems; people match descriptions to stereotypes and neglect base rates. Underlies the conjunction and gambler's fallacies.","example":"A quiet man who loves poetry is guessed to be a classics professor rather than a truck driver, though truck drivers vastly outnumber classics professors.","look":"Availability heuristic","tell":"Representativeness = 'looks LIKE the type'; availability = 'comes to MIND easily'.","aliases":["representativeness heuristic","representativeness","representative heuristic","tom w"],"lookId":"availability-heuristic"},{"id":"recognition-heuristic","name":"Recognition heuristic","cat":"bias","area":"cognitive","who":"Goldstein & Gigerenzer","year":"2002","def":"If you recognise one of two options and not the other, inferring the recognised one is larger, better or more important.","detail":"Goldstein & Gigerenzer: German students outperformed Americans on 'Which is bigger, San Diego or San Antonio?' because they recognised only San Diego (less-is-more effect). Part of Gigerenzer's fast-and-frugal heuristics.","example":"Asked which of two unknown-to-you companies earns more, you pick the one whose name you have heard.","look":"Availability heuristic","tell":"Recognition = a yes/no 'have I heard of it?' cue between options (Gigerenzer); availability = how many examples come to mind (Tversky & Kahneman).","aliases":["recognition heuristic","fast and frugal","fast-and-frugal","less-is-more effect","take the best","gigerenzer"],"lookId":"availability-heuristic"},{"id":"affect-heuristic","name":"Affect heuristic","cat":"bias","area":"cognitive","who":"Slovic (Finucane et al.)","year":"2000","def":"Letting your current feeling (good or bad) about something drive judgments of its risks and benefits.","detail":"Finucane, Alhakami, Slovic & Johnson (2000): when people like a technology they judge it low-risk AND high-benefit, an inverse relation that does not exist in reality; time pressure strengthens it.","example":"Because you love a sport, you rate its injury risk as low.","look":"Availability heuristic","tell":"Affect = 'how do I FEEL about it?'; availability = 'how easily do examples come to mind?'.","aliases":["affect heuristic","affective heuristic","emotion heuristic"],"lookId":"availability-heuristic"},{"id":"simulation-heuristic","name":"Simulation heuristic","cat":"bias","area":"cognitive","who":"Kahneman & Tversky","year":"1982","def":"Judging likelihood or emotional impact by how easily you can mentally imagine (simulate) an alternative outcome.","detail":"Kahneman & Tversky (1982): Mr. Crane and Mr. Tees both miss flights; the one who missed by 5 minutes is judged more upset because the alternative is easier to imagine. Basis of counterfactual thinking research.","example":"Bronze medallists often look happier than silver medallists, who can easily imagine winning gold.","look":"Availability heuristic","tell":"Simulation = ease of IMAGINING a scenario that has not happened; availability = ease of RECALLING instances.","aliases":["simulation heuristic","mr crane and mr tees","mental simulation"],"lookId":"availability-heuristic"},{"id":"base-rate-fallacy","name":"Base-rate fallacy (base-rate neglect)","cat":"bias","area":"cognitive","who":"Kahneman & Tversky","year":"1973","def":"Ignoring the general frequency (base rate) of something and relying on specific case details instead.","detail":"Kahneman & Tversky (1973) engineer-lawyer problem: told a sample was 70% lawyers, people still judged a stereotypical 'engineer' description by resemblance alone. Taxicab problem and medical-test errors are classic forms.","example":"A test for a rare disease is 99% accurate, so a positive result is assumed to mean 99% chance of disease, ignoring that the disease affects 1 in 10,000.","look":"Conjunction fallacy","tell":"Base-rate = ignoring PRIOR odds; conjunction = rating 'A and B' as more likely than 'A' alone.","aliases":["base-rate fallacy","base rate fallacy","base-rate neglect","base rate neglect","engineer-lawyer","taxicab problem"],"lookId":"conjunction-fallacy"},{"id":"conjunction-fallacy","name":"Conjunction fallacy","cat":"bias","area":"cognitive","who":"Tversky & Kahneman","year":"1983","def":"Judging a combination of two events as more likely than one of them alone, which is mathematically impossible.","detail":"Tversky & Kahneman (1983) Linda problem: Linda, a former philosophy student and activist, is rated more likely to be 'a bank teller AND feminist' than 'a bank teller'. Driven by representativeness.","example":"Thinking 'a Delhi student who loves music and plays guitar' is likelier than 'a Delhi student who plays guitar'.","look":"Base-rate fallacy","tell":"Conjunction = A-and-B beats A (Linda); base-rate = prior frequencies ignored (engineer-lawyer).","aliases":["conjunction fallacy","conjunction effect","linda problem","linda the bank teller"],"lookId":"base-rate-fallacy"},{"id":"gamblers-fallacy","name":"Gambler's fallacy","cat":"bias","area":"cognitive","who":"","year":"","def":"Believing that past independent random events change the odds of the next one, so a 'due' outcome becomes likelier.","detail":"Explained by Tversky & Kahneman as representativeness: people expect even short random runs to look balanced (law of small numbers). The Monte Carlo casino 1913 roulette run is the folk example.","example":"After five heads in a row, a person bets on tails because it is 'due'.","look":"Hot-hand fallacy","tell":"Gambler's = expects a streak to REVERSE; hot hand = expects a streak to CONTINUE.","aliases":["gambler's fallacy","gamblers fallacy","gambler fallacy","monte carlo fallacy","negative recency"],"lookId":"hot-hand-fallacy"},{"id":"hot-hand-fallacy","name":"Hot-hand fallacy","cat":"bias","area":"cognitive","who":"Gilovich, Vallone & Tversky","year":"1985","def":"Believing a person who has succeeded several times in a row is more likely to succeed next time, in a chance process.","detail":"Gilovich, Vallone & Tversky (1985) analysed basketball shooting records and found no greater chance of a hit after a hit, though players and fans believed in streaks.","example":"A batsman hit three sixes, so fans 'know' the next ball will be a six too.","look":"Gambler's fallacy","tell":"Hot hand = streak will CONTINUE; gambler's = streak will END.","aliases":["hot hand","hot-hand","hot hand fallacy","hot-hand fallacy","positive recency"],"lookId":"gamblers-fallacy"},{"id":"law-of-small-numbers","name":"Belief in the law of small numbers","cat":"bias","area":"research","who":"Tversky & Kahneman","year":"1971","def":"Expecting small samples to mirror the population as closely as large samples do.","detail":"Tversky & Kahneman (1971) showed even trained psychologists overtrusted small-sample results and expected replications to succeed; it underlies the gambler's fallacy and insensitivity to sample size.","example":"A researcher sees a large effect in 10 participants and is sure it will replicate exactly.","look":"Gambler's fallacy","tell":"Law of small numbers = overtrusting SMALL SAMPLES; gambler's fallacy is one consequence applied to chance sequences.","aliases":["law of small numbers","insensitivity to sample size","small sample bias"],"lookId":"gamblers-fallacy"},{"id":"illusory-correlation","name":"Illusory correlation","cat":"bias","area":"cognitive","who":"Chapman & Chapman","year":"1967","def":"Perceiving a relationship between two variables where none exists, or a stronger one than really exists.","detail":"Chapman & Chapman (1967): clinicians and students 'saw' links between Draw-a-Person features (e.g., big eyes) and paranoia that were not in the data; repeated for Rorschach signs (1969). Hamilton & Gifford (1976) linked it to stereotypes of minorities.","example":"Believing more babies are born on full-moon nights because those nights are memorable.","look":"Confirmation bias","tell":"Illusory correlation = seeing a LINK between two variables that is not there; confirmation = searching for support for any belief.","aliases":["illusory correlation","illusory correlations","draw-a-person","chapman and chapman"],"lookId":"confirmation-bias"},{"id":"illusion-of-control","name":"Illusion of control","cat":"bias","area":"cognitive","who":"Langer","year":"1975","def":"Believing you can influence outcomes that are actually determined by chance.","detail":"Langer (1975): people who chose their own lottery ticket demanded more money to sell it than those handed one. Dice players throw softly for low numbers, hard for high.","example":"A gambler blows on the dice before rolling to 'help' get a six.","look":"Optimism bias","tell":"Illusion of control = belief in PERSONAL INFLUENCE over chance; optimism = believing good things are likelier for you.","aliases":["illusion of control","illusory control","langer lottery"],"lookId":"optimism-bias"},{"id":"just-world-bias","name":"Just-world bias (just-world hypothesis)","cat":"bias","area":"social","who":"Lerner","year":"1966","def":"Believing the world is fair, so people get what they deserve and deserve what they get; this leads to blaming victims.","detail":"Lerner & Simmons (1966): observers who watched a woman receive apparent shocks and could not help her rated her less favourably. Lerner developed the just-world hypothesis (1980 book). Also called just-world phenomenon or belief.","example":"'She must have done something to provoke the attack.'","look":"Defensive attribution","tell":"Just-world = belief that outcomes are DESERVED; defensive attribution = blaming to feel SAFE ('it can't happen to me').","aliases":["just-world","just world","just-world hypothesis","just world hypothesis","just-world phenomenon","belief in a just world","victim blaming","blaming the victim"],"lookId":"defensive-attribution"},{"id":"in-group-bias","name":"In-group bias (in-group favouritism)","cat":"bias","area":"social","who":"Tajfel","year":"1970","def":"Favouring members of your own group over outsiders, even when groups are trivial.","detail":"Tajfel's minimal group paradigm (1970-71): boys split by 'Klee vs Kandinsky' preference allocated more points to their own group, even at a cost to absolute gain. Explained by social identity theory (Tajfel & Turner, 1979).","example":"Students rate their own hostel's fest as better than other hostels' without having attended them.","look":"Out-group homogeneity effect","tell":"In-group bias = we are BETTER; out-group homogeneity = they are all ALIKE.","aliases":["in-group bias","ingroup bias","in-group favoritism","in-group favouritism","ingroup favoritism","minimal group","klee and kandinsky","intergroup bias"],"lookId":"out-group-homogeneity"},{"id":"out-group-homogeneity","name":"Out-group homogeneity effect","cat":"bias","area":"social","who":"Quattrone & Jones","year":"1980","def":"Seeing members of other groups as more similar to each other than members of your own group.","detail":"Quattrone & Jones (1980): Princeton and Rutgers students saw the other university's students as more alike. Linked to the cross-race effect in face recognition.","example":"'They all look the same and think the same, but we are all different.'","look":"In-group bias","tell":"Out-group homogeneity is about perceived VARIABILITY; in-group bias is about EVALUATION (favouring).","aliases":["out-group homogeneity","outgroup homogeneity","out-group homogeneity effect","outgroup homogeneity bias","they are all alike"],"lookId":"in-group-bias"},{"id":"false-uniqueness-effect","name":"False uniqueness effect","cat":"bias","area":"social","who":"","year":"","def":"Underestimating how common your good abilities and desirable behaviours are, seeing them as rarer than they are.","detail":"Described by Goethals and colleagues; Myers pairs it with false consensus: we see our failings as common but our talents and virtues as unusual.","example":"A volunteer believes very few people would donate blood like they do.","look":"False consensus effect","tell":"Uniqueness = my GOOD traits are rare; consensus = my opinions and BAD habits are common.","aliases":["false uniqueness","false-uniqueness","false uniqueness effect","false uniqueness bias"],"lookId":"false-consensus-effect"},{"id":"better-than-average-effect","name":"Better-than-average effect (illusory superiority)","cat":"bias","area":"social","who":"Svenson; Alicke","year":"1981","def":"Most people rate themselves above average on desirable traits and abilities, which cannot be true for most.","detail":"Svenson (1981): about 93% of US drivers rated themselves above the median in skill. Alicke (1985) extended it to many traits. Also called the Lake Wobegon effect.","example":"Nearly every student believes they are more ethical than the average student.","look":"Self-serving bias","tell":"Better-than-average = COMPARING self to peers; self-serving = EXPLAINING (attributing) your own outcomes.","aliases":["better-than-average","better than average","illusory superiority","above-average effect","lake wobegon","superiority bias"],"lookId":"self-serving-bias"},{"id":"self-enhancement","name":"Self-enhancement bias (positive illusions)","cat":"bias","area":"social","who":"Taylor & Brown","year":"1988","def":"The motive and tendency to view yourself in an unrealistically favourable light.","detail":"Taylor & Brown (1988) argued that mild positive illusions (inflated self-views, exaggerated control, unrealistic optimism) support mental health; mildly depressed people judge more accurately (depressive realism).","example":"You remember your contribution to a group project as bigger and better than it was.","look":"Better-than-average effect","tell":"Self-enhancement is the broad MOTIVE (umbrella); better-than-average is one specific comparison effect.","aliases":["self-enhancement","self enhancement","self-enhancement bias","positive illusions","positive illusion"],"lookId":"better-than-average-effect"},{"id":"egocentric-bias","name":"Egocentric bias","cat":"bias","area":"social","who":"Ross & Sicoly","year":"1979","def":"Overestimating your own role or contribution, or relying too heavily on your own perspective.","detail":"Ross & Sicoly (1979): husbands and wives each claimed more than their share of household tasks; summed estimates exceeded 100%. Own contributions are more available in memory.","example":"Two roommates each say they do 70% of the cleaning.","look":"Self-serving bias","tell":"Egocentric = 'I did MORE' (bigger role, even for bad things); self-serving = credit for good, blame elsewhere for bad.","aliases":["egocentric bias","egocentrism bias","egocentric attribution","responsibility allocation"],"lookId":"self-serving-bias"},{"id":"trait-ascription-bias","name":"Trait ascription bias","cat":"bias","area":"social","who":"Kammer","year":"1982","def":"Seeing yourself as variable and flexible across situations, but others as fixed and predictable in their traits.","detail":"Kammer (1982): people rated their own trait scores as more variable across situations than those of friends. Related to the actor-observer bias.","example":"'I am quiet sometimes and outgoing at other times, but Rahul is just an introvert.'","look":"Actor-observer bias","tell":"Trait ascription = others have FIXED traits, I am variable; actor-observer = situation explains me, traits explain others.","aliases":["trait ascription bias","trait ascription","trait-ascription"],"lookId":"actor-observer-bias"},{"id":"negativity-bias","name":"Negativity bias","cat":"bias","area":"cognitive","who":"Rozin & Royzman","year":"2001","def":"Negative information, events and emotions have a stronger impact than equally intense positive ones.","detail":"Rozin & Royzman (2001) and Baumeister et al. (2001, 'Bad is stronger than good'): one cruel remark outweighs several compliments; negative traits weigh more in impression formation.","example":"Out of twenty good feedback comments, you keep thinking about the one criticism.","look":"Positivity bias","tell":"Negativity = bad things WEIGH more; positivity = we tend to REPORT and rate things favourably.","aliases":["negativity bias","negativity effect","bad is stronger than good"],"lookId":"positivity-bias"},{"id":"positivity-bias","name":"Positivity bias (Pollyanna principle)","cat":"bias","area":"cognitive","who":"Matlin & Stang","year":"1978","def":"A general tendency to rate, recall and describe things more favourably than neutral, and to process pleasant information more easily.","detail":"Matlin & Stang (1978) Pollyanna principle: pleasant items are recalled and processed more accurately; person positivity bias (Sears, 1983) means individuals are rated better than their groups. Older adults show it in memory (Carstensen).","example":"Most people rate an unknown stranger slightly above neutral.","look":"Negativity bias","tell":"Positivity = default favourable RATING and recall; negativity = negative events have stronger IMPACT.","aliases":["positivity bias","positivity effect","pollyanna principle","pollyanna effect","person positivity bias"],"lookId":"negativity-bias"},{"id":"attentional-bias","name":"Attentional bias","cat":"bias","area":"clinical","who":"MacLeod, Mathews & Tata","year":"1986","def":"Attention being automatically drawn to certain stimuli, especially threat in anxiety or substance cues in addiction.","detail":"MacLeod, Mathews & Tata (1986) dot-probe task: anxious people responded faster to probes replacing threat words. Emotional Stroop shows the same; basis of attention bias modification therapy.","example":"A person with spider phobia spots a tiny spider on the wall before anyone else in the room.","look":"Confirmation bias","tell":"Attentional bias is automatic, perceptual capture by emotional STIMULI; confirmation is a reasoning bias about beliefs.","aliases":["attentional bias","attention bias","dot-probe","dot probe","emotional stroop"],"lookId":"confirmation-bias"},{"id":"recall-bias","name":"Recall bias","cat":"bias","area":"research","who":"","year":"","def":"Systematic error caused by participants remembering past exposures or events inaccurately or selectively.","detail":"Classic threat in retrospective and case-control studies: cases (e.g., mothers of children with birth defects) search memory harder than controls, inflating apparent associations.","example":"Patients with lung disease recall past dust exposure in more detail than healthy controls.","look":"Hindsight bias","tell":"Recall bias is a RESEARCH data-quality error in self-reported past exposures; hindsight is believing you predicted an outcome.","aliases":["recall bias","recall error","memory bias in retrospective"],"lookId":"hindsight-bias"},{"id":"selection-bias","name":"Selection bias","cat":"bias","area":"research","who":"","year":"","def":"Error that arises when the people in a study, or in the compared groups, are systematically different from those they are meant to represent.","detail":"Includes non-random assignment to groups (threat to internal validity, Campbell & Stanley) and unrepresentative inclusion. Randomisation is the main cure.","example":"Comparing therapy volunteers with non-volunteers: the volunteers were already more motivated.","look":"Sampling bias","tell":"Selection bias = how participants get INTO groups/study (internal validity); sampling bias = sample does not REPRESENT population (external validity).","aliases":["selection bias","selection effect","differential selection"],"lookId":"sampling-bias"},{"id":"sampling-bias","name":"Sampling bias","cat":"bias","area":"research","who":"","year":"","def":"A sample that over- or under-represents certain parts of the population, so results do not generalise.","detail":"The 1936 Literary Digest poll predicted Landon would beat Roosevelt because it sampled car and telephone owners. Random sampling is the cure; a bigger biased sample does not help.","example":"An online survey on internet use concludes everyone is online.","look":"Selection bias","tell":"Sampling bias is about REPRESENTATIVENESS of the sample; selection bias also covers how groups are formed.","aliases":["sampling bias","biased sample","biased sampling","literary digest","unrepresentative sample"],"lookId":"selection-bias"},{"id":"publication-bias","name":"Publication bias (file-drawer problem)","cat":"bias","area":"research","who":"Rosenthal","year":"1979","def":"Studies with significant or positive results are more likely to be published than null results, distorting the literature.","detail":"Rosenthal (1979) named the file-drawer problem: null studies stay in drawers, so meta-analyses overestimate effects. Detected with funnel plots and fail-safe N.","example":"Twenty labs test a drug; the one that finds an effect is published and the nineteen null results are not.","look":"Selection bias","tell":"Publication bias filters STUDIES (what gets published); selection bias filters PARTICIPANTS.","aliases":["publication bias","file drawer","file-drawer","file drawer problem","funnel plot","fail-safe n"],"lookId":"selection-bias"},{"id":"experimenter-bias","name":"Experimenter bias (expectancy effect)","cat":"bias","area":"research","who":"Rosenthal","year":"1963","def":"The researcher's expectations unintentionally influence participants' behaviour or the recording of results.","detail":"Rosenthal & Fode (1963): students told their rats were 'maze-bright' got better maze performance than those told 'maze-dull', though rats were randomly assigned. Controlled by double-blind procedures.","example":"An experimenter who expects the drug group to improve smiles more when testing them.","look":"Observer bias","tell":"Experimenter bias changes what PARTICIPANTS do (via the researcher); observer bias changes what is RECORDED.","aliases":["experimenter bias","experimenter effect","experimenter expectancy","expectancy effect","rosenthal effect","maze-bright","maze bright"],"lookId":"observer-bias"},{"id":"observer-bias","name":"Observer bias","cat":"bias","area":"research","who":"","year":"","def":"Observers' expectations or knowledge distorting how they see and record behaviour.","detail":"Common in naturalistic observation and rating; reduced by blind observers, clear operational definitions and checking inter-rater reliability.","example":"A rater who knows which children are 'ADHD' codes more fidgeting for them.","look":"Experimenter bias","tell":"Observer bias = distortion in RECORDING/perceiving; experimenter bias = researcher's expectations change participants' actual behaviour.","aliases":["observer bias","observer effect","observer expectancy","detection bias"],"lookId":"experimenter-expectancy-effect"},{"id":"response-bias","name":"Response bias (response set)","cat":"bias","area":"research","who":"Cronbach","year":"1946","def":"A systematic tendency to answer questions in a particular way regardless of their content.","detail":"Cronbach (1946) described response sets as threats to test validity. Umbrella for acquiescence, social desirability, extreme and central tendency responding.","example":"A respondent picks the middle option on every Likert item.","look":"Social desirability bias","tell":"Response bias is the UMBRELLA (any content-independent answering style); social desirability is one type (looking good).","aliases":["response bias","response set","response sets","response style","response styles","extreme responding"],"lookId":"social-desirability-bias"},{"id":"social-desirability-bias","name":"Social desirability bias","cat":"bias","area":"research","who":"Edwards; Crowne & Marlowe","year":"1957","def":"Answering in a way that makes you look good rather than truthfully.","detail":"Edwards (1957) built a social desirability scale; the Marlowe-Crowne Social Desirability Scale (1960) detects it. Controlled by anonymity, lie scales (MMPI L scale) and forced-choice items.","example":"In a survey, a smoker under-reports cigarettes per day.","look":"Acquiescence bias","tell":"Social desirability = answers that look GOOD; acquiescence = saying YES regardless of content.","aliases":["social desirability","social desirability bias","social desirability effect","social-desirability","faking good","marlowe-crowne","impression management"],"lookId":"acquiescence-bias"},{"id":"acquiescence-bias","name":"Acquiescence bias (yea-saying)","cat":"bias","area":"research","who":"Couch & Keniston","year":"1960","def":"Tendency to agree with statements regardless of their content.","detail":"Couch & Keniston (1960) studied 'yeasayers and naysayers'. Controlled by balanced scales with reverse-keyed items.","example":"A respondent agrees with both 'I am outgoing' and 'I am shy'.","look":"Social desirability bias","tell":"Acquiescence = agree with ANYTHING; social desirability = choose whatever looks GOOD.","aliases":["acquiescence","acquiescence bias","acquiescence effect","acquiescent response","yea-saying","yea saying","yeasayer","agreement bias"],"lookId":"social-desirability-bias"},{"id":"volunteer-bias","name":"Volunteer bias","cat":"bias","area":"research","who":"Rosenthal & Rosnow","year":"1975","def":"People who volunteer for studies differ systematically from those who do not, limiting generalisation.","detail":"Rosenthal & Rosnow (1975), 'The Volunteer Subject': volunteers tend to be better educated, higher in need for approval and more sociable. A form of self-selection bias.","example":"A sleep study recruits via a poster; only insomniacs keen for help sign up.","look":"Sampling bias","tell":"Volunteer bias = participants SELF-SELECT; sampling bias = the researcher's sampling method is unrepresentative.","aliases":["volunteer bias","self-selection bias","self selection bias","volunteer subject"],"lookId":"sampling-bias"},{"id":"survivorship-bias","name":"Survivorship bias","cat":"bias","area":"research","who":"","year":"","def":"Drawing conclusions only from cases that 'survived' a selection process, ignoring those that dropped out or failed.","detail":"Wartime example attributed to statistician Abraham Wald: armour was recommended where returning bombers had NO bullet holes, since planes hit there never came back.","example":"'College dropouts become billionaires' based only on famous successful dropouts.","look":"Attrition bias","tell":"Survivorship = only SUCCESSFUL cases are visible to begin with; attrition = participants DROP OUT during a study.","aliases":["survivorship bias","survivor bias","survivorship","abraham wald"],"lookId":"attrition-bias"},{"id":"attrition-bias","name":"Attrition bias","cat":"bias","area":"research","who":"","year":"","def":"Bias caused when participants who drop out of a study differ systematically from those who stay.","detail":"A threat in longitudinal studies and RCTs (experimental mortality in Campbell & Stanley's list). Handled by intention-to-treat analysis.","example":"Patients who felt worse quit a therapy trial, so the remaining group looks more improved.","look":"Survivorship bias","tell":"Attrition = DROPOUT during a study; survivorship = only survivors were ever sampled.","aliases":["attrition bias","experimental mortality","differential attrition","dropout bias","mortality threat"],"lookId":"survivorship-bias"},{"id":"implicit-bias","name":"Implicit bias","cat":"bias","area":"social","who":"Greenwald, McGhee & Schwartz","year":"1998","def":"Automatic, unconscious attitudes or stereotypes that affect judgment without awareness.","detail":"Greenwald & Banaji (1995) framed implicit social cognition; Greenwald, McGhee & Schwartz (1998) created the Implicit Association Test (IAT), measuring faster pairing of concepts (e.g., White + good).","example":"A recruiter who believes in equality still rates identical resumes higher when the name sounds upper-caste.","look":"In-group bias","tell":"Implicit = UNCONSCIOUS, measured by reaction time (IAT); in-group bias can be fully conscious and openly stated.","aliases":["implicit bias","implicit association test","implicit attitude","implicit attitudes","unconscious bias"],"lookId":"in-group-bias"},{"id":"cultural-bias-testing","name":"Cultural bias in testing","cat":"bias","area":"research","who":"","year":"","def":"A test favouring one cultural group because its content, language or norms reflect that group's experience.","detail":"Led to culture-fair and culture-free tests such as Cattell's Culture Fair Intelligence Test and Raven's Progressive Matrices; Dove's 'Chitling Test' (1968) satirised it.","example":"An IQ item asking about snowfall or baseball disadvantages a rural Indian child.","look":"Sampling bias","tell":"Cultural bias = the TEST content favours a group; sampling bias = the PEOPLE studied are unrepresentative.","aliases":["cultural bias","culture bias","test bias","culture-fair","culture fair","culture-free","chitling test"],"lookId":"sampling-bias"},{"id":"bias-blind-spot","name":"Bias blind spot","cat":"bias","area":"social","who":"Pronin, Lin & Ross","year":"2002","def":"Recognising biases in other people while believing you are less biased yourself.","detail":"Pronin, Lin & Ross (2002): people rated themselves less susceptible than the average person to a list of biases, even after learning about them. Rooted in introspection illusion.","example":"After reading about confirmation bias, a student says 'Others do that, but I am objective.'","look":"Naive realism","tell":"Blind spot = 'YOU are biased, I am not'; naive realism = 'I see the world as it really is', the belief that drives it.","aliases":["bias blind spot","blind spot bias","introspection illusion"],"lookId":"naive-realism"},{"id":"naive-realism","name":"Naive realism","cat":"bias","area":"social","who":"Ross & Ward","year":"1996","def":"Believing you see the world objectively, so anyone who disagrees must be uninformed, irrational or biased.","detail":"Ross & Ward (1996) formalised it; Hastorf & Cantril (1954) 'They saw a game' showed Princeton and Dartmouth fans seeing different fouls in the same football film. Hostile media effect (Vallone, Ross & Lepper, 1985) follows from it.","example":"Supporters of two parties watch the same debate and each think the moderator favoured the other side.","look":"Bias blind spot","tell":"Naive realism = MY view is objective reality; blind spot = applying bias labels to others but not to me.","aliases":["naive realism","naïve realism","they saw a game","hostile media"],"lookId":"bias-blind-spot"},{"id":"groupthink","name":"Groupthink","cat":"phenomenon","area":"social","who":"Irving Janis","year":"1972","def":"A cohesive group's drive for agreement overrides realistic appraisal of alternatives, producing bad decisions.","detail":"Janis studied fiascos like the Bay of Pigs. Symptoms: illusion of invulnerability, collective rationalization, belief in the group's inherent morality, stereotyped view of opponents, pressure on dissenters, self-censorship, illusion of unanimity, self-appointed mindguards.","example":"A tight-knit cabinet approves an invasion plan because nobody wants to break the warm consensus.","look":"Group polarization","tell":"Groupthink = the group seeks HARMONY and stops thinking; polarization = the group's existing leaning gets more EXTREME after discussion.","aliases":["groupthink","group think","janis groupthink","mindguards","illusion of unanimity"],"lookId":"group-polarization"},{"id":"group-polarization","name":"Group polarization","cat":"phenomenon","area":"social","who":"Serge Moscovici & Marisa Zavalloni","year":"1969","def":"After group discussion, members' average opinion becomes more extreme in the direction it already leaned.","detail":"Generalises the risky shift: cautious groups become more cautious, risky groups riskier. Explained by persuasive arguments (informational) and social comparison (normative). Moscovici & Zavalloni showed French students' attitudes toward de Gaulle and Americans intensified after discussion.","example":"Mildly prejudiced students who discuss race together come out more prejudiced; tolerant ones come out more tolerant.","look":"Risky shift","tell":"Risky shift = always toward RISK (Stoner); polarization = toward whichever pole the group ALREADY favoured.","aliases":["group polarization","group polarisation","polarization of groups","attitude polarization"],"lookId":"risky-shift"},{"id":"risky-shift","name":"Risky shift","cat":"phenomenon","area":"social","who":"James Stoner","year":"1961","def":"The finding that groups make riskier decisions than the average of their members' individual decisions.","detail":"Found by Stoner in an MIT master's thesis using choice-dilemma items. Later work found shifts toward caution too, so it was reframed as group polarization.","example":"Individually each manager would bet small, but after a meeting the team backs the high-risk venture.","look":"Group polarization","tell":"Stoner's 1961 shift is the special case; Moscovici's polarization is the general rule (it can shift to caution too).","aliases":["risky shift","risky-shift","risky shift phenomenon","choice shift"],"lookId":"group-polarization"},{"id":"social-loafing","name":"Social loafing","cat":"phenomenon","area":"social","who":"Bibb Latane, Kipling Williams & Stephen Harkins","year":"1979","def":"People exert less effort when working in a group whose output is pooled than when working alone.","detail":"Latane et al. had people clap and shout alone or in groups; per-person noise fell as group size grew. Builds on Ringelmann's rope-pulling observation (Ringelmann effect). Reduced when individual output is identifiable or the task matters. Related: free-rider effect (Kerr).","example":"In a five-person class project, two members coast because the grade is shared.","look":"Social facilitation","tell":"Loafing = pooled, unidentifiable effort, so effort DROPS; facilitation = individual performance in front of others, so dominant responses RISE.","aliases":["social loafing","ringelmann effect","free-rider effect","free rider effect","freeriding effect","free riding"],"lookId":"social-facilitation"},{"id":"bystander-effect","name":"Bystander effect","cat":"phenomenon","area":"social","who":"John Darley & Bibb Latane","year":"1968","def":"The more bystanders present at an emergency, the less likely any one of them is to help.","detail":"Triggered by the 1964 Kitty Genovese murder. In Darley & Latane's seizure study, 85% helped when alone vs 31% when they thought four others heard. Five-step decision model: notice, interpret as emergency, assume responsibility, know how to help, decide to help.","example":"A man collapses on a crowded railway platform and dozens walk past assuming someone else will act.","look":"Diffusion of responsibility","tell":"Bystander effect is the OUTCOME (less helping in crowds); diffusion of responsibility is one CAUSE behind it.","aliases":["bystander effect","bystander apathy","bystander intervention","genovese syndrome","kitty genovese"],"lookId":"diffusion-of-responsibility"},{"id":"diffusion-of-responsibility","name":"Diffusion of responsibility","cat":"phenomenon","area":"social","who":"John Darley & Bibb Latane","year":"1968","def":"When others are present, each person feels less personally responsible to act.","detail":"The main explanation for the bystander effect in the seizure (intercom) study; it also contributes to social loafing and to obedience when an authority 'takes responsibility'.","example":"In a WhatsApp group of 200, nobody answers a question because each assumes another member will.","look":"Bystander effect","tell":"Diffusion = the inner feeling 'not my job'; bystander effect = the observable failure to help.","aliases":["diffusion of responsibility","responsibility diffusion"],"lookId":"bystander-effect"},{"id":"pluralistic-ignorance","name":"Pluralistic ignorance","cat":"phenomenon","area":"social","who":"Floyd Allport & Daniel Katz (term); Latane & Darley (bystander work)","year":"1931","def":"Each person privately doubts a norm but wrongly assumes everyone else accepts it, so all go along.","detail":"In Latane & Darley's smoke-filled room study (1968), only 38% of people in groups reported smoke vs 75% alone, because everyone read others' calm faces as 'no emergency'.","example":"No student asks a question in class because everyone sees others looking calm and assumes only they are confused.","look":"False consensus effect","tell":"Pluralistic ignorance = I think others DISAGREE with my private view; false consensus = I think others AGREE with me.","aliases":["pluralistic ignorance"],"lookId":"false-consensus-effect"},{"id":"deindividuation","name":"Deindividuation","cat":"phenomenon","area":"social","who":"Leon Festinger, Albert Pepitone & Theodore Newcomb; later Philip Zimbardo, Ed Diener","year":"1952","def":"Loss of self-awareness and personal responsibility in groups or under anonymity, which releases normally restrained behaviour.","detail":"Coined by Festinger, Pepitone & Newcomb (1952). Zimbardo (1969) found hooded anonymous women gave longer shocks. Diener et al. (1976) found trick-or-treaters in anonymous groups stole more Halloween candy. Fed by anonymity, arousal, group size.","example":"Masked rioters loot shops they would never touch alone.","look":"Social loafing","tell":"Deindividuation = anonymity unleashes ANTISOCIAL or impulsive acts; loafing = anonymity just lowers EFFORT.","aliases":["deindividuation","de-individuation","deindividuated"],"roots":"de- (removal of) + individuation (being a distinct individual): losing your sense of being a separate self","lookId":"social-loafing"},{"id":"conformity","name":"Conformity","cat":"phenomenon","area":"social","who":"Solomon Asch; Muzafer Sherif","year":"1951","def":"Changing one's behaviour or belief to match a group, without any direct request.","detail":"Asch's line-judgement study: about 75% conformed at least once and about 37% of critical trials were conforming; one dissenting ally cut conformity sharply. Normative (to be liked) vs informational (to be right, Sherif's autokinetic study) influence.","example":"You pick the wrong answer aloud because the six students before you all gave it.","look":"Obedience","tell":"Conformity = PEERS, no command given; obedience = an AUTHORITY gives a direct order.","aliases":["conformity","group conformity","asch conformity","asch line experiment","normative influence","informational influence"],"lookId":"obedience"},{"id":"obedience","name":"Obedience","cat":"phenomenon","area":"social","who":"Stanley Milgram","year":"1963","def":"Following a direct command from an authority figure, even against one's conscience.","detail":"In Milgram's Yale study 65% of participants gave the maximum 450-volt 'shock' to a learner. Obedience fell when the victim was close, the experimenter was absent, or peers defied. Milgram explained it via the agentic state.","example":"A nurse gives an overdose because the doctor on the phone insisted.","look":"Conformity","tell":"Obedience = ORDER from above (vertical); conformity = PRESSURE from equals (horizontal).","aliases":["obedience","obedience to authority","milgram obedience","milgram experiment","agentic state"],"lookId":"conformity"},{"id":"compliance","name":"Compliance","cat":"phenomenon","area":"social","who":"Robert Cialdini (compliance techniques); Freedman & Fraser (foot-in-the-door)","year":"1966","def":"Agreeing to an explicit request from someone who has no authority over you.","detail":"Classic techniques: foot-in-the-door (small request then larger, Freedman & Fraser 1966), door-in-the-face (huge request refused then smaller, Cialdini et al. 1975), low-ball (Cialdini 1978), that's-not-all.","example":"You sign a petition, then a week later agree to put a big sign in your garden for the same cause.","look":"Obedience","tell":"Compliance = a REQUEST from an equal; obedience = a COMMAND from authority.","aliases":["social compliance","compliance techniques","foot-in-the-door","door-in-the-face","low-ball technique"],"lookId":"obedience"},{"id":"minority-influence","name":"Minority influence","cat":"phenomenon","area":"social","who":"Serge Moscovici","year":"1969","def":"A consistent minority can shift the views of the majority, usually through private conversion rather than public compliance.","detail":"Moscovici, Lage & Naffrechoux's blue-green slide study: two confederates consistently calling blue slides 'green' got about 8% of majority answers to follow; inconsistent confederates had almost no effect. Key ingredient: consistency (behavioural style).","example":"One juror who steadily argues 'not guilty' slowly wins over the other eleven.","look":"Conformity","tell":"Conformity = majority pulls minority, public compliance; minority influence = consistent few convert many, private change.","aliases":["minority influence","moscovici minority","consistent minority","blue-green slides"],"lookId":"conformity"},{"id":"cognitive-dissonance","name":"Cognitive dissonance","cat":"phenomenon","area":"social","who":"Leon Festinger","year":"1957","def":"The uncomfortable tension felt when holding two inconsistent cognitions, which motivates changing an attitude or belief to restore consistency.","detail":"Festinger & Carlsmith (1959): people paid $1 to tell others a boring task was fun later rated it more enjoyable than those paid $20 (insufficient justification). Also effort justification and post-decision dissonance.","example":"A smoker who knows smoking kills tells himself 'my grandfather smoked and lived to 90'.","look":"Self-perception","tell":"Dissonance = there is aversive AROUSAL that drives the change; self-perception = no tension, you simply infer your attitude from watching your behaviour.","aliases":["cognitive dissonance","dissonance","festinger's cognitive dissonance theory","insufficient justification","effort justification","reduce the dissonance"],"lookId":"self-perception"},{"id":"self-perception","name":"Self-perception","cat":"phenomenon","area":"social","who":"Daryl Bem","year":"1967","def":"We infer our own attitudes by observing our own behaviour, the way an outsider would.","detail":"Bem offered it as a no-arousal alternative explanation of the Festinger & Carlsmith result. Works best when attitudes are weak or ambiguous; it underlies the overjustification effect.","example":"'I keep ordering filter coffee, so I guess I like it more than tea.'","look":"Cognitive dissonance","tell":"Bem = cool self-observation, no discomfort; Festinger = hot inner conflict that must be reduced.","aliases":["self-perception theory","self perception theory","bem's self-perception"],"lookId":"cognitive-dissonance"},{"id":"stereotype-threat","name":"Stereotype threat","cat":"phenomenon","area":"social","who":"Claude Steele & Joshua Aronson","year":"1995","def":"Worry about confirming a negative stereotype about one's group lowers one's performance on the relevant task.","detail":"Steele & Aronson found Black students did worse on a GRE-type test when it was framed as diagnostic of intellectual ability, but equal to White students when it was not. Similar effects for women in maths.","example":"Women told a maths test shows gender differences score lower than women told it does not.","look":"Self-fulfilling prophecy","tell":"Stereotype threat = the TARGET's own anxiety drags performance; self-fulfilling prophecy = OTHERS' expectations shape how they treat you.","aliases":["stereotype threat"],"lookId":"self-fulfilling-prophecy"},{"id":"self-fulfilling-prophecy","name":"Self-fulfilling prophecy","cat":"phenomenon","area":"social","who":"Robert K. Merton","year":"1948","def":"A false expectation leads to behaviour that makes the expectation come true.","detail":"Merton (a sociologist) coined it using a bank-run example. Rosenthal & Jacobson's 'Pygmalion in the Classroom' (1968) showed teachers' randomly induced expectations raised pupils' IQ gains.","example":"A rumour that a bank is failing makes everyone withdraw money, so the bank fails.","look":"Pygmalion effect","tell":"Self-fulfilling prophecy is Merton's general idea; Pygmalion effect is Rosenthal's classroom version (teacher expectations raise performance).","aliases":["self-fulfilling prophecy","self fulfilling prophecy","self-fulfilling prophecies"],"lookId":"pygmalion-effect"},{"id":"social-comparison","name":"Social comparison","cat":"phenomenon","area":"social","who":"Leon Festinger","year":"1954","def":"We evaluate our own abilities and opinions by comparing ourselves with other people, especially when objective standards are lacking.","detail":"Festinger said we prefer similar others. Upward comparison (to better-off people) can motivate or depress; downward comparison (to worse-off people) boosts self-esteem.","example":"You feel fine about 70% until you hear your friend scored 90%.","look":"Relative deprivation","tell":"Social comparison is the general PROCESS of comparing; relative deprivation is the specific RESENTMENT when the comparison shows you have less than you deserve.","aliases":["social comparison","social comparison theory","upward comparison","downward comparison"],"lookId":"relative-deprivation"},{"id":"relative-deprivation","name":"Relative deprivation","cat":"phenomenon","area":"social","who":"Samuel Stouffer and colleagues","year":"1949","def":"Feeling deprived because you have less than a comparison group, regardless of how much you objectively have.","detail":"From 'The American Soldier': military police with slow promotions were more satisfied than air corps men with fast promotions, because of whom they compared with. Used to explain protest, riots and prejudice.","example":"A well-paid engineer feels cheated because batchmates at another firm earn more.","look":"Social comparison","tell":"Relative deprivation = the GRIEVANCE (I deserve more); social comparison = just the act of comparing.","aliases":["relative deprivation","fraternal deprivation","egoistic deprivation"],"lookId":"social-comparison"},{"id":"scapegoating","name":"Scapegoating","cat":"phenomenon","area":"social","who":"Carl Hovland & Robert Sears (classic data); frustration-aggression theory","year":"1940","def":"Displacing frustration-driven aggression onto a weaker, often minority, target who is not the real cause.","detail":"Rooted in Dollard et al.'s frustration-aggression hypothesis (1939). Hovland & Sears linked falling cotton prices in the US South to more lynchings of Black people.","example":"During an economic slump, migrants are blamed for lost jobs.","look":"Displacement","tell":"Displacement is the individual defence (kick the dog); scapegoating is the GROUP-level version aimed at an outgroup.","aliases":["scapegoating","scapegoat theory","scapegoat"]},{"id":"catharsis","name":"Catharsis","cat":"phenomenon","area":"clinical","who":"Aristotle (term); Breuer & Freud (therapeutic use)","year":"","def":"The idea that expressing or venting emotion, especially aggression, releases it and reduces later aggression.","detail":"Breuer & Freud's 'cathartic method' for hysteria (Anna O). Research (e.g. Bushman 2002, punching bag) shows venting anger tends to INCREASE later aggression, so the catharsis hypothesis is largely unsupported.","example":"Smashing plates in a 'rage room' to feel calmer about your boss.","look":"Abreaction","tell":"Catharsis = the overall emotional purging (and the venting hypothesis); abreaction = reliving a repressed memory with its emotion in therapy.","aliases":["catharsis","catharsis hypothesis","cathartic method","venting hypothesis"]},{"id":"emotional-contagion","name":"Emotional contagion","cat":"phenomenon","area":"social","who":"Elaine Hatfield, John Cacioppo & Richard Rapson","year":"1994","def":"Automatically 'catching' others' emotions by mimicking their faces, voices and postures.","detail":"Process: automatic mimicry, then facial and postural feedback produces the matching feeling. Seen in infants who cry when other infants cry.","example":"A cheerful shopkeeper's smile lifts your mood without you noticing why.","look":"Empathy","tell":"Contagion is automatic mimicry with no understanding needed; empathy involves knowing the feeling is the other person's.","aliases":["emotional contagion","mood contagion"]},{"id":"learned-helplessness","name":"Learned helplessness","cat":"phenomenon","area":"learning","who":"Martin Seligman & Steven Maier","year":"1967","def":"After repeated uncontrollable bad events, an organism stops trying to escape even when escape becomes possible.","detail":"Dogs given inescapable shocks later failed to jump a barrier in a shuttle box to avoid shock. Reformulated (Abramson, Seligman & Teasdale 1978) around internal, stable, global attributions; a model of depression.","example":"A student who failed maths repeatedly no longer attempts problems even with a new, good teacher.","look":"Learned optimism","tell":"Helplessness = learning that you have NO control; learned optimism = learning to explain setbacks as temporary, specific and external.","aliases":["learned helplessness","learned helplessness phenomenon","what is learned helplessness"],"lookId":"learned-optimism"},{"id":"learned-optimism","name":"Learned optimism","cat":"phenomenon","area":"personality","who":"Martin Seligman","year":"1990","def":"Optimism can be learned by changing one's explanatory style for bad events.","detail":"Optimists explain failures as temporary, specific and external; pessimists as permanent, pervasive and personal (the 3 Ps). Taught via ABCDE disputing, adapted from Ellis.","example":"After a rejection, you say 'that panel had an off day' instead of 'I am never good enough'.","look":"Learned helplessness","tell":"Same author (Seligman): helplessness is the problem, optimism is the trained cure.","aliases":["learned optimism","explanatory style"],"lookId":"learned-helplessness"},{"id":"insight-learning","name":"Insight learning","cat":"phenomenon","area":"learning","who":"Wolfgang Kohler","year":"1925","def":"Sudden solution of a problem by perceiving the relationships among its parts, rather than by trial and error.","detail":"Kohler's chimpanzees on Tenerife (e.g. Sultan) joined two sticks or stacked boxes to reach bananas ('The Mentality of Apes', English 1925). Marks: sudden 'aha', smooth performance, transfer to new problems, retention.","example":"After staring at a puzzle you suddenly see the trick and solve it at once.","look":"Trial and error learning","tell":"Kohler = sudden whole-situation 'aha'; Thorndike = gradual stamping in through trial and error.","aliases":["insight learning","aha experience","aha moment","learning and insight","kohler's apes"]},{"id":"latent-learning","name":"Latent learning","cat":"phenomenon","area":"learning","who":"Edward Tolman & Charles Honzik","year":"1930","def":"Learning that happens without reinforcement and stays hidden until there is a reason to show it.","detail":"Rats that explored a maze unrewarded for 10 days made few errors as soon as food appeared on day 11, matching or beating always-rewarded rats.","example":"You never needed the route to the chemist until you fell ill, then you knew it at once from passing it daily.","look":"Latent inhibition","tell":"Latent LEARNING = hidden learning that later appears; latent INHIBITION = prior exposure to a CS SLOWS later conditioning.","aliases":["latent learning","tolman's rat maze studies","tolman and honzik"],"lookId":"latent-inhibition"},{"id":"cognitive-map","name":"Cognitive map","cat":"phenomenon","area":"learning","who":"Edward Tolman","year":"1948","def":"A mental representation of the layout of an environment.","detail":"Proposed in 'Cognitive maps in rats and men'. Rats took a novel shortcut when the usual path was blocked, showing they had learned the spatial layout, not just a chain of turns. Later linked to hippocampal place cells (O'Keefe).","example":"You find a new route home when your usual road is closed.","look":"Latent learning","tell":"Latent learning is the phenomenon (hidden learning); the cognitive map is what is learned (the mental layout).","aliases":["cognitive map","cognitive maps","mental map"],"lookId":"latent-learning"},{"id":"observational-learning","name":"Observational learning","cat":"phenomenon","area":"learning","who":"Albert Bandura","year":"1961","def":"Learning by watching others' behaviour and its outcomes.","detail":"Bandura, Ross & Ross's Bobo doll study (1961): children who watched an adult attack the doll imitated the aggression. Four processes: attention, retention, reproduction, motivation.","example":"A child learns to use chopsticks by watching an older sibling.","look":"Vicarious reinforcement","tell":"Observational learning is learning from a model at all; vicarious reinforcement is the specific bit where seeing the model REWARDED raises imitation.","aliases":["observational learning","modelling","modeling","imitation learning","social learning","bobo doll experiment"],"lookId":"vicarious-reinforcement"},{"id":"vicarious-reinforcement","name":"Vicarious reinforcement","cat":"phenomenon","area":"learning","who":"Albert Bandura","year":"1965","def":"Being more likely to perform a behaviour after seeing someone else rewarded for it.","detail":"Bandura (1965): children who saw the model punished imitated less aggression, but when offered incentives they all could reproduce it, separating learning from performance. Vicarious punishment is the opposite.","example":"A classmate is praised for answering, so you start raising your hand too.","look":"Observational learning","tell":"'Vicarious' = second-hand CONSEQUENCE; observational learning = the whole watch-and-learn process.","aliases":["vicarious reinforcement","vicarious punishment","vicarious conditioning"],"lookId":"observational-learning"},{"id":"spontaneous-recovery","name":"Spontaneous recovery","cat":"phenomenon","area":"learning","who":"Ivan Pavlov","year":"1927","def":"Reappearance of an extinguished conditioned response after a rest period, without new training.","detail":"Shows extinction suppresses rather than erases learning. The recovered response is usually weaker and extinguishes faster.","example":"A dog's salivation to the bell, extinguished yesterday, partly returns this morning.","look":"Extinction burst","tell":"Spontaneous recovery = comes BACK after a REST; extinction burst = brief SURGE right when reinforcement STOPS.","aliases":["spontaneous recovery"],"lookId":"extinction-burst"},{"id":"extinction-burst","name":"Extinction burst","cat":"phenomenon","area":"learning","who":"","year":"","def":"A temporary increase in the frequency or intensity of a behaviour right after reinforcement for it stops.","detail":"A sign extinction is working; giving in during the burst puts the behaviour on intermittent reinforcement and makes it stronger. Often comes with emotional or aggressive behaviour.","example":"A child whose tantrums are now ignored screams louder for a few days before stopping.","look":"Spontaneous recovery","tell":"Burst = at the START of extinction; spontaneous recovery = AFTER extinction and a rest.","aliases":["extinction burst","response burst"],"lookId":"spontaneous-recovery"},{"id":"stimulus-generalization","name":"Stimulus generalization","cat":"phenomenon","area":"learning","who":"Ivan Pavlov; John Watson & Rosalie Rayner","year":"1920","def":"Responding to stimuli similar to the conditioned stimulus, with stronger responses the more similar they are (generalization gradient).","detail":"Little Albert, conditioned to fear a white rat, also feared a rabbit, a dog, a fur coat and a Santa Claus mask.","example":"After being bitten by a dog, a child fears all dogs.","look":"Stimulus discrimination","tell":"Generalization = SPREAD to similar stimuli; discrimination = NARROWING to only the trained stimulus.","aliases":["stimulus generalization","stimulus generalisation","generalization gradient","little albert"],"lookId":"stimulus-discrimination"},{"id":"stimulus-discrimination","name":"Stimulus discrimination","cat":"phenomenon","area":"learning","who":"Ivan Pavlov","year":"1927","def":"Learning to respond to one stimulus but not to similar stimuli that are never paired with the US or reinforcer.","detail":"Trained by reinforcing the CS+ and not the CS-. When discriminations are made too hard (circle vs near-circle ellipse) Pavlov's dogs showed 'experimental neurosis'.","example":"Your dog runs to the kitchen at the sound of the food packet but ignores other crinkling bags.","look":"Stimulus generalization","tell":"Discrimination = telling stimuli APART; generalization = treating them ALIKE.","aliases":["stimulus discrimination","discrimination learning","discriminative stimulus","experimental neurosis"],"lookId":"stimulus-generalization"},{"id":"higher-order-conditioning","name":"Higher-order conditioning","cat":"phenomenon","area":"learning","who":"Ivan Pavlov","year":"1927","def":"A neutral stimulus becomes a CS by being paired with an already conditioned CS, not with the US.","detail":"Order: CS1 is paired with the US first, then CS2 is paired with CS1. Second-order is reliable; third-order is weak.","example":"Bell gets paired with food; then a light gets paired with the bell; now the light alone causes salivation.","look":"Sensory preconditioning","tell":"Higher-order: CS1 is conditioned FIRST, then CS2 pairing; sensory preconditioning: CS2-CS1 pairing FIRST, then CS1 conditioned.","aliases":["higher-order conditioning","higher order conditioning","second-order conditioning","second order conditioning"],"lookId":"sensory-preconditioning"},{"id":"sensory-preconditioning","name":"Sensory preconditioning","cat":"phenomenon","area":"learning","who":"W. J. Brogden","year":"1939","def":"Two neutral stimuli are paired first; one is then conditioned; the other now also evokes the response.","detail":"Brogden paired a light and bell in dogs, then conditioned the bell to shock; the untrained light produced the response too. Shows learning of stimulus-stimulus associations without a US.","example":"You often see a dog behind a red gate; a dog bites you elsewhere; now the red gate itself makes you nervous.","look":"Higher-order conditioning","tell":"Preconditioning = neutral pairing BEFORE any US; higher-order = pairing AFTER CS1 is already conditioned.","aliases":["sensory preconditioning","sensory pre-conditioning"],"lookId":"higher-order-conditioning"},{"id":"blocking","name":"Blocking (Kamin effect)","cat":"phenomenon","area":"learning","who":"Leon Kamin","year":"1969","def":"Prior conditioning to one CS prevents conditioning to a second CS added later in compound.","detail":"Rats conditioned to a noise and then to noise+light compound learned nothing about the light. Shows conditioning needs surprise or information, and led to the Rescorla-Wagner model (1972).","example":"Your stomach upset is already explained by the street food, so you never link it to the new juice you drank with it.","look":"Overshadowing","tell":"Blocking = the first CS was trained EARLIER and blocks the newcomer; overshadowing = both CSs are new together and the more SALIENT one wins.","aliases":["blocking","kamin blocking","kamin's blocking","blocking effect","kamin effect"],"lookId":"overshadowing"},{"id":"overshadowing","name":"Overshadowing","cat":"phenomenon","area":"learning","who":"Ivan Pavlov","year":"1927","def":"When two stimuli are presented together as a compound CS, the more salient one acquires most of the conditioning.","detail":"Training happens at the same time for both stimuli; the stronger or more intense one gets conditioned, the weaker one little.","example":"Paired with shock, a loud tone plus dim light leads to fear of the tone and almost none of the light.","look":"Blocking","tell":"Overshadowing = SIMULTANEOUS competition decided by salience; blocking = PRIOR training decides.","aliases":["overshadowing"],"lookId":"blocking"},{"id":"latent-inhibition","name":"Latent inhibition","cat":"phenomenon","area":"learning","who":"R. E. Lubow & A. U. Moore","year":"1959","def":"Pre-exposure to a stimulus without consequence makes it slower to become a conditioned stimulus later.","detail":"Also called the CS pre-exposure effect. Reduced latent inhibition has been linked to schizophrenia and creativity.","example":"A familiar kitchen noise is harder to condition as a fear cue than a brand-new sound.","look":"Latent learning","tell":"Latent INHIBITION slows later learning; latent LEARNING is hidden learning that shows up later.","aliases":["latent inhibition","cs pre-exposure effect","cs preexposure effect"],"lookId":"latent-learning"},{"id":"habituation","name":"Habituation","cat":"phenomenon","area":"learning","who":"Thompson & Spencer (classic criteria); Groves & Thompson (dual-process theory)","year":"1966","def":"Decrease in response to a stimulus that is presented repeatedly and has no consequence.","detail":"Simplest form of non-associative learning. It is stimulus-specific and reverses with a novel stimulus (dishabituation). Used in infant research (habituation paradigm) to test perception.","example":"You stop noticing the ceiling fan's hum after a few minutes.","look":"Sensory adaptation","tell":"Habituation is a central/behavioural decrease that dishabituation can undo; sensory adaptation is receptor fatigue in the sense organ.","aliases":["habituation","habituation paradigm"],"lookId":"sensory-adaptation"},{"id":"sensitization","name":"Sensitization","cat":"phenomenon","area":"learning","who":"Groves & Thompson (dual-process theory); Eric Kandel (Aplysia)","year":"1970","def":"Increase in response to a stimulus after exposure to a strong or noxious stimulus; the opposite of habituation.","detail":"Non-associative and not stimulus-specific: after a shock, many stimuli produce a bigger response. Kandel studied it in the sea slug Aplysia. Also used for drug sensitization (reverse tolerance).","example":"After hearing a gunshot, you jump at every small noise for the rest of the evening.","look":"Habituation","tell":"Habituation = response goes DOWN with repetition; sensitization = response goes UP after a strong stimulus. (Covert sensitization is Cautela's aversion therapy, not this.)","aliases":["sensitization","sensitisation","opposite of habituation","behavioural sensitization","reverse tolerance"],"lookId":"habituation"},{"id":"dishabituation","name":"Dishabituation","cat":"phenomenon","area":"learning","who":"","year":"","def":"Recovery of a habituated response when a new or changed stimulus is presented.","detail":"Proves habituation was learning, not fatigue. In infant studies, renewed looking at a new stimulus shows the infant can tell old and new apart.","example":"You had tuned out the fan, but when it starts rattling you notice its hum again.","look":"Spontaneous recovery","tell":"Dishabituation = response returns because of a NEW stimulus; spontaneous recovery = a conditioned response returns after a REST.","aliases":["dishabituation"],"lookId":"spontaneous-recovery"},{"id":"pree","name":"Partial reinforcement extinction effect","cat":"phenomenon","area":"learning","who":"Lloyd Humphreys","year":"1939","def":"Behaviour learned under partial (intermittent) reinforcement extinguishes more slowly than behaviour learned under continuous reinforcement.","detail":"Also called the Humphreys effect or Humphreys paradox. Variable-ratio schedules give the most resistance to extinction. Explanations: discrimination hypothesis, frustration theory (Amsel), sequential theory (Capaldi).","example":"A gambler keeps playing a slot machine long after it stops paying, unlike a vending machine you abandon after one failure.","look":"Extinction burst","tell":"PREE = slow extinction because of INTERMITTENT past reward; extinction burst = brief SPIKE when reward stops.","aliases":["partial reinforcement extinction effect","partial reinforcement effect","pree","humphreys effect","humphreys paradox","resistance to extinction"],"lookId":"extinction-burst"},{"id":"instinctive-drift","name":"Instinctive drift","cat":"phenomenon","area":"learning","who":"Keller Breland & Marian Breland","year":"1961","def":"Trained animals gradually drift back to instinctive, species-typical behaviours that interfere with the conditioned response.","detail":"From 'The Misbehavior of Organisms'. Raccoons trained to drop coins in a box began rubbing them together; pigs rooted their tokens. Shows biological limits on operant conditioning.","example":"A raccoon trained for a coin trick starts 'washing' the coins instead of depositing them.","look":"Autoshaping","tell":"Instinctive drift = trained behaviour DECAYS into instinct; autoshaping = instinctive pecking APPEARS with no shaping at all.","aliases":["instinctive drift","misbehavior of organisms","misbehaviour of organisms"],"lookId":"autoshaping"},{"id":"autoshaping","name":"Autoshaping","cat":"phenomenon","area":"learning","who":"Paul Brown & Herbert Jenkins","year":"1968","def":"Animals start responding to a signal for food (such as pecking a lit key) without any response-contingent reinforcement.","detail":"Pigeons pecked a key that lit before free food delivery. A Pavlovian sign-tracking effect that looks operant.","example":"Pigeons peck a lit disc even though food arrives whether they peck or not.","look":"Superstitious behaviour","tell":"Autoshaping = response directed AT the signal, driven by the CS-food pairing; superstition = ANY random behaviour that happened to precede the reward.","aliases":["autoshaping","auto-shaping","sign tracking","sign-tracking"],"lookId":"superstitious-behaviour"},{"id":"superstitious-behaviour","name":"Superstitious behaviour","cat":"phenomenon","area":"learning","who":"B. F. Skinner","year":"1948","def":"Behaviour strengthened by accidental pairing with a reinforcer that was not actually caused by it.","detail":"Skinner gave pigeons food every 15 seconds regardless of behaviour; they developed odd rituals like turning counter-clockwise or head-tossing (fixed-time schedule).","example":"A cricketer wears the same unwashed socks after scoring a century in them.","look":"Autoshaping","tell":"Superstition = an arbitrary act ACCIDENTALLY rewarded; autoshaping = the response is aimed at a food SIGNAL.","aliases":["superstitious behaviour","superstitious behavior","superstitious conditioning","superstition in the pigeon"],"lookId":"autoshaping"},{"id":"preparedness","name":"Preparedness (biological)","cat":"phenomenon","area":"learning","who":"Martin Seligman","year":"1970","def":"Species are biologically prepared to learn some associations easily and others with difficulty.","detail":"Explains why phobias cluster around snakes, spiders, heights and blood (prepared stimuli) rather than cars or sockets (Seligman 1971 on phobias). Continuum: prepared, unprepared, contraprepared.","example":"People acquire snake phobias after one scare but rarely develop electrical-socket phobias.","look":"Taste aversion (Garcia effect)","tell":"Preparedness is the general PRINCIPLE; taste aversion is its most famous single DEMONSTRATION.","aliases":["preparedness","biological preparedness","prepared learning","preparedness theory"],"lookId":"garcia-effect"},{"id":"taste-aversion","name":"Conditioned taste aversion (Garcia effect)","cat":"phenomenon","area":"learning","who":"John Garcia & Robert Koelling","year":"1966","def":"Learning to avoid a food after it is followed by illness, often after a single pairing and a long delay.","detail":"Rats easily linked taste with nausea but not light/sound with nausea, and linked light/sound with shock but not taste with shock (bright-noisy-tasty water). Violates equipotentiality and the need for close CS-US timing.","example":"After one bout of food poisoning from biryani, you cannot face biryani for years.","look":"Preparedness","tell":"Garcia effect is the specific taste-illness finding; preparedness is Seligman's broader theory it supports.","aliases":["taste aversion","conditioned taste aversion","garcia effect","learned taste aversion","bait shyness","equipotentiality hypothesis"],"lookId":"preparedness"},{"id":"imprinting","name":"Imprinting","cat":"phenomenon","area":"developmental","who":"Konrad Lorenz","year":"1935","def":"Rapid, lasting attachment formed by young animals to the first moving object they see during a brief critical period after birth.","detail":"Lorenz's greylag goslings followed him. Critical period is roughly the first 36 hours (Hess put peak sensitivity at 13-16 hours in ducklings). Influenced Bowlby's attachment theory.","example":"Ducklings hatched in an incubator follow the farmer's boots everywhere.","look":"Attachment","tell":"Imprinting = instinctive, fast, within a fixed critical period, in birds; attachment = slower human emotional bond (Bowlby, Ainsworth).","aliases":["imprinting","filial imprinting","lorenz's geese"],"lookId":"strange-situation"},{"id":"functional-fixedness","name":"Functional fixedness","cat":"phenomenon","area":"cognitive","who":"Karl Duncker","year":"1945","def":"Inability to see an object as useful for anything other than its usual function.","detail":"Duncker's candle problem: fix a candle to a wall with a box of tacks; people fail to use the box as a shelf, especially when it is full of tacks. Maier's two-string problem is a related demonstration.","example":"You hunt for a screwdriver when a coin in your pocket would turn the screw.","look":"Mental set","tell":"Functional fixedness = stuck on an OBJECT's usual use; mental set = stuck on a familiar METHOD or strategy.","aliases":["functional fixedness","functional fixity","duncker candle problem","candle problem","why does functional fixedness"],"lookId":"mental-set"},{"id":"mental-set","name":"Mental set (Einstellung effect)","cat":"phenomenon","area":"cognitive","who":"Abraham Luchins","year":"1942","def":"Tendency to keep using a strategy that worked before, even when a simpler or better one is available.","detail":"Luchins' water-jar problems: after several problems solved by B - A - 2C, most people used the long formula on problems that could be solved by A - C or A + C.","example":"Having solved five sums by long division, you long-divide 100 by 10.","look":"Functional fixedness","tell":"Mental set = rigid PROCEDURE; functional fixedness = rigid view of an OBJECT.","aliases":["mental set","einstellung","einstellung effect","water jar problem","water-jar problem","response set","problem-solving set"],"lookId":"functional-fixedness"},{"id":"incubation","name":"Incubation","cat":"phenomenon","area":"cognitive","who":"Graham Wallas","year":"1926","def":"A solution to a problem emerges after a period of setting the problem aside.","detail":"Second of Wallas' four stages of creative thinking: preparation, incubation, illumination, verification. Possible reasons: fatigue lifts, mental set fades, unconscious processing.","example":"The answer to a crossword clue pops into your head while you are bathing.","look":"Insight","tell":"Incubation = the time AWAY from the problem; insight/illumination = the sudden 'aha' that may follow it.","aliases":["incubation","incubation effect","incubation stage","wallas stages"],"lookId":"insight-learning"},{"id":"tip-of-the-tongue","name":"Tip-of-the-tongue phenomenon","cat":"phenomenon","area":"memory","who":"Roger Brown & David McNeill","year":"1966","def":"Feeling sure you know a word but being unable to retrieve it, often with partial access to its first letter or syllable count.","detail":"Brown & McNeill read dictionary definitions of rare words (e.g. 'sampan'); people in the TOT state often recalled the first letter, number of syllables and similar-sounding words. Shows retrieval failure, not storage loss.","example":"You know the actor's name starts with 'S' and has two syllables but cannot say it.","look":"Feeling-of-knowing","tell":"TOT = the word is on the edge and you have PARTIAL cues; feeling-of-knowing = a general JUDGEMENT that you would recognise the answer.","aliases":["tip-of-the-tongue","tip of the tongue","tot phenomenon","tip-of-the-tongue phenomenon","tot state"],"lookId":"feeling-of-knowing"},{"id":"feeling-of-knowing","name":"Feeling-of-knowing","cat":"phenomenon","area":"memory","who":"Joseph Hart","year":"1965","def":"A metamemory judgement that you know an answer you cannot currently recall.","detail":"Hart showed people's feeling-of-knowing ratings for unrecalled items predicted later recognition accuracy above chance. Part of metacognition research.","example":"You cannot recall a capital city but feel certain you would pick it from four options.","look":"Tip-of-the-tongue phenomenon","tell":"Feeling-of-knowing = a confidence RATING about recognition; TOT = an intense, about-to-say-it STATE with partial word cues.","aliases":["feeling-of-knowing","feeling of knowing","fok judgement","fok judgment"],"lookId":"tip-of-the-tongue"},{"id":"change-blindness","name":"Change blindness","cat":"phenomenon","area":"perception","who":"Daniel Simons & Daniel Levin","year":"1998","def":"Failure to notice large changes in a scene, especially when the change happens during a disruption.","detail":"In the 'door study', a stranger asking directions was swapped for a different person while a door was carried between them; about half of people did not notice. Flicker paradigm (Rensink) is another demonstration.","example":"You fail to notice that an actor's shirt changed colour between two shots of a film.","look":"Inattentional blindness","tell":"Change blindness = missing a CHANGE between views; inattentional blindness = missing an unexpected OBJECT while attending elsewhere.","aliases":["change blindness","door study","flicker paradigm"],"lookId":"inattentional-blindness"},{"id":"inattentional-blindness","name":"Inattentional blindness","cat":"phenomenon","area":"perception","who":"Arien Mack & Irvin Rock (term); Daniel Simons & Christopher Chabris (gorilla study)","year":"1998","def":"Failing to see a fully visible but unexpected object because attention is focused elsewhere.","detail":"Mack & Rock named it (1998). Simons & Chabris (1999): about half of viewers counting basketball passes missed a person in a gorilla suit walking through the scene.","example":"A driver focused on traffic signals fails to see a cyclist right in front of the car.","look":"Change blindness","tell":"Inattentional = the thing was there the WHOLE time but not attended (gorilla); change blindness = something CHANGED and you missed the change.","aliases":["inattentional blindness","invisible gorilla","gorilla experiment","gorilla study"],"lookId":"change-blindness"},{"id":"attentional-blink","name":"Attentional blink","cat":"phenomenon","area":"perception","who":"Jane Raymond, Kimron Shapiro & Karen Arnell","year":"1992","def":"After detecting one target in a rapid stream of stimuli, people often miss a second target that appears about 200-500 ms later.","detail":"Shown with rapid serial visual presentation (RSVP). If T2 comes immediately after T1 it is often spared (lag-1 sparing).","example":"Scanning a fast list of words, you spot your friend's name but miss your own name shown a moment later.","look":"Repetition blindness","tell":"Attentional blink = missing a DIFFERENT second target (time-based); repetition blindness = missing a REPEAT of the same item.","aliases":["attentional blink","rsvp blink"],"lookId":"repetition-blindness"},{"id":"repetition-blindness","name":"Repetition blindness","cat":"phenomenon","area":"perception","who":"Nancy Kanwisher","year":"1987","def":"Failure to detect the second occurrence of an identical item in a rapid sequence.","detail":"In RSVP, 'When she spilled the ink there was ink all over' is often reported without the second 'ink', even though the sentence becomes ungrammatical. Explained as a failure to create a new token for an already-recognised type.","example":"Reading fast, you miss that 'the the' appears in a sentence.","look":"Attentional blink","tell":"Repetition blindness needs the SAME item twice; attentional blink involves two DIFFERENT targets.","aliases":["repetition blindness"],"lookId":"attentional-blink"},{"id":"phi-phenomenon","name":"Phi phenomenon","cat":"phenomenon","area":"perception","who":"Max Wertheimer","year":"1912","def":"Illusion of pure movement seen between two stationary lights flashed in quick alternation, without seeing an object actually move.","detail":"Wertheimer's 1912 paper on apparent movement is usually taken as the founding of Gestalt psychology (with Kohler and Koffka as subjects). It showed the whole experience is not the sum of sensations.","example":"Lights on a cinema marquee seem to chase around the sign.","look":"Beta movement","tell":"Phi = 'objectless' movement sensation between faster flashes; beta = you see one OBJECT move from place to place (as in films).","aliases":["phi phenomenon","phi movement","pure phi","wertheimer's phi"],"lookId":"beta-movement"},{"id":"beta-movement","name":"Beta movement","cat":"phenomenon","area":"perception","who":"","year":"","def":"Perception of a single object moving smoothly from one location to another when two separate images are flashed in sequence.","detail":"Wertheimer distinguished it from phi; occurs at slightly slower alternation rates than pure phi. Basis of the motion seen in films and animation.","example":"A cartoon character seems to walk across the screen though each frame is still.","look":"Phi phenomenon","tell":"Beta = you see the OBJECT travel; phi = you see motion without a clear object.","aliases":["beta movement","beta motion","optimal movement"],"lookId":"phi-phenomenon"},{"id":"apparent-motion","name":"Apparent (stroboscopic) motion","cat":"phenomenon","area":"perception","who":"Max Wertheimer (Gestalt studies)","year":"1912","def":"Umbrella term for perceiving motion where there is no actual physical movement.","detail":"Includes stroboscopic motion (phi and beta), induced motion (stationary moon seems to move behind drifting clouds), the autokinetic effect, and motion aftereffect (waterfall illusion).","example":"A film made of 24 still frames per second looks like continuous motion.","look":"Real motion","tell":"Apparent motion = the brain infers motion from static change; real motion = the stimulus actually moves across the retina.","aliases":["apparent motion","apparent movement","stroboscopic motion","stroboscopic movement","induced motion","illusory motion"]},{"id":"autokinetic-effect","name":"Autokinetic effect","cat":"phenomenon","area":"perception","who":"Muzafer Sherif (used it for norm formation)","year":"1935","def":"A stationary point of light in a completely dark room appears to move.","detail":"Caused by small eye movements with no visual frame of reference. Sherif used it to show group norm formation: people's estimates of movement converged in groups and persisted when tested alone (informational influence).","example":"A single star stared at on a dark night seems to drift.","look":"Phi phenomenon","tell":"Autokinetic = ONE still light appears to wander; phi = TWO alternating lights create motion between them.","aliases":["autokinetic effect","autokinetic phenomenon","autokinetic movement","autokinetic illusion","sherif's norm formation"],"lookId":"phi-phenomenon"},{"id":"perceptual-constancy","name":"Perceptual constancy","cat":"phenomenon","area":"perception","who":"","year":"","def":"Perceiving objects as having stable size, shape, brightness and colour despite changes in the retinal image.","detail":"Types: size constancy (Emmert's law relates perceived size and distance), shape constancy (a door seen at an angle still looks rectangular), brightness and colour constancy. Breakdowns create illusions such as the Ames room and moon illusion.","example":"A friend walking away does not seem to shrink, though their retinal image does.","look":"Sensory adaptation","tell":"Constancy = the brain HOLDS the percept stable while input changes; adaptation = the receptor's response FADES while input stays the same.","aliases":["perceptual constancy","size constancy","shape constancy","brightness constancy","colour constancy","color constancy"],"lookId":"sensory-adaptation"},{"id":"figure-ground","name":"Figure-ground perception","cat":"phenomenon","area":"perception","who":"Edgar Rubin","year":"1915","def":"Organising a scene into a figure (the object that stands out) and a ground (the background).","detail":"Rubin's vase-faces figure is a reversible (ambiguous) figure where figure and ground switch. The figure appears closer, shaped and object-like; the ground looks formless and continues behind.","example":"Black text on a white page is seen as figure on ground.","look":"Gestalt closure","tell":"Figure-ground = separating an object from its BACKGROUND; closure = filling GAPS to complete a shape.","aliases":["figure-ground","figure ground","figure and ground","rubin's vase","rubin vase","figure-ground reversal"],"lookId":"gestalt-closure"},{"id":"sensory-adaptation","name":"Sensory adaptation","cat":"phenomenon","area":"perception","who":"","year":"","def":"Decline in a sense receptor's responsiveness to an unchanging stimulus.","detail":"Happens at the receptor level, mostly for smell, touch and temperature. Vision avoids it by constant tiny eye movements (saccades); stabilised retinal images fade.","example":"After a few minutes in a room, you no longer smell the agarbatti.","look":"Habituation","tell":"Sensory adaptation = the SENSE ORGAN tires; habituation = the BRAIN/behaviour stops responding and can be dishabituated.","aliases":["sensory adaptation","neural adaptation","receptor adaptation"],"lookId":"habituation"},{"id":"flashbulb-memory","name":"Flashbulb memory","cat":"phenomenon","area":"memory","who":"Roger Brown & James Kulik","year":"1977","def":"A vivid, detailed, confident memory of the circumstances in which one heard about a shocking, emotional event.","detail":"Named after the JFK assassination studies. Later work (Neisser on Challenger; Talarico & Rubin on 9/11) showed confidence stays high while accuracy decays like ordinary memories.","example":"You remember exactly where you were when you heard of a major national tragedy.","look":"Eidetic imagery","tell":"Flashbulb = emotional EVENT memory, feels vivid but may be wrong; eidetic = near-photographic visual image of a scene, mostly in children.","aliases":["flashbulb memory","flashbulb memories"]},{"id":"reminiscence-bump","name":"Reminiscence bump","cat":"phenomenon","area":"memory","who":"David Rubin, Scott Wetzler & Robert Nebes","year":"1986","def":"Older adults recall more autobiographical memories from adolescence and early adulthood (about ages 10-30) than from other periods.","detail":"Seen in autobiographical memory curves alongside childhood amnesia and a recency effect. Explanations: identity formation, novel 'first time' events, cultural life scripts.","example":"Grandparents talk most vividly about their college years and wedding.","look":"Reminiscence (Ballard)","tell":"Reminiscence BUMP = lifespan peak of memories from youth; Ballard's reminiscence = recall IMPROVING after a delay with no practice.","aliases":["reminiscence bump"]},{"id":"childhood-amnesia","name":"Infantile (childhood) amnesia","cat":"phenomenon","area":"memory","who":"Sigmund Freud (term)","year":"1905","def":"Inability of adults to recall episodic memories from roughly the first 3-4 years of life.","detail":"Freud blamed repression; modern accounts cite immature hippocampus and prefrontal cortex, lack of language, and the absence of a cognitive self (Howe & Courage).","example":"You cannot remember your second birthday even though photos show it.","look":"Repression","tell":"Childhood amnesia is NORMAL and universal; repression is a motivated forgetting of threatening material.","aliases":["infantile amnesia","childhood amnesia"]},{"id":"source-amnesia","name":"Source amnesia (misattribution)","cat":"phenomenon","area":"memory","who":"Marcia Johnson (source monitoring); Daniel Schacter (misattribution as a 'sin')","year":"1993","def":"Remembering information but forgetting or misattributing where or how you learned it.","detail":"Johnson, Hashtroudi & Lindsay's source-monitoring framework (1993). Schacter lists misattribution among the 'seven sins of memory' (1999). Common in frontal lobe damage and ageing; a factor in false memories and eyewitness error.","example":"You confidently quote a 'fact' you think a professor said, but you actually read it on a forum.","look":"Cryptomnesia","tell":"Source amnesia = you remember the content but lose its SOURCE; cryptomnesia = you think a borrowed idea is your OWN original idea.","aliases":["source amnesia","source misattribution","misattribution","source monitoring error","source monitoring"],"lookId":"cryptomnesia"},{"id":"cryptomnesia","name":"Cryptomnesia","cat":"phenomenon","area":"memory","who":"Theodore Flournoy (term); Alan Brown & Dana Murphy (lab study)","year":"1989","def":"Unintentional plagiarism: a forgotten memory returns and is experienced as a new, original idea.","detail":"Brown & Murphy had people generate items in groups and later many reported others' items as their own. A form of source-monitoring failure.","example":"A songwriter 'composes' a tune that turns out to be a song heard years ago.","look":"Source amnesia","tell":"Cryptomnesia = you claim the idea as ORIGINAL; source amnesia = you know it is a memory but credit the WRONG source.","aliases":["cryptomnesia","inadvertent plagiarism","unconscious plagiarism"],"roots":"crypto (hidden) + mnesia (memory): a hidden memory","lookId":"source-amnesia"},{"id":"deja-vu","name":"Deja vu","cat":"phenomenon","area":"memory","who":"Emile Boirac (term)","year":"1876","def":"The strong, eerie feeling that a new experience has happened before.","detail":"Common in healthy people; frequent episodes can be an aura of temporal lobe epilepsy. Explanations include familiarity without recollection (Cleary).","example":"Walking into a new cafe, you feel you have stood in that exact spot before.","look":"Jamais vu","tell":"Deja vu = NEW feels FAMILIAR; jamais vu = FAMILIAR feels NEW.","aliases":["deja vu","déjà vu","already seen"],"roots":"French deja (already) + vu (seen)","lookId":"jamais-vu"},{"id":"jamais-vu","name":"Jamais vu","cat":"phenomenon","area":"memory","who":"","year":"","def":"A familiar situation or word suddenly feels strange and unfamiliar.","detail":"Can be induced by repeatedly writing or saying a common word (semantic satiation is related). Also reported in temporal lobe epilepsy and dissociative states.","example":"After writing 'the' twenty times, it starts to look like a strange, wrong word.","look":"Deja vu","tell":"Jamais vu = never seen (familiar feels new); deja vu = already seen (new feels familiar).","aliases":["jamais vu"],"roots":"French jamais (never) + vu (seen)","lookId":"deja-vu"},{"id":"hedonic-adaptation","name":"Hedonic adaptation (hedonic treadmill)","cat":"phenomenon","area":"personality","who":"Philip Brickman & Donald Campbell","year":"1971","def":"After good or bad life changes, people's happiness tends to return toward a baseline.","detail":"Brickman & Campbell coined 'hedonic treadmill' (1971). Brickman, Coates & Janoff-Bulman (1978) found lottery winners were not much happier than controls and paraplegic accident victims were less unhappy than expected.","example":"The joy of a new phone fades within weeks and you want the next model.","look":"Opponent-process theory","tell":"Hedonic adaptation = return to a HAPPINESS SET POINT over months; opponent-process (Solomon) = an opposite emotional after-reaction that follows each emotion.","aliases":["hedonic adaptation","hedonic treadmill","happiness set point","adaptation level"],"lookId":"opponent-process-motivation"},{"id":"flow","name":"Flow","cat":"phenomenon","area":"personality","who":"Mihaly Csikszentmihalyi","year":"1975","def":"A state of complete absorption in a challenging activity where skill matches challenge, and time and self-consciousness fade.","detail":"Occurs when both challenge and skill are high and balanced; too much challenge gives anxiety, too little gives boredom. Activities are autotelic (rewarding in themselves). Popularised in 'Flow' (1990).","example":"A sitar player practising loses track of three hours.","look":"Peak experience","tell":"Flow = sustained, effortful absorption in a TASK; peak experience = a brief, ecstatic, transcendent MOMENT (Maslow).","aliases":["flow state","flow experience","flow theory","optimal experience"],"lookId":"peak-experience"},{"id":"peak-experience","name":"Peak experience","cat":"phenomenon","area":"personality","who":"Abraham Maslow","year":"1960s","def":"Brief moments of intense joy, awe and wholeness, frequent in self-actualizing people.","detail":"Described in 'Toward a Psychology of Being' (1962) and 'Religions, Values, and Peak Experiences' (1964). Maslow later added 'plateau experiences' as calmer, longer-lasting versions.","example":"Standing at a Himalayan summit at sunrise, you feel at one with everything.","look":"Flow","tell":"Peak experience = a spontaneous, transcendent MOMENT; flow = absorbed SKILLED activity.","aliases":["peak experience","peak experiences","plateau experience"],"lookId":"flow"},{"id":"phantom-limb","name":"Phantom limb","cat":"phenomenon","area":"biological","who":"Silas Weir Mitchell (term); V. S. Ramachandran (mirror box)","year":"1871","def":"Continuing to feel sensations, including pain, in a limb that has been amputated.","detail":"Explained by cortical remapping of the somatosensory map (e.g. touching the face is felt in the missing hand) and neuromatrix theory (Melzack). Ramachandran's mirror box relieves phantom pain.","example":"A man whose arm was amputated feels his missing fingers clenched painfully.","look":"Anosognosia","tell":"Phantom limb = feeling a part that is GONE; anosognosia = being unaware of a deficit that IS there.","aliases":["phantom limb","phantom limb pain","phantom pain","mirror box"],"lookId":"anosognosia"},{"id":"synaesthesia","name":"Synaesthesia","cat":"phenomenon","area":"perception","who":"Francis Galton (early description)","year":"1880","def":"Stimulation of one sense automatically produces an experience in another sense.","detail":"Most common form is grapheme-colour (numbers or letters have colours). Consistent over time and involuntary; linked to cross-activation between adjacent brain areas (Ramachandran & Hubbard).","example":"A person always sees the number 7 as green.","look":"McGurk effect","tell":"Synaesthesia = a rare, stable cross-sense experience in some individuals; McGurk effect = everyone's hearing is altered by seeing lip movements.","aliases":["synaesthesia","synesthesia","grapheme-colour synaesthesia","grapheme-color synesthesia"],"roots":"syn (together) + aesthesis (sensation): senses joined","lookId":"mcgurk-effect"},{"id":"blindsight","name":"Blindsight","cat":"phenomenon","area":"biological","who":"Lawrence Weiskrantz","year":"1974","def":"People with damage to primary visual cortex can respond accurately to visual stimuli in their blind field while denying they see anything.","detail":"Weiskrantz and colleagues studied patient DB, who could point to and discriminate stimuli he said he could not see. Thought to use subcortical routes (superior colliculus) bypassing V1.","example":"A patient blind in the left field 'guesses' correctly which way a line in that field points.","look":"Anton syndrome","tell":"Blindsight = CAN respond but says 'I am blind'; Anton syndrome = IS cortically blind but insists 'I can see'.","aliases":["blindsight","blind sight","patient db"],"lookId":"anton-syndrome"},{"id":"bobo-doll","name":"Bobo doll experiment","cat":"experiment","area":"social","who":"Albert Bandura (with Dorothea Ross & Sheila Ross)","year":"1961","def":"Children who watched an adult beat up an inflatable Bobo doll later copied that aggression, often in the exact same ways. Showed aggression can be learned by observation (modelling) without any reinforcement.","detail":"72 children aged 3-6 (Stanford nursery). Groups: aggressive model, non-aggressive model, no-model control. Boys imitated more physical aggression; same-sex models copied more. 1963: filmed and cartoon models also worked. 1965 variant: model rewarded, punished or no consequence; the punished-model group imitated least, but when children were offered incentives all groups reproduced the acts, showing learning vs performance.","example":"'Which study supports social learning theory / observational learning of aggression?' Answer: Bandura's Bobo doll.","look":"Little Albert","tell":"Bobo = children IMITATE a model (observational learning); Little Albert = a baby is CONDITIONED to fear a rat.","aliases":["bobo doll","bobo","bandura ross and ross","bandura's bobo"],"lookId":"stimulus-generalization"},{"id":"robbers-cave","name":"Robbers Cave experiment","cat":"experiment","area":"social","who":"Muzafer Sherif (with Carolyn Sherif and colleagues)","year":"1954","def":"Boys at a summer camp were split into two groups that turned hostile when made to compete, and became friendly again only when they had to work together on shared (superordinate) goals.","detail":"22 eleven-year-old boys at Robbers Cave State Park, Oklahoma. Groups named the Eagles and the Rattlers. Three stages: in-group formation, friction phase (tournament with prizes), integration phase. Simple contact (meals, films together) did NOT reduce hostility; superordinate goals (fixing the water supply, pulling a stuck truck, pooling money for a film) did. Basis of realistic conflict theory.","example":"'Prejudice from competition for scarce resources reduced by superordinate goals' points to Sherif's Robbers Cave.","look":"Tajfel minimal group studies","tell":"Robbers Cave = REAL competition breeds conflict; Tajfel = trivial categorisation alone breeds in-group bias, no competition needed.","aliases":["robbers cave","eagles and rattlers","superordinate goal","sherif's robbers cave"],"lookId":"tajfel-minimal-group"},{"id":"milgram-obedience","name":"Milgram obedience study","cat":"experiment","area":"social","who":"Stanley Milgram","year":"1963","def":"Ordinary men, told by an experimenter in a lab coat to give increasing electric shocks to a 'learner', mostly kept going to the maximum. Showed how strongly people obey authority.","detail":"Yale University; 40 men aged 20-50 from New Haven, recruited for a 'learning and punishment' study. Shock generator 15 to 450 volts in 15-volt steps; learner was a confederate who received no shocks. 65% (26 of 40) went to 450 V; all went to at least 300 V. Prods like 'The experiment requires that you continue'. Obedience fell when the learner was closer (touch-proximity), when orders came by phone, and in a run-down office in Bridgeport (about 48%). Book: Obedience to Authority (1974).","example":"'Which study showed 65% of participants administered the maximum 450-volt shock?' Milgram.","look":"Stanford prison experiment","tell":"Milgram = obeying an AUTHORITY's direct orders; Zimbardo = slipping into a ROLE (guard/prisoner) without being ordered.","aliases":["milgram","obedience study","obedience to authority","450 volts","milgram's obedience"],"lookId":"stanford-prison"},{"id":"milgram-small-world","name":"Milgram small-world (letter chain) study","cat":"experiment","area":"social","who":"Stanley Milgram","year":"1967","def":"People in the American Midwest were asked to get a letter to a stranger in Boston by passing it only through people they knew personally. Completed chains took about five or six steps, the origin of 'six degrees of separation'.","detail":"Starters were in Nebraska (Omaha) and Kansas (Wichita); targets in the Boston area. Only a minority of chains reached the target; completed chains had a median of about 5 intermediaries. Published in Psychology Today (1967). Also called the 'message' or 'letter' experiment.","example":"'Milgram's message experiment showed the world is a small world' refers to this, not the obedience study.","look":"Milgram lost-letter technique","tell":"Small-world = letters forwarded hand to hand to a TARGET person; lost-letter = stamped letters DROPPED in the street to measure attitudes.","aliases":["small world","small-world","six degrees of separation","milgram's message experiment","message experiment"]},{"id":"stanford-prison","name":"Stanford prison experiment","cat":"experiment","area":"social","who":"Philip Zimbardo (with Craig Haney & Curtis Banks)","year":"1971","def":"Students randomly assigned to be guards or prisoners in a mock prison quickly became abusive or passive, so the study was stopped early. Used to argue that situations and roles can overpower individual character.","detail":"24 male college students screened as psychologically normal, randomly assigned; mock prison in the basement of Stanford's psychology building. Planned for 2 weeks, stopped after 6 days. Guards wore uniforms and mirrored sunglasses (deindividuation); prisoners were called by numbers. Christina Maslach's objection helped end it. Zimbardo himself acted as prison superintendent. Later criticised for demand characteristics and guard coaching.","example":"'Deindividuation and the power of social roles' points to Zimbardo's Stanford prison experiment.","look":"Milgram obedience study","tell":"Zimbardo = ROLES in a mock prison; Milgram = ORDERS from an experimenter.","aliases":["stanford prison","zimbardo's prison experiment","zimbardo prison","prison experiment","stanford prison experiment"],"lookId":"milgram-obedience"},{"id":"asch-conformity","name":"Asch line-judgement (conformity) study","cat":"experiment","area":"social","who":"Solomon Asch","year":"1951","def":"People judged which of three lines matched a standard line; when a group of confederates unanimously gave the wrong answer, many participants went along with them despite the obvious truth.","detail":"One real participant among about 7-9 confederates; 18 trials, 12 critical. About 37% (often quoted as roughly one-third) of critical responses conformed; about 75% conformed at least once; about 25% never did. Conformity rose with group size up to about 3-4, then levelled off; one dissenting ally cut it sharply; writing answers privately reduced it. Shows normative social influence.","example":"'Experiments demonstrating conformity using unambiguous line lengths' means Asch.","look":"Sherif autokinetic study","tell":"Asch = obvious (unambiguous) lines, NORMATIVE influence; Sherif = ambiguous moving light, INFORMATIONAL influence.","aliases":["asch","line judgement","line judgment","asch conformity","experiments on conformity","asch paradigm"],"lookId":"autokinetic-effect"},{"id":"sherif-autokinetic","name":"Sherif autokinetic effect study","cat":"experiment","area":"social","who":"Muzafer Sherif","year":"1935","def":"In a dark room a stationary pinpoint of light seems to move. Individuals' estimates of how far it moved converged in groups into a shared norm, which they kept even when later tested alone.","detail":"Used the autokinetic effect (an illusion). Ambiguous task, so people use others as information (informational social influence). Group norms persisted in later individual sessions, showing internalisation. Published in The Psychology of Social Norms (1936).","example":"'Formation of group norms in an ambiguous situation' is Sherif's autokinetic study.","look":"Asch line-judgement study","tell":"Sherif = ambiguous LIGHT, private acceptance; Asch = clear LINES, public compliance.","aliases":["autokinetic","autokinetic effect","sherif 1935","pinpoint of light"],"lookId":"asch-conformity"},{"id":"festinger-carlsmith","name":"$1/$20 experiment (forced compliance)","cat":"experiment","area":"social","who":"Leon Festinger & James Carlsmith","year":"1959","def":"Students who were paid only $1 to tell someone a boring task was fun later rated the task as more enjoyable than those paid $20. Too little external justification creates dissonance, which is reduced by changing the attitude.","detail":"71 male Stanford students did an hour of dull tasks (turning pegs, loading spools). Paid $1 or $20 to tell a waiting 'participant' (a confederate) that the task was interesting; controls told no lie. $1 group rated the task most enjoyable. Classic support for cognitive dissonance theory (Festinger 1957) and insufficient justification.","example":"'Participants paid less for lying changed their attitude more' is Festinger & Carlsmith.","look":"Aronson & Mills initiation study","tell":"$1/$20 = insufficient REWARD for lying; Aronson & Mills = SEVERE initiation, effort justification.","aliases":["festinger and carlsmith","festinger & carlsmith","$1/$20","one dollar twenty dollar","forced compliance","insufficient justification","boring task"],"lookId":"aronson-mills"},{"id":"aronson-mills","name":"Aronson & Mills initiation study","cat":"experiment","area":"social","who":"Elliot Aronson & Judson Mills","year":"1959","def":"Women who went through an embarrassing, severe initiation to join a discussion group later rated the group's dull discussion as more interesting. We value what we suffered for (effort justification).","detail":"Female college students wanting to join a group discussing the psychology of sex. Severe initiation: reading obscene words and explicit passages aloud to a male experimenter; mild: reading mild sex-related words; control: none. Then they heard a deliberately boring recorded discussion (about animal sexual behaviour). Severe group liked it most.","example":"Hazing or tough admission rituals increasing loyalty is explained by Aronson & Mills.","look":"$1/$20 experiment","tell":"Aronson & Mills = high COST (effort) raises liking; Festinger & Carlsmith = low PAY raises liking.","aliases":["aronson and mills","severity of initiation","effort justification"]},{"id":"seizure-study","name":"Darley & Latane seizure (intercom) study","cat":"experiment","area":"social","who":"John Darley & Bibb Latane","year":"1968","def":"Students talking over an intercom heard another student apparently have a seizure. The more people they believed were listening, the less likely and slower they were to help.","detail":"Participants believed the group was 2, 3 or 6 people. Alone with the victim, 85% helped before the seizure ended; with four others believed present, only 31%. Explained by diffusion of responsibility. Prompted by the Kitty Genovese case.","example":"'Helping decreased as the number of perceived bystanders increased' is the Darley & Latane seizure study.","look":"Smoke-filled room study","tell":"Seizure = diffusion of RESPONSIBILITY (can't see others); smoke room = pluralistic IGNORANCE (others look calm).","aliases":["seizure study","intercom study","diffusion of responsibility study","darley and latane"],"lookId":"smoke-filled-room"},{"id":"smoke-filled-room","name":"Smoke-filled room study","cat":"experiment","area":"social","who":"Bibb Latane & John Darley","year":"1968","def":"Students filling out forms saw smoke pour into the room. Alone, most reported it; with passive confederates who ignored the smoke, very few did.","detail":"Alone: 75% reported the smoke (most within 2 minutes). With two passive confederates: only 10% reported it. Three naive participants together: 38%. Others' calm was read as a sign of no emergency (pluralistic ignorance, a social-influence step in Latane & Darley's 5-step decision model).","example":"'Participants failed to report smoke when others nearby ignored it' is the smoke-filled room study.","look":"Darley & Latane seizure study","tell":"Smoke = defining the situation (is it an emergency?); seizure = taking responsibility (must I act?).","aliases":["smoke-filled room","smoke filled room","smoke study","pluralistic ignorance"],"lookId":"seizure-study"},{"id":"kitty-genovese","name":"Kitty Genovese case","cat":"experiment","area":"social","who":"Real case (reported by The New York Times)","year":"1964","def":"Catherine 'Kitty' Genovese was murdered outside her apartment in Queens, New York; the press reported that 38 neighbours witnessed it and none helped. The case inspired research on the bystander effect.","detail":"Reported by the New York Times (A. M. Rosenthal). Later investigations found the '38 witnesses who did nothing' account was exaggerated: few saw the attack and some did call. Led directly to Darley & Latane's bystander studies (1968).","example":"'Which incident triggered research on bystander apathy?' Kitty Genovese.","look":"Darley & Latane seizure study","tell":"Genovese = the real 1964 MURDER that inspired the work; seizure study = the 1968 LAB experiment that tested it.","aliases":["kitty genovese","genovese","38 witnesses"],"lookId":"seizure-study"},{"id":"good-samaritan","name":"Good Samaritan study","cat":"experiment","area":"social","who":"John Darley & Daniel Batson","year":"1973","def":"Seminary students on their way to give a talk passed a slumped, groaning man. Whether they helped depended mostly on how much of a hurry they were in, not on what talk they were about to give.","detail":"Princeton Theological Seminary students; talk topic was either the Good Samaritan parable or seminary jobs. Helped: low hurry 63%, intermediate hurry 45%, high hurry 10%. Topic had no significant effect; some stepped over the victim. Situational factors beat dispositional ones.","example":"'Time pressure predicted helping better than religiosity' is Darley & Batson.","look":"Darley & Latane seizure study","tell":"Good Samaritan = HURRY reduces helping; seizure = NUMBER OF BYSTANDERS reduces helping.","aliases":["good samaritan","darley and batson","darley & batson","seminary students"],"lookId":"seizure-study"},{"id":"asch-warm-cold","name":"Asch warm-cold impression formation study","cat":"experiment","area":"social","who":"Solomon Asch","year":"1946","def":"People read a list of traits describing a person; swapping only 'warm' for 'cold' changed the whole impression. Some traits are central and colour everything else.","detail":"List: intelligent, skilful, industrious, warm/cold, determined, practical, cautious. Warm version rated generous, happy, humorous; cold version the opposite. Swapping 'polite' and 'blunt' made little difference (peripheral traits). Asch also showed a primacy effect: 'intelligent ... envious' vs 'envious ... intelligent' produced different impressions. Supports a Gestalt view of impression formation.","example":"'Central traits in impression formation' points to Asch 1946.","look":"Kelley warm-cold lecturer study","tell":"Asch = trait LISTS on paper; Kelley = a real guest LECTURER introduced as warm or cold.","aliases":["warm-cold","warm cold","central traits","impression formation","central trait"],"lookId":"kelley-warm-cold"},{"id":"kelley-warm-cold","name":"Kelley warm-cold guest lecturer study","cat":"experiment","area":"social","who":"Harold Kelley","year":"1950","def":"Students were told a guest lecturer was either 'rather warm' or 'rather cold' before he led a class discussion. Those told 'warm' rated him more favourably and joined in more, though all saw the same lecture.","detail":"MIT students; written biographical note differed in one phrase. About 56% of the 'warm' group participated in the discussion vs about 32% of the 'cold' group. Real-life extension of Asch's central traits.","example":"Expectations about a lecturer shaping both ratings and behaviour is Kelley 1950.","look":"Asch warm-cold study","tell":"Kelley = a LIVE person in class; Asch = a written LIST of traits.","aliases":["kelley warm cold","guest lecturer","rather warm","rather cold"],"lookId":"asch-warm-cold"},{"id":"tajfel-minimal-group","name":"Minimal group studies","cat":"experiment","area":"social","who":"Henri Tajfel (with Billig, Bundy & Flament)","year":"1970/1971","def":"Boys divided into groups on a trivial basis (which abstract painter they preferred) still favoured their own group when sharing out points. Mere categorisation is enough to produce in-group favouritism.","detail":"Schoolboys aged 14-15 in Bristol. Grouping by preference for Klee vs Kandinsky paintings or by over- vs under-estimating dots. Allocation matrices showed boys often chose to MAXIMISE THE DIFFERENCE in favour of their group even at the cost of getting less overall. No contact, no history, no self-interest. Led to social identity theory (Tajfel & Turner 1979).","example":"'In-group bias without any competition or interaction' is Tajfel's minimal group paradigm.","look":"Robbers Cave experiment","tell":"Tajfel = trivial LABELS are enough; Sherif = needed real COMPETITION for prizes.","aliases":["minimal group","klee and kandinsky","klee kandinsky","tajfel","minimal group paradigm"],"lookId":"robbers-cave"},{"id":"hofling-hospital","name":"Hofling hospital (nurses) study","cat":"experiment","area":"social","who":"Charles Hofling","year":"1966","def":"Nurses received a phone order from an unknown 'doctor' to give twice the maximum dose of an unfamiliar drug; nearly all prepared to do it. Obedience to authority in a real workplace.","detail":"22 nurses; caller 'Dr Smith' from the psychiatric department; drug 'Astroten' (a placebo), label maximum 10 mg, order 20 mg. 21 of 22 (95%) were stopped on the way to give it. Broke rules on phone orders, unknown doctors and dosage. Rank & Jacobson (1977) replication with Valium and a known doctor: only 2 of 18 complied.","example":"'Field study of obedience among nurses' is Hofling 1966.","look":"Milgram obedience study","tell":"Hofling = NURSES, phone order, real hospital (field); Milgram = volunteers, shocks, Yale lab.","aliases":["hofling","astroten","nurses study","dr smith"],"lookId":"milgram-obedience"},{"id":"lapiere","name":"LaPiere attitude-behaviour study","cat":"experiment","area":"social","who":"Richard LaPiere","year":"1934","def":"LaPiere travelled across the US with a Chinese couple and was refused service only once; yet later, when asked by letter, most of the same places said they would not serve Chinese guests. Attitudes do not always predict behaviour.","detail":"Travel 1930-1932; about 250 hotels, auto camps and restaurants visited, served at all but one. Six months later, of about 128 that replied to a questionnaire, over 90% said they would not accept Chinese customers. Classic attitude-behaviour gap (inconsistency).","example":"'Stated attitudes differed from actual behaviour toward a Chinese couple' is LaPiere 1934.","look":"Clark doll test","tell":"LaPiere = attitudes vs BEHAVIOUR toward Chinese travellers; Clark = Black children's DOLL preference.","aliases":["lapiere","la piere","chinese couple"],"lookId":"clark-doll"},{"id":"clark-doll","name":"Clark doll test","cat":"experiment","area":"social","who":"Kenneth B. Clark & Mamie Phipps Clark","year":"1940s (published 1947)","def":"Black children were shown Black and white dolls and most preferred the white doll and attributed good qualities to it, showing internalised effects of segregation and racism.","detail":"Children aged about 3-7; asked which doll is nice, which is bad, which looks like you. Cited in the US Supreme Court case Brown v. Board of Education (1954), which ended school segregation.","example":"'Doll preference research cited in Brown v. Board of Education' is the Clark doll test.","look":"Jane Elliott blue eyes/brown eyes","tell":"Clark = measuring children's racial SELF-image with dolls; Elliott = a classroom DEMONSTRATION creating discrimination by eye colour.","aliases":["clark doll","doll test","clark and clark","brown v board"],"lookId":"blue-eyes-brown-eyes"},{"id":"blue-eyes-brown-eyes","name":"Blue eyes/brown eyes exercise","cat":"experiment","area":"social","who":"Jane Elliott","year":"1968","def":"A schoolteacher divided her class by eye colour and told one group they were superior; within a day the 'superior' children became bossy and the others' schoolwork and mood dropped. A demonstration of how arbitrary discrimination works.","detail":"Third-grade class in Riceville, Iowa, the day after Martin Luther King Jr. was assassinated (April 1968). Roles reversed the next day. Documented in 'The Eye of the Storm' (1970) and 'A Class Divided' (1985). A classroom exercise, not a controlled experiment.","example":"'A teacher's eye-colour exercise on discrimination' is Jane Elliott.","look":"Tajfel minimal group studies","tell":"Elliott = a teacher telling one group they are SUPERIOR (status given); Tajfel = neutral labels with no status, bias still appears.","aliases":["blue eyes brown eyes","blue eyes/brown eyes","jane elliott","a class divided"],"lookId":"tajfel-minimal-group"},{"id":"triplett","name":"Triplett cyclist (fishing reel) study","cat":"experiment","area":"social","who":"Norman Triplett","year":"1898","def":"Triplett noticed cyclists rode faster when racing others than alone, then found children wound fishing reels faster in pairs than alone. Often called the first social psychology experiment; the start of social facilitation research.","detail":"Analysed cycling records (paced and competitive races faster than solo). Lab task: children winding a fishing reel on a 'competition machine'. Term social facilitation later from Floyd Allport (1920); Zajonc (1965) explained it by arousal/drive (helps simple, hurts complex tasks).","example":"'The first experiment in social psychology' is Triplett 1898.","look":"Ringelmann rope-pulling","tell":"Triplett = others present make you work HARDER (facilitation); Ringelmann = in a group effort you work LESS (loafing).","aliases":["triplett","fishing reel","cyclists study","competition machine"],"lookId":"ringelmann"},{"id":"ringelmann","name":"Ringelmann rope-pulling study","cat":"experiment","area":"social","who":"Max Ringelmann","year":"1880s (published 1913)","def":"Men pulling on a rope exerted less effort each as the group got bigger. The first evidence of what was later called social loafing (the Ringelmann effect).","detail":"A French agricultural engineer; individual effort per person dropped as group size rose (a group of 8 pulled with far less than 8 times one person's force). Ingham and colleagues (1974) showed it occurs even with fake groups, so it is motivation loss, not just coordination loss.","example":"'Rope pulling showed per-person effort falls as group size rises' is Ringelmann.","look":"Latane clapping study","tell":"Ringelmann = ROPE pulling, the original effect; Latane = CLAPPING/shouting, coined 'social loafing'.","aliases":["ringelmann","rope pulling","ringelmann effect","tug of war"],"lookId":"latane-clapping"},{"id":"latane-clapping","name":"Latane clapping and shouting study","cat":"experiment","area":"social","who":"Bibb Latane, Kipling Williams & Stephen Harkins","year":"1979","def":"Students clapped and shouted as loudly as they could alone or in groups; the noise each person made dropped as the group grew. Coined the term 'social loafing'.","detail":"Blindfolded and wearing headphones playing noise; in pseudo-groups they only believed others were shouting, yet still produced less, showing motivation loss. Reduced when individual output is identifiable.","example":"'Who coined social loafing using clapping and shouting?' Latane, Williams & Harkins.","look":"Ringelmann rope-pulling","tell":"Clapping (1979) NAMED social loafing; rope pulling (1880s) first SHOWED it.","aliases":["clapping and shouting","latane williams harkins","social loafing study"],"lookId":"ringelmann"},{"id":"darley-gross","name":"Darley & Gross 'Hannah' study","cat":"experiment","area":"social","who":"John Darley & Paget Gross","year":"1983","def":"Viewers judged the academic ability of a girl named Hannah after watching her take an ambiguous test; those who believed she came from a wealthy background rated her higher. Stereotypes bias how we read ambiguous evidence.","detail":"Video showed Hannah in a poor urban or an affluent suburban setting. Without the test video, ratings did not differ; after seeing the same ambiguous test performance, 'rich Hannah' was rated above grade level and 'poor Hannah' below. Stereotypes act as hypotheses that are then 'confirmed'.","example":"'Stereotypes biasing interpretation of an ambiguous performance (Hannah)' is Darley & Gross.","look":"Rosenthal & Jacobson Oak School","tell":"Darley & Gross = observers JUDGING Hannah differently; Pygmalion = teacher expectations actually CHANGING pupils' scores.","aliases":["hannah study","darley and gross","darley & gross"],"lookId":"pygmalion-oak-school"},{"id":"schachter-singer","name":"Schachter & Singer epinephrine study","cat":"experiment","area":"social","who":"Stanley Schachter & Jerome Singer","year":"1962","def":"Men injected with adrenaline (epinephrine) who were not told about its effects took on the mood of a stooge who was acting either euphoric or angry. Emotion = physiological arousal plus a cognitive label.","detail":"184 male students told they were getting 'Suproxin', a vitamin, to test vision. Groups: epinephrine informed, misinformed, ignorant, and a placebo group. Stooge was euphoric (paper planes, hula hoop) or angry (insulting questionnaire). Uninformed/misinformed participants caught the stooge's emotion most; informed ones had an explanation for their arousal. Supports the two-factor theory.","example":"'Emotion depends on arousal plus cognitive labelling' points to the Schachter & Singer experiment.","look":"Dutton & Aron bridge study","tell":"Schachter & Singer = arousal from an INJECTION labelled using a stooge; Dutton & Aron = arousal from a scary BRIDGE misread as attraction.","aliases":["schachter and singer","schachter & singer","suproxin","epinephrine","adrenaline injection","two factor experiment"],"lookId":"capilano-bridge"},{"id":"capilano-bridge","name":"Capilano bridge study","cat":"experiment","area":"social","who":"Donald Dutton & Arthur Aron","year":"1974","def":"Men crossing a high, swaying suspension bridge were more likely to call an attractive female interviewer afterwards than men crossing a low, solid bridge. Arousal from fear was misattributed to attraction.","detail":"Capilano Canyon suspension bridge, Vancouver, Canada vs a sturdy low bridge. Interviewer asked men to write a story about a TAT picture and gave her phone number. Fear-bridge men wrote stories with more sexual imagery and more called her (about 9 of 18 vs 2 of 16). Misattribution of arousal.","example":"'Shaky bridge and attraction' is Dutton & Aron.","look":"Schachter & Singer epinephrine study","tell":"Dutton & Aron = real-world FIELD study on a bridge; Schachter & Singer = LAB injection study.","aliases":["capilano","suspension bridge","shaky bridge","dutton and aron","dutton & aron"],"lookId":"schachter-singer"},{"id":"cannon-washburn","name":"Cannon & Washburn balloon study","cat":"experiment","area":"biological","who":"Walter Cannon & A. L. Washburn","year":"1912","def":"Washburn swallowed a balloon attached to a tube so stomach contractions could be recorded; his reports of hunger pangs coincided with the contractions. Supported a stomach (local) theory of hunger.","detail":"Later evidence weakened the theory: people whose stomachs had been removed or whose stomach nerves were cut still felt hunger, pointing to brain (hypothalamic) and blood-glucose signals.","example":"'Hunger caused by stomach contractions' (swallowed balloon) is Cannon & Washburn.","look":"Olds & Milner pleasure centre","tell":"Cannon & Washburn = a BALLOON in the stomach for hunger; Olds & Milner = ELECTRODES in the brain for reward.","aliases":["cannon and washburn","swallowed a balloon","balloon study","stomach contractions"],"lookId":"olds-milner"},{"id":"little-albert","name":"Little Albert experiment","cat":"experiment","area":"learning","who":"John B. Watson & Rosalie Rayner","year":"1920","def":"An infant who first showed no fear of a white rat was conditioned to fear it by pairing it with a sudden loud noise. Showed that emotional responses like fear can be classically conditioned.","detail":"Albert B. was about 9 months at baseline and 11 months when conditioning began. Rat (CS) + steel bar struck by a hammer behind his head (UCS) gave fear (CR). Fear generalised to a rabbit, a dog, a fur coat, cotton wool and a Santa Claus mask. He left the hospital before any deconditioning. Ethically condemned today.","example":"'Which experiment showed conditioned emotional response and stimulus generalisation in a child?' Little Albert.","look":"Little Peter","tell":"Albert = fear was CREATED by conditioning (Watson); Peter = fear was REMOVED by counterconditioning (Jones).","aliases":["little albert","little albert' experiment","albert b","watson and rayner","watson & rayner","white rat"],"lookId":"little-peter"},{"id":"little-peter","name":"Little Peter case","cat":"experiment","area":"clinical","who":"Mary Cover Jones","year":"1924","def":"A young boy's fear of rabbits was removed by gradually bringing a rabbit closer while he ate something he liked, and by letting him watch other children play with it. Early demonstration of counterconditioning.","detail":"Peter was about 3 years old (2 years 10 months). Methods: direct conditioning (rabbit paired with food, moved closer step by step) and social imitation. Forerunner of Wolpe's systematic desensitisation; Jones is called 'the mother of behaviour therapy'. Done under Watson's supervision.","example":"'First use of counterconditioning to remove a child's phobia' is Mary Cover Jones's Little Peter.","look":"Little Albert","tell":"Peter = UN-conditioning a rabbit fear (1924, Jones); Albert = conditioning a rat fear (1920, Watson).","aliases":["little peter","mary cover jones","peter and the rabbit"],"lookId":"stimulus-generalization"},{"id":"pavlov-dogs","name":"Pavlov's dogs","cat":"experiment","area":"learning","who":"Ivan Pavlov","year":"1890s-1900s","def":"While studying digestion, Pavlov found dogs began to salivate to signals that came before food. Pairing a neutral stimulus with food made it alone trigger salivation: classical conditioning.","detail":"Saliva collected through a surgical fistula. Meat powder = UCS; salivation = UCR; metronome/bell/tone = CS; salivation to CS = CR. Studied acquisition, extinction, spontaneous recovery, generalisation, discrimination, higher-order conditioning. Experimental neurosis: dogs broke down when circle vs ellipse discrimination was made too hard. Nobel Prize 1904 for work on digestion (not conditioning).","example":"'Salivation to a metronome before food' means Pavlov and classical conditioning.","look":"Thorndike puzzle box","tell":"Pavlov = REFLEX to a signal (classical); Thorndike = ACTION to escape and get food (instrumental).","aliases":["pavlov","pavlov's dogs","salivating dogs","metronome","pavlovian"],"lookId":"thorndike-puzzle-box"},{"id":"thorndike-puzzle-box","name":"Thorndike puzzle box","cat":"experiment","area":"learning","who":"Edward L. Thorndike","year":"1898","def":"Hungry cats in a box learned to pull a string or press a lever to escape and reach food. Escape time fell gradually across trials (trial-and-error), leading to the law of effect.","detail":"Doctoral dissertation 'Animal Intelligence' (1898); also used chicks and dogs. Learning curves were gradual, not sudden, so Thorndike argued against insight. Laws: effect, exercise, readiness. Called instrumental learning; foundation for Skinner's operant conditioning.","example":"'Cats escaping from a puzzle box' means Thorndike, trial-and-error learning, law of effect.","look":"Kohler's chimpanzees","tell":"Thorndike = GRADUAL trial-and-error in cats; Kohler = SUDDEN insight in chimps.","aliases":["puzzle box","thorndike","thorndike's cats","law of effect experiment"],"lookId":"kohler-chimps"},{"id":"skinner-box","name":"Skinner box (operant chamber)","cat":"experiment","area":"learning","who":"B. F. Skinner","year":"1930s","def":"A chamber in which a rat presses a lever (or a pigeon pecks a key) and receives food, with responses recorded automatically. Used to study how consequences and schedules of reinforcement shape behaviour.","detail":"Cumulative recorder plots response rate. The Behavior of Organisms (1938); Schedules of Reinforcement (Ferster & Skinner 1957): FR, VR, FI, VI. Shaping by successive approximations. 'Superstition in the pigeon' (1948): food at fixed times produced odd ritual behaviours. Pigeon-guided missile (Project Pigeon).","example":"'Lever pressing in an operant chamber' means Skinner.","look":"Thorndike puzzle box","tell":"Skinner box = animal STAYS inside, free responding, rate measured; puzzle box = animal ESCAPES, time to escape measured.","aliases":["skinner box","operant chamber","skinner's rats","superstition in the pigeon"],"lookId":"thorndike-puzzle-box"},{"id":"tolman-honzik","name":"Tolman & Honzik latent learning study","cat":"experiment","area":"learning","who":"Edward Tolman & Charles Honzik","year":"1930","def":"Rats that explored a maze for days without reward made few apparent gains, but once food was introduced they almost immediately ran it as well as rats rewarded all along. Learning had happened without reinforcement (latent learning).","detail":"Three groups in a 14-unit T-maze: always rewarded; never rewarded; rewarded from day 11. Group 3's errors dropped sharply on day 12, matching or beating group 1. Tolman argued rats form a cognitive map ('Cognitive maps in rats and men', 1948). Also place learning studies.","example":"'Tolman's rat maze studies' showed latent learning and cognitive maps.","look":"Kohler's chimpanzees","tell":"Tolman = rats with a hidden MAP shown once reward appears; Kohler = apes with sudden INSIGHT solving a problem.","aliases":["tolman","tolman's rat maze studies","tolman and honzik","latent learning study","cognitive map","rat maze"],"lookId":"kohler-chimps"},{"id":"kohler-chimps","name":"Kohler's chimpanzees (Sultan)","cat":"experiment","area":"learning","who":"Wolfgang Kohler","year":"1913-1917","def":"Chimpanzees solved problems such as reaching hanging bananas by suddenly combining tools, e.g. stacking boxes or joining two sticks. Learning by insight, not trial and error.","detail":"Done on Tenerife, Canary Islands. Sultan joined two short bamboo sticks to rake in fruit. Book 'The Mentality of Apes' (1917 German, 1925 English). Gestalt psychologist; features of insight: sudden, transferable, retained ('aha').","example":"'Learning and insight in chimpanzees' (Sultan) means Kohler.","look":"Thorndike puzzle box","tell":"Kohler = sudden INSIGHT (Gestalt); Thorndike = gradual TRIAL AND ERROR (connectionism).","aliases":["kohler","kohler's chimps","sultan","mentality of apes","stick problem","box stacking","learning and insight"],"lookId":"thorndike-puzzle-box"},{"id":"seligman-maier","name":"Seligman & Maier learned helplessness dogs","cat":"experiment","area":"learning","who":"Martin Seligman & Steven Maier","year":"1967","def":"Dogs that had earlier received shocks they could not escape later failed to escape shocks in a shuttle box even when escape was easy. Uncontrollable events teach helplessness.","detail":"Triadic design: escapable shock (could press a panel to stop it), yoked inescapable shock (same shocks, no control), no shock. Most yoked dogs lay down and whined; the others learned to jump the barrier. Also Overmier & Seligman (1967). Became a model of depression; later reformulated with attributions (Abramson, Seligman & Teasdale 1978).","example":"'Dogs given inescapable shock stopped trying' is learned helplessness (Seligman).","look":"Langer & Rodin nursing home study","tell":"Seligman = LOSS of control causes helplessness (dogs); Langer & Rodin = GIVING control improves well-being (elderly).","aliases":["learned helplessness","seligman","seligman's dogs","seligman and maier","shuttle box"],"lookId":"langer-rodin"},{"id":"garcia-koelling","name":"Garcia & Koelling taste aversion study","cat":"experiment","area":"learning","who":"John Garcia & Robert Koelling","year":"1966","def":"Rats easily learned to avoid a taste paired with illness, and lights and sounds paired with shock, but not the reverse. Some associations are biologically 'prepared'.","detail":"'Bright-noisy-tasty water': licking produced flavour plus light and click. Illness (X-ray radiation or lithium chloride) produced aversion to the taste only; shock produced avoidance of the light/noise only. Challenged equipotentiality; showed belongingness. Taste aversion forms in one trial even with hours of delay (Garcia effect).","example":"'Rats associate taste with nausea but not lights' is Garcia & Koelling, biological preparedness.","look":"Seligman & Maier dogs","tell":"Garcia = which stimuli CAN be linked (preparedness); Seligman = what happens when responses DON'T matter (helplessness).","aliases":["garcia","garcia and koelling","garcia effect","taste aversion","bright noisy water","bright-noisy-tasty water"],"lookId":"seligman-maier"},{"id":"rosenthal-maze-bright","name":"Maze-bright and maze-dull rats","cat":"experiment","area":"research","who":"Robert Rosenthal & Kermit Fode","year":"1963","def":"Students were told their rats were bred to be 'maze-bright' or 'maze-dull' (though rats were assigned at random); the 'bright' rats learned the maze faster. Experimenters' expectations influence results.","detail":"Experimenter expectancy effect (Rosenthal effect). Argues for double-blind procedures. A forerunner of the Oak School classroom study.","example":"'Students' beliefs about their rats affected the rats' performance' is Rosenthal's maze-bright study.","look":"Tryon's selectively bred rats","tell":"Rosenthal = rats were IDENTICAL, only beliefs differed; Tryon (1940) = rats were genetically BRED bright or dull.","aliases":["maze-bright","maze bright","maze-dull","maze dull","rosenthal and fode","experimenter expectancy"]},{"id":"pygmalion-oak-school","name":"Pygmalion in the Classroom (Oak School)","cat":"experiment","area":"developmental","who":"Robert Rosenthal & Lenore Jacobson","year":"1968","def":"Teachers were told some randomly chosen pupils were about to 'bloom' intellectually; by year's end those pupils showed greater IQ gains. Teacher expectations can become self-fulfilling prophecies.","detail":"Oak School, an elementary school in South San Francisco. About 20% of pupils labelled 'bloomers' on the basis of a supposed test of inflected acquisition. Effect clearest in grades 1 and 2. Called the Pygmalion effect or Rosenthal effect; criticised for weak replication.","example":"'Teacher expectations raised IQ of randomly labelled bloomers' is Rosenthal & Jacobson.","look":"Maze-bright and maze-dull rats","tell":"Oak School = TEACHERS and children; maze-bright = STUDENTS and rats. Both Rosenthal, both expectancy.","aliases":["pygmalion","pygmalion in the classroom","oak school","rosenthal and jacobson","bloomers","self-fulfilling prophecy study"],"lookId":"rosenthal-maze-bright"},{"id":"lepper-magic-markers","name":"Magic markers (overjustification) study","cat":"experiment","area":"social","who":"Mark Lepper, David Greene & Richard Nisbett","year":"1973","def":"Preschoolers who already liked drawing and were promised a reward for it later drew less in free play than children who got no reward or an unexpected one. Expected rewards can undermine intrinsic motivation.","detail":"Three groups: expected award (a 'Good Player' certificate), unexpected award, no award. Measured free-time drawing 1-2 weeks later: the expected-award group drew about half as much. Overjustification effect.","example":"'Rewarding children for drawing reduced their later interest' is Lepper, Greene & Nisbett.","look":"$1/$20 experiment","tell":"Magic markers = BIG expected reward kills intrinsic interest; $1/$20 = SMALL reward makes attitude change more.","aliases":["magic markers","overjustification","lepper greene nisbett","good player award"]},{"id":"langer-rodin","name":"Langer & Rodin nursing home (plant) study","cat":"experiment","area":"developmental","who":"Ellen Langer & Judith Rodin","year":"1976","def":"Nursing home residents given responsibility (choosing and caring for a plant, choosing a movie night) became happier and more active than those whose care was handled by staff, and fewer died over the next 18 months.","detail":"Arden House, Connecticut. Fourth floor: responsibility-induced group; second floor: comparison group told staff would look after them. 18-month follow-up (Rodin & Langer 1977): about 15% vs 30% mortality. Perceived control and well-being.","example":"'Giving elderly residents choice and a plant improved health' is Langer & Rodin.","look":"Seligman & Maier dogs","tell":"Langer & Rodin = ADDING control helps; Seligman = REMOVING control harms.","aliases":["langer and rodin","nursing home study","plant study","arden house"],"lookId":"seligman-maier"},{"id":"harlow-monkeys","name":"Harlow's monkeys (wire vs cloth mother)","cat":"experiment","area":"developmental","who":"Harry Harlow","year":"1958","def":"Infant rhesus monkeys clung to a soft cloth 'mother' rather than a wire one that gave milk, and ran to the cloth mother when frightened. Attachment rests on contact comfort, not just feeding.","detail":"Paper 'The Nature of Love' (1958); Harlow & Zimmermann (1959). Monkeys fed by the wire mother still spent most of their time on the cloth mother. Refuted the 'cupboard love' (drive-reduction) account of attachment. Total social isolation (up to 12 months) produced lasting social, sexual and parenting deficits; 'pit of despair' studies with Suomi.","example":"'Contact comfort' and wire vs cloth surrogate mothers mean Harlow.","look":"Lorenz's geese","tell":"Harlow = monkeys need CONTACT COMFORT; Lorenz = goslings IMPRINT on the first moving object.","aliases":["harlow","harlow's monkeys","wire mother","cloth mother","contact comfort","surrogate mother","rhesus monkeys"],"lookId":"imprinting"},{"id":"lorenz-geese","name":"Lorenz's geese (imprinting)","cat":"experiment","area":"developmental","who":"Konrad Lorenz","year":"1935","def":"Greylag goslings that saw Lorenz first after hatching followed him around as if he were their mother. Imprinting occurs during a critical period soon after birth.","detail":"Split a clutch: half saw the mother goose first, half saw Lorenz; each followed its first object. Critical period in the first hours/days; imprinting thought irreversible and to affect later mate preference. Ethologist; Nobel Prize 1973 with Tinbergen and von Frisch.","example":"'Goslings following a scientist' means Lorenz and imprinting.","look":"Harlow's monkeys","tell":"Lorenz = birds IMPRINT on a moving object quickly; Harlow = primates attach for COMFORT.","aliases":["lorenz","imprinting","lorenz's geese","greylag geese","goslings"],"lookId":"harlow-monkeys"},{"id":"tinbergen","name":"Tinbergen's sticklebacks and gulls","cat":"experiment","area":"biological","who":"Niko Tinbergen","year":"1950s","def":"Male sticklebacks attacked any object with a red underside, and herring gull chicks pecked at a red spot on a model beak. Instinctive behaviour is set off by simple sign stimuli.","detail":"Fixed action patterns released by sign stimuli (releasers); supernormal stimuli (exaggerated models drew stronger responses). Book 'The Study of Instinct' (1951). Four questions of ethology (1963). Nobel 1973 with Lorenz and von Frisch.","example":"'Red belly triggers attack in stickleback' means Tinbergen, sign stimulus.","look":"Lorenz's geese","tell":"Tinbergen = SIGN STIMULI triggering fixed actions; Lorenz = IMPRINTING on a first-seen object.","aliases":["tinbergen","stickleback","herring gull","sign stimulus","fixed action pattern"],"lookId":"imprinting"},{"id":"strange-situation","name":"Strange Situation","cat":"experiment","area":"developmental","who":"Mary Ainsworth (with Silvia Bell; Ainsworth, Blehar, Waters & Wall)","year":"1970/1978","def":"A lab procedure in which a 12-18-month-old is separated from and reunited with the caregiver and meets a stranger; behaviour at reunion classifies attachment style.","detail":"8 episodes of about 3 minutes. Types: secure (B, about 65-70%), insecure-avoidant (A, about 20%), insecure-resistant/ambivalent (C, about 10-15%). Disorganised (D) added by Main & Solomon (1986/1990). Main book 'Patterns of Attachment' (1978). Key predictor: caregiver sensitivity.","example":"'Which procedure assesses infant attachment through separation and reunion?' Ainsworth's Strange Situation.","look":"Ainsworth Uganda/Baltimore studies","tell":"Strange Situation = the LAB test; Uganda/Baltimore = the earlier HOME observations it grew from.","aliases":["strange situation","ainsworth","strange situation test","secure attachment"],"lookId":"ainsworth-uganda-baltimore"},{"id":"ainsworth-uganda-baltimore","name":"Ainsworth Uganda and Baltimore studies","cat":"experiment","area":"developmental","who":"Mary Ainsworth","year":"1950s-1960s","def":"Ainsworth watched mothers and babies at home, first in Uganda and then in Baltimore, and linked mothers' sensitivity to babies' secure attachment. These naturalistic studies led to the Strange Situation.","detail":"Uganda: Ganda mothers and infants, book 'Infancy in Uganda' (1967). Baltimore: 26 families observed at home through the first year. Introduced the secure base concept and maternal sensitivity ratings.","example":"'Naturalistic observation of mother-infant pairs in Uganda' is Ainsworth.","look":"Strange Situation","tell":"Uganda/Baltimore = HOME observation; Strange Situation = structured LAB procedure.","aliases":["uganda","ganda","infancy in uganda","baltimore study"],"lookId":"strange-situation"},{"id":"schaffer-emerson","name":"Schaffer & Emerson Glasgow study","cat":"experiment","area":"developmental","who":"Rudolph Schaffer & Peggy Emerson","year":"1964","def":"A longitudinal study of Glasgow babies showed attachment forms to the person who responds most sensitively, not the one who feeds most, and that multiple attachments are common.","detail":"60 babies from working-class Glasgow families, visited monthly for the first year and again at 18 months; mothers reported separation protest and stranger anxiety. Stages: asocial (0-6 weeks), indiscriminate (6 weeks-7 months), specific (about 7 months), multiple. By 18 months most had multiple attachments.","example":"'Emerson's longitudinal study' of infant attachment stages is Schaffer & Emerson.","look":"Strange Situation","tell":"Schaffer & Emerson = STAGES of attachment over time, home visits; Ainsworth = TYPES of attachment in the lab.","aliases":["schaffer and emerson","emerson's longitudinal study","glasgow babies","schaffer & emerson"],"lookId":"strange-situation"},{"id":"still-face","name":"Still-face experiment","cat":"experiment","area":"developmental","who":"Edward Tronick (with Als, Adamson, Wise & Brazelton)","year":"1978","def":"A mother plays normally with her baby, then suddenly keeps a blank, unresponsive face. The baby first tries to re-engage, then becomes distressed and withdraws. Infants actively regulate social interaction.","detail":"Infants about 1-4 months. Phases: normal face-to-face play, still face (about 2 minutes), reunion. Babies smile, point, vocalise, then look away, slump, cry. Used to study emotion regulation and maternal depression.","example":"'Infants become distressed when the mother's face goes blank' is Tronick's still-face paradigm.","look":"Strange Situation","tell":"Still-face = mother PRESENT but unresponsive (young infants); Strange Situation = mother LEAVES (12-18 months).","aliases":["still-face","still face","tronick"],"lookId":"strange-situation"},{"id":"visual-cliff","name":"Visual cliff","cat":"experiment","area":"perception","who":"Eleanor Gibson & Richard Walk","year":"1960","def":"Crawling babies would not cross onto a glass surface that looked like a sudden drop, even when their mothers called. Depth perception is present by the time infants crawl.","detail":"36 infants aged 6-14 months: 27 crawled over the shallow side, only 3 crept onto the deep side. Also tested chicks, kids (goats), lambs, rats, which avoided the drop as soon as they could walk. Campos (1970) found 2-month-olds showed heart-rate slowing (interest, not fear) over the deep side, so fear comes with crawling experience.","example":"'Glass-topped table to test depth perception in infants' is Gibson & Walk's visual cliff.","look":"Fantz preferential looking","tell":"Visual cliff = DEPTH perception (crawlers); Fantz = FORM/face preference (newborns).","aliases":["visual cliff","gibson and walk","gibson & walk"],"lookId":"fantz-preferential-looking"},{"id":"fantz-preferential-looking","name":"Fantz preferential looking","cat":"experiment","area":"perception","who":"Robert Fantz","year":"1961","def":"Babies lying in a looking chamber looked longer at patterned stimuli, especially face-like ones, than at plain ones. Infants can perceive form and have built-in visual preferences from very early on.","detail":"'The origin of form perception' (Scientific American, 1961). Observer watched the reflection of the stimulus in the infant's eye to time looking. Preference: face > newsprint/bull's-eye > plain colour. Preferential looking became a standard infant method, alongside habituation.","example":"'Infants looked longer at faces than plain discs' is Fantz.","look":"Visual cliff","tell":"Fantz = WHAT babies prefer to look at; Gibson & Walk = whether babies perceive DEPTH.","aliases":["fantz","preferential looking","looking chamber"],"lookId":"visual-cliff"},{"id":"three-mountains","name":"Three mountains task","cat":"experiment","area":"developmental","who":"Jean Piaget & Barbel Inhelder","year":"1956 (French 1948)","def":"Children were shown a model of three mountains and asked what a doll on the other side would see. Preoperational children chose their own view, showing egocentrism.","detail":"Children picked from photographs; under about 7 most chose their own viewpoint. Hughes (1975) 'policeman doll' task, with a more meaningful setting, found 3-5-year-olds could take another's view, suggesting Piaget underestimated children.","example":"'Egocentrism tested with a model landscape and a doll' is the three mountains task.","look":"Piaget conservation tasks","tell":"Three mountains = EGOCENTRISM (whose view?); conservation = CENTRATION/irreversibility (same amount?).","aliases":["three mountains","three mountain","three-mountains task","egocentrism task"],"lookId":"conservation-tasks"},{"id":"conservation-tasks","name":"Piaget's conservation tasks","cat":"experiment","area":"developmental","who":"Jean Piaget","year":"1940s-1950s","def":"Children watch the same amount of liquid poured into a taller, thinner glass (or a row of counters spread out) and asked if it is still the same. Preoperational children say it changed; concrete operational children know it is the same.","detail":"Failure due to centration (focusing on one dimension) and irreversibility. Order mastered (horizontal decalage): number about 6-7, mass/substance 7-8, weight 9-10, volume 11-12. McGarrigle & Donaldson (1974) 'naughty teddy' accidental change produced more correct answers.","example":"'Tall thin glass and short wide glass' tests conservation (Piaget).","look":"Three mountains task","tell":"Conservation = QUANTITY stays the same; three mountains = VIEWPOINT of another.","aliases":["conservation task","conservation of liquid","conservation of number","naughty teddy","beaker task"],"lookId":"three-mountains"},{"id":"heinz-dilemma","name":"Heinz dilemma","cat":"experiment","area":"developmental","who":"Lawrence Kohlberg","year":"1958 (dissertation)","def":"A man named Heinz can save his dying wife only by stealing an overpriced drug. Kohlberg scored the reasoning behind people's answers, not the answer itself, to place them in stages of moral development.","detail":"Original sample 72 boys in Chicago aged 10, 13 and 16, followed longitudinally for about 20 years. 3 levels x 2 stages: preconventional, conventional, postconventional. Carol Gilligan (1982) criticised male bias and proposed an ethic of care.","example":"'Should Heinz steal the drug?' points to Kohlberg's moral reasoning stages.","look":"Piaget's moral stories","tell":"Kohlberg = HEINZ dilemma, 6 stages; Piaget = stories about broken CUPS (intentions vs damage), 2 stages.","aliases":["heinz","heinz dilemma","kohlberg's dilemma","moral dilemma"]},{"id":"marshmallow-test","name":"Marshmallow test","cat":"experiment","area":"personality","who":"Walter Mischel","year":"late 1960s-1970s","def":"Preschoolers could eat one treat now or wait (about 15 minutes) for two. Waiting ability was linked years later to better school and life outcomes. A measure of delay of gratification.","detail":"Stanford's Bing Nursery School (Mischel & Ebbesen 1970; Mischel, Ebbesen & Zeiss 1972). Strategies: distraction, covering the treat, 'cool' vs 'hot' thinking. Follow-ups (Shoda, Mischel & Peake 1990) linked waiting to SAT scores. Watts, Duncan & Quan (2018) found much weaker effects after controlling for family background.","example":"'Delay of gratification in children with treats' is Mischel's marshmallow test.","look":"Bobo doll experiment","tell":"Marshmallow = SELF-CONTROL (Mischel); Bobo = IMITATION (Bandura). Both Stanford preschools.","aliases":["marshmallow","marshmallow test","delay of gratification","mischel"],"lookId":"bobo-doll"},{"id":"spitz-hospitalism","name":"Spitz hospitalism study","cat":"experiment","area":"developmental","who":"Rene Spitz","year":"1945/1946","def":"Infants raised in a foundling home with adequate physical care but little individual attention declined badly in development and many died, unlike infants in a prison nursery cared for by their own mothers.","detail":"'Hospitalism' (1945). Also 'anaclitic depression' (1946): infants separated from mothers at about 6-12 months became withdrawn and weepy, recovering if reunited within about 3 months. Supported the importance of emotional care (with Bowlby's maternal deprivation work).","example":"'Hospitalism and anaclitic depression in institutionalised infants' is Spitz.","look":"Bowlby 44 juvenile thieves","tell":"Spitz = INFANTS in institutions; Bowlby = adolescent THIEVES with early separation.","aliases":["spitz","hospitalism","anaclitic depression","foundling home"],"lookId":"forty-four-thieves"},{"id":"forty-four-thieves","name":"Forty-four juvenile thieves","cat":"experiment","area":"clinical","who":"John Bowlby","year":"1944","def":"Bowlby compared 44 young thieves with 44 disturbed non-thieves and found that many 'affectionless' thieves had suffered prolonged separation from their mothers early in life. Basis of the maternal deprivation hypothesis.","detail":"London Child Guidance Clinic. 14 thieves were 'affectionless psychopaths'; 12 of these 14 had prolonged early separation, vs only 2 of the 44 controls. Retrospective and correlational. Led to Maternal Care and Mental Health (WHO, 1951).","example":"'Affectionless psychopathy linked to maternal separation' is Bowlby's 44 juvenile thieves.","look":"Robertson films","tell":"Bowlby 1944 = RETROSPECTIVE case records of thieves; Robertsons = FILMED children during short separations.","aliases":["44 juvenile thieves","forty-four juvenile thieves","forty four thieves","affectionless psychopathy","maternal deprivation"],"lookId":"robertson-films"},{"id":"robertson-films","name":"Robertson separation films","cat":"experiment","area":"developmental","who":"James & Joyce Robertson","year":"1952-1973","def":"Films of young children separated from parents (in hospital or residential nurseries) showed a sequence of protest, despair and detachment. Helped change hospital visiting rules.","detail":"'A Two-Year-Old Goes to Hospital' (1952, Laura). 'Young Children in Brief Separation' series (1967-1973), e.g. John, 17 months, 9 days in a residential nursery, deteriorated badly; children fostered by the Robertsons themselves coped much better. Protest-despair-detachment described with Bowlby.","example":"'Protest, despair, detachment shown on film' is the Robertsons.","look":"Forty-four juvenile thieves","tell":"Robertsons = SHORT separations filmed as they happened; Bowlby 1944 = LONG-TERM outcomes in thieves.","aliases":["robertson","john 17 months","a two-year-old goes to hospital","protest despair detachment"],"lookId":"forty-four-thieves"},{"id":"genie","name":"Genie case","cat":"experiment","area":"developmental","who":"Studied by Susan Curtiss (with Victoria Fromkin and others)","year":"1970 (discovered)","def":"A girl found at age 13 after years of extreme isolation and abuse learned many words but never mastered grammar. Used as evidence for a critical period for language.","detail":"Found in Los Angeles; had been kept strapped to a potty chair, rarely spoken to. Vocabulary grew, but syntax stayed very limited ('telegraphic'). Supports Lenneberg's (1967) critical period hypothesis, though abuse and possible disability complicate interpretation. Curtiss, 'Genie' (1977).","example":"'A feral/isolated child who could not acquire grammar after puberty' means Genie.","look":"Kellogg's Gua","tell":"Genie = a HUMAN child deprived of language; Gua = a CHIMP raised with a human child.","aliases":["genie","genie case","genie wiley","feral child"],"lookId":"kellogg-gua"},{"id":"kellogg-gua","name":"Kellogg's Gua (home-raised chimp)","cat":"experiment","area":"developmental","who":"Winthrop & Luella Kellogg","year":"1931-1932","def":"The Kelloggs raised a baby chimpanzee, Gua, alongside their son Donald for nine months. Gua never learned to speak, while Donald began copying Gua's chimp noises.","detail":"Gua was about 7.5 months, Donald about 10 months at the start. Book 'The Ape and the Child' (1933). Later Keith & Catherine Hayes raised Viki, who managed only about four spoken words (mama, papa, cup, up).","example":"'A chimp raised alongside a human baby' is the Kelloggs' Gua.","look":"Project Washoe","tell":"Gua = tried SPOKEN language; Washoe = taught SIGN language.","aliases":["gua","kellogg","the ape and the child","viki"],"lookId":"project-washoe"},{"id":"project-washoe","name":"Project Washoe","cat":"experiment","area":"cognitive","who":"R. Allen Gardner & Beatrix Gardner","year":"1966 (published 1969)","def":"The Gardners raised a chimpanzee, Washoe, and taught her American Sign Language; she learned well over a hundred signs and combined them in new ways. Started the ape-language debate.","detail":"Began in 1966 at the University of Nevada; reported in Science (1969). Famous combination: 'water bird' for a swan. Later passed signs to adopted son Loulis. Other ape projects: Premack's Sarah (plastic tokens), Savage-Rumbaugh's Kanzi (lexigram keyboard, bonobo).","example":"'A chimp taught American Sign Language' means Washoe (Gardner & Gardner).","look":"Project Nim","tell":"Washoe = optimistic SIGN-language claims; Nim = sceptical re-analysis showing imitation, no syntax.","aliases":["washoe","project washoe","gardner and gardner","water bird","kanzi","premack's sarah"],"lookId":"project-nim"},{"id":"project-nim","name":"Project Nim","cat":"experiment","area":"cognitive","who":"Herbert Terrace","year":"1979","def":"Terrace taught a chimp named Nim Chimpsky sign language, then analysed videotapes and concluded Nim mostly imitated his trainers and showed no real grammar.","detail":"Columbia University, 1970s; Nim learned about 125 signs. Long utterances were repetitive, not more complex; many signs prompted by teachers. Paper 'Can an ape create a sentence?' (Science, 1979). Name is a play on Noam Chomsky.","example":"'Ape signing was largely imitation without syntax' is Terrace's Project Nim.","look":"Project Washoe","tell":"Nim = the SCEPTIC (Terrace, 1979); Washoe = the PIONEER (Gardners, 1969).","aliases":["nim chimpsky","project nim","terrace"],"lookId":"project-washoe"},{"id":"ebbinghaus","name":"Ebbinghaus forgetting curve","cat":"experiment","area":"memory","who":"Hermann Ebbinghaus","year":"1885","def":"Ebbinghaus memorised lists of nonsense syllables himself and retested at intervals, finding that forgetting is fast at first and then levels off. The first experimental study of memory.","detail":"Book 'Uber das Gedachtnis' (Memory, 1885). Stimuli: consonant-vowel-consonant nonsense syllables (e.g. DAX). Measure: savings method (time saved in relearning). Most loss within the first hour or day, then slow. Also showed overlearning and the spacing effect; serial position effects in lists.","example":"'Nonsense syllables and the savings method' means Ebbinghaus.","look":"Bartlett War of the Ghosts","tell":"Ebbinghaus = MEANINGLESS syllables, how much is lost; Bartlett = MEANINGFUL story, how it is distorted.","aliases":["ebbinghaus","forgetting curve","nonsense syllables","savings method","curve of forgetting"],"lookId":"war-of-the-ghosts"},{"id":"war-of-the-ghosts","name":"War of the Ghosts","cat":"experiment","area":"memory","who":"Frederic Bartlett","year":"1932","def":"English participants retold a Native American folk tale over time; their versions got shorter and were changed to fit their own culture. Memory is reconstructive and shaped by schemas.","detail":"Book 'Remembering' (1932). Methods: repeated reproduction (same person) and serial reproduction (passed person to person, like Chinese whispers). Changes: omission of unfamiliar details, rationalisation, 'canoes' became 'boats', the supernatural element dropped or explained.","example":"'Memory distortions in recalling an unfamiliar folk story' is Bartlett's War of the Ghosts.","look":"Ebbinghaus forgetting curve","tell":"Bartlett = stories, SCHEMA distortion; Ebbinghaus = nonsense syllables, pure retention.","aliases":["war of the ghosts","bartlett","serial reproduction","reconstructive memory"],"lookId":"ebbinghaus"},{"id":"peterson-peterson","name":"Peterson & Peterson (Brown-Peterson) study","cat":"experiment","area":"memory","who":"Lloyd Peterson & Margaret Peterson","year":"1959","def":"People recalled a three-consonant trigram after counting backwards by threes for a few seconds; recall fell to about 10% after 18 seconds. Information in short-term memory fades very quickly without rehearsal.","detail":"Delays of 3, 6, 9, 12, 15, 18 seconds; counting backwards prevented rehearsal. Interpreted as decay; Keppel & Underwood (1962) showed early trials were remembered well, so proactive interference explains much of the loss. Brown (1958) did similar work, hence 'Brown-Peterson technique'.","example":"'Duration of STM about 18-30 seconds with rehearsal prevented' points to Peterson & Peterson.","look":"Sperling partial report","tell":"Peterson = SHORT-TERM memory lasting seconds; Sperling = SENSORY (iconic) memory lasting under a second.","aliases":["peterson and peterson","peterson & peterson","brown-peterson","trigrams","counting backwards"],"lookId":"sperling-partial-report"},{"id":"sperling-partial-report","name":"Sperling partial report","cat":"experiment","area":"memory","who":"George Sperling","year":"1960","def":"A grid of letters was flashed for a split second; when a tone signalled which row to report, people could report most of any row, showing almost the whole display was briefly held in a visual sensory store (iconic memory).","detail":"3 rows x 4 letters, flashed for 50 ms. Whole report: about 4-5 letters. Partial report (high, middle, low tone): about 3 of 4 per row, implying about 9 of 12 (around 75%) available. Advantage vanished if the tone was delayed about 1 second. Neisser named it iconic memory; echoic memory shown by Darwin, Turvey & Crowder (1972).","example":"'Partial report technique and iconic memory' means Sperling.","look":"Peterson & Peterson","tell":"Sperling = ICONIC memory, under 1 second; Peterson = SHORT-TERM memory, about 18 seconds.","aliases":["sperling","partial report","whole report","iconic memory experiment"],"lookId":"peterson-peterson"},{"id":"loftus-palmer","name":"Loftus & Palmer car crash study","cat":"experiment","area":"memory","who":"Elizabeth Loftus & John Palmer","year":"1974","def":"After watching films of car accidents, people asked how fast the cars were going when they 'smashed' gave higher speed estimates than those asked with 'hit' or 'contacted'. Leading questions change eyewitness memory.","detail":"Experiment 1: 45 students, 7 film clips; verbs smashed (about 41 mph), collided, bumped, hit, contacted (about 32 mph). Experiment 2: 150 students; a week later, 'smashed' group more often falsely reported broken glass (32% vs 14% for 'hit', 12% control). Misinformation effect.","example":"'Verb in a question altered speed estimates and recall of broken glass' is Loftus & Palmer.","look":"Lost in the mall","tell":"Loftus & Palmer = DISTORTING details of a real event; lost in the mall = IMPLANTING a whole event that never happened.","aliases":["loftus and palmer","loftus & palmer","car crash","smashed","broken glass","leading question"],"lookId":"lost-in-the-mall"},{"id":"lost-in-the-mall","name":"Lost in the mall study","cat":"experiment","area":"memory","who":"Elizabeth Loftus & Jacqueline Pickrell","year":"1995","def":"Participants given family-provided stories that included a false one about getting lost in a shopping mall as a child came to 'remember' the false event. Entire false memories can be implanted.","detail":"24 participants; booklets with three true childhood events and one false (lost in a mall around age 5). About 25% (6 of 24) recalled the false event fully or partly. Relevant to recovered-memory controversy and therapy suggestion.","example":"'Implanting a false childhood memory' is Loftus's lost in the mall.","look":"Loftus & Palmer car crash study","tell":"Mall = a wholly FALSE event implanted; car crash = DETAILS of a real event altered.","aliases":["lost in the mall","lost in a shopping mall","false memory implantation","loftus and pickrell"],"lookId":"loftus-palmer"},{"id":"hm","name":"H.M. (Henry Molaison)","cat":"experiment","area":"memory","who":"William Scoville & Brenda Milner","year":"1957","def":"After surgery removed much of both medial temporal lobes to control epilepsy, H.M. could no longer form new long-term memories, though his intelligence, short-term memory and old memories were largely intact.","detail":"Operation in 1953 at age 27 (bilateral hippocampus, amygdala, nearby cortex). Severe anterograde amnesia, some graded retrograde amnesia. Improved at mirror drawing across days without remembering practice: procedural (implicit) memory spared. Studied for decades by Suzanne Corkin; died 2008.","example":"'Despite his severe amnesia, he learned mirror drawing' points to H.M.","look":"Clive Wearing","tell":"H.M. = SURGERY for epilepsy, mainly anterograde; Clive Wearing = herpes ENCEPHALITIS, dense anterograde AND retrograde.","aliases":["h.m.","henry molaison","patient hm","scoville and milner","mirror drawing","patient h.m."]},{"id":"cherry-dichotic","name":"Cherry dichotic listening (shadowing)","cat":"experiment","area":"cognitive","who":"Colin Cherry","year":"1953","def":"Participants heard a different message in each ear and repeated aloud (shadowed) one of them. They noticed almost nothing about the unattended message except physical features like a switch from a male to a female voice.","detail":"Coined the 'cocktail party problem'. Missed: change of language (English to German), reversed speech, content. Noticed: voice gender change, a tone. Moray (1959): about a third of people noticed their own name in the unattended ear, challenging a strict filter.","example":"'Cherry's dichotic listening studies' and shadowing relate to selective attention, the cocktail party effect.","look":"Broadbent split-span experiment","tell":"Cherry = SHADOWING one ear (1953); Broadbent = SPLIT-SPAN digit pairs and the filter model (1954/1958).","aliases":["cherry","dichotic listening","shadowing","cocktail party","cherry's dichotic listening studies"],"lookId":"broadbent-filter"},{"id":"broadbent-filter","name":"Broadbent split-span experiment / filter model","cat":"experiment","area":"cognitive","who":"Donald Broadbent","year":"1954/1958","def":"When pairs of digits were played to the two ears at once, people preferred to recall them ear by ear rather than pair by pair. Broadbent proposed an early filter that selects one channel by physical features.","detail":"Typically 3 digits per ear (e.g. left 7 3 2, right 4 9 6). Book 'Perception and Communication' (1958): sensory buffer, then selective filter, then limited-capacity channel. Early selection model; challenged by Moray's own-name finding and Gray & Wedderburn's 'Dear Aunt Jane'.","example":"'Single-channel early filter theory of attention' is Broadbent.","look":"Treisman attenuation model","tell":"Broadbent = filter BLOCKS the unattended channel; Treisman = filter only TURNS DOWN (attenuates) it.","aliases":["broadbent","split-span","split span","filter theory","filter model","early selection"],"lookId":"treisman-attenuation"},{"id":"treisman-attenuation","name":"Treisman attenuation experiment","cat":"experiment","area":"cognitive","who":"Anne Treisman","year":"1960/1964","def":"When a story being shadowed in one ear switched to the other ear, people briefly followed the meaning across. Unattended messages are weakened, not completely blocked.","detail":"Attenuation theory (filter-attenuation): unattended input processed at reduced strength; words with low thresholds (own name, danger words, contextually expected words) break through. Related: Gray & Wedderburn (1960) 'Dear Aunt Jane'. Late selection alternative by Deutsch & Deutsch (1963).","example":"'Filter-attenuation theory of attention' is Treisman.","look":"Broadbent split-span experiment","tell":"Treisman = attenuates, MEANING can break through; Broadbent = all-or-none early filter.","aliases":["treisman","attenuation","filter-attenuation theory","attenuation theory"],"lookId":"broadbent-filter"},{"id":"split-brain","name":"Split-brain studies","cat":"experiment","area":"biological","who":"Roger Sperry & Michael Gazzaniga","year":"1960s","def":"Patients whose corpus callosum was cut to control epilepsy could not name an object shown only to the left visual field (right hemisphere), yet could pick it out with the left hand. The two hemispheres can work separately.","detail":"Left hemisphere usually handles speech; right is better at spatial and face tasks. Gazzaniga's 'interpreter' in the left hemisphere invents explanations for actions started by the right. Earlier work on split-brain cats (Myers & Sperry). Sperry won the Nobel Prize in 1981.","example":"'Split-brain studies on lateralisation of function' means Sperry and Gazzaniga.","look":"Phineas Gage","tell":"Split-brain = CUTTING the corpus callosum (lateralisation); Gage = an iron rod through the FRONTAL lobe (personality).","aliases":["split-brain","split brain","split-brain studies","corpus callosotomy","sperry","gazzaniga"],"lookId":"phineas-gage"},{"id":"phineas-gage","name":"Phineas Gage case","cat":"experiment","area":"biological","who":"Reported by Dr John Martyn Harlow","year":"1848 (reports 1848, 1868)","def":"A railway foreman survived an iron rod blasting through his frontal lobe but changed from a responsible man into an impulsive, profane one ('no longer Gage'). Early evidence linking frontal lobes to personality and self-control.","detail":"Accident in Cavendish, Vermont: a 3-foot-plus tamping iron entered under the left cheekbone and exited through the top of the skull. Harlow's 1868 report described the personality change. Gage died in 1860. Hanna Damasio and colleagues (1994) reconstructed damage to ventromedial prefrontal cortex.","example":"'Frontal lobe damage changed personality after a tamping iron accident' is Phineas Gage.","look":"Harlow's monkeys","tell":"Gage's doctor was John HARLOW (1848, frontal lobe); the monkey researcher was Harry HARLOW (1958, attachment).","aliases":["phineas gage","gage","tamping iron"],"lookId":"harlow-monkeys"},{"id":"hubel-wiesel","name":"Hubel & Wiesel feature detectors","cat":"experiment","area":"perception","who":"David Hubel & Torsten Wiesel","year":"1959","def":"Recording from single neurons in the cat's visual cortex, Hubel and Wiesel found cells that fire to lines and edges at particular orientations. Vision builds images from feature detectors.","detail":"Microelectrodes in anaesthetised cats (later monkeys). Cell types: simple, complex, hypercomplex. Later showed a critical period: covering one eye of kittens left it functionally blind (monocular deprivation, 1963). Nobel Prize 1981 (shared with Sperry).","example":"'Feature detector cells in the visual cortex' means Hubel & Wiesel.","look":"Blakemore & Cooper kittens","tell":"Hubel & Wiesel = DISCOVERED orientation-tuned cells; Blakemore & Cooper = showed EARLY EXPERIENCE shapes which orientations those cells respond to.","aliases":["hubel and wiesel","hubel & wiesel","feature detectors","simple cells","complex cells"],"lookId":"blakemore-cooper"},{"id":"blakemore-cooper","name":"Blakemore & Cooper kittens","cat":"experiment","area":"perception","who":"Colin Blakemore & Grahame Cooper","year":"1970","def":"Kittens raised seeing only vertical stripes (or only horizontal) later behaved as if blind to lines of the other orientation, and their cortical cells responded only to the orientation they had seen.","detail":"Kittens kept in darkness except for a few hours a day inside a striped cylinder, wearing a collar so they could not see their own body, from about 2 weeks to 5 months. Published in Nature (1970). Shows experience-dependent development of perception (nurture).","example":"'Kittens reared in a vertical-striped environment' is Blakemore & Cooper.","look":"Held & Hein kitten carousel","tell":"Blakemore & Cooper = WHAT the kitten sees (stripes); Held & Hein = whether the kitten MOVES itself.","aliases":["blakemore and cooper","vertical stripes","striped cylinder","blakemore & cooper"],"lookId":"held-hein"},{"id":"held-hein","name":"Held & Hein kitten carousel","cat":"experiment","area":"perception","who":"Richard Held & Alan Hein","year":"1963","def":"Two kittens got identical visual input in a carousel, but one walked actively while the other rode passively in a gondola. Only the active kitten developed normal visually guided behaviour.","detail":"Passive kitten failed tests like visual placing (extending paws when lowered toward a surface), blinking to an approaching object and avoiding the deep side of a visual cliff. Self-produced movement is needed for perceptual-motor coordination.","example":"'Active vs passive kittens in a carousel' is Held & Hein.","look":"Blakemore & Cooper kittens","tell":"Held & Hein = ACTIVE vs PASSIVE movement; Blakemore & Cooper = vertical vs horizontal STRIPES.","aliases":["held and hein","kitten carousel","gondola","held & hein"],"lookId":"blakemore-cooper"},{"id":"rosenzweig-enriched","name":"Rosenzweig enriched environment rats","cat":"experiment","area":"biological","who":"Mark Rosenzweig (with Edward Bennett & Marian Diamond)","year":"1960s-1972","def":"Rats raised in enriched cages with toys and companions developed heavier, thicker cortex and more neural connections than rats raised alone in bare cages. Experience physically changes the brain.","detail":"Conditions: enriched, standard, impoverished. Enriched rats showed greater cortical weight and thickness, more acetylcholinesterase, more dendritic branching and synapses. Summary 'Brain changes in response to experience' (Scientific American, 1972). Evidence for neural plasticity.","example":"'Enriched vs impoverished cages changed rat cortex' is Rosenzweig.","look":"Tryon's maze-bright/maze-dull breeding","tell":"Rosenzweig = ENVIRONMENT changes the brain; Tryon = GENES (breeding) change maze ability.","aliases":["rosenzweig","enriched environment","impoverished environment","enriched cages"],"lookId":"rosenthal-maze-bright"},{"id":"olds-milner","name":"Olds & Milner pleasure centre","cat":"experiment","area":"biological","who":"James Olds & Peter Milner","year":"1954","def":"Rats with electrodes in certain brain areas pressed a lever over and over to stimulate themselves electrically, sometimes ignoring food. Discovery of brain reward (pleasure) centres.","detail":"Found by accident when an electrode missed its target and landed in the septal area. Some rats pressed thousands of times per hour. Called intracranial self-stimulation; reward circuitry includes the medial forebrain bundle and dopamine pathways to the nucleus accumbens.","example":"'Rats self-stimulating the septal area' is Olds & Milner.","look":"Brenda Milner and H.M.","tell":"PETER Milner = rat pleasure centre (with Olds); BRENDA Milner = H.M.'s memory (with Scoville).","aliases":["olds and milner","olds & milner","pleasure centre","pleasure center","self-stimulation","septal area"],"lookId":"hm"},{"id":"executive-monkey","name":"Executive monkey study","cat":"experiment","area":"biological","who":"Joseph Brady","year":"1958","def":"Paired monkeys received shocks, but only the 'executive' monkey could press a lever to prevent them for both. The executives developed ulcers and died, suggesting responsibility and control cause stress.","detail":"Schedule of 6 hours on, 6 hours off. Major flaw: executives were not randomly assigned but chosen because they learned faster (possibly more emotional). Jay Weiss (1971) with rats found the opposite: animals WITHOUT control got more ulcers.","example":"'Monkeys with decision-making responsibility developed ulcers' is Brady.","look":"Seligman & Maier dogs","tell":"Brady = HAVING control caused ulcers (flawed); Seligman/Weiss = LACKING control is what harms.","aliases":["executive monkey","executive monkeys","brady","ulcers in monkeys"],"lookId":"seligman-maier"},{"id":"selye-rats","name":"Selye's rats (General Adaptation Syndrome)","cat":"experiment","area":"biological","who":"Hans Selye","year":"1936","def":"Selye found that rats exposed to many different harmful agents (injections, cold, injury, forced exercise) all showed the same bodily reaction. He called this nonspecific stress response the General Adaptation Syndrome.","detail":"Triad: enlarged adrenal cortex, shrunken thymus and lymph nodes, stomach ulcers. Stages: alarm reaction, resistance, exhaustion. First reported in Nature (1936); book 'The Stress of Life' (1956). Coined eustress and distress.","example":"'Selye's general adaptation syndrome' came from rats exposed to varied noxious agents.","look":"Executive monkey study","tell":"Selye = rats, ANY stressor gives the same 3-stage response; Brady = monkeys, CONTROL/responsibility and ulcers.","aliases":["selye","general adaptation syndrome","general adaption syndrome","gas","alarm resistance exhaustion"],"lookId":"executive-monkey"},{"id":"hawthorne-studies","name":"Hawthorne studies","cat":"experiment","area":"research","who":"Elton Mayo, Fritz Roethlisberger & William Dickson","year":"1924-1932","def":"At a Western Electric factory, workers' productivity seemed to rise with almost any change in conditions, including dimmer lighting, apparently because they knew they were being studied and receiving attention.","detail":"Hawthorne Works, near Chicago. Phases: illumination studies (1924-27), relay assembly test room (1927-32), interviewing programme, bank wiring observation room (1931-32, informal group norms restricted output). Book 'Management and the Worker' (1939). The term 'Hawthorne effect' was coined later by Henry Landsberger (1958). Launched the human relations movement.","example":"'Workers changed behaviour because they were being observed' is the Hawthorne effect from the Western Electric studies.","look":"Pygmalion in the Classroom","tell":"Hawthorne = SUBJECTS change because they are WATCHED; Pygmalion = subjects change because of OTHERS' EXPECTATIONS.","aliases":["hawthorne","hawthorne studies","western electric","hawthorne works","relay assembly","bank wiring","elton mayo"],"lookId":"pygmalion-oak-school"},{"id":"rosenhan","name":"On being sane in insane places","cat":"experiment","area":"clinical","who":"David Rosenhan","year":"1973","def":"Eight mentally healthy people got themselves admitted to psychiatric hospitals by claiming to hear voices, then acted normally; staff never detected them, and their normal behaviour was read as symptoms. Showed the power of diagnostic labels.","detail":"Published in Science. 12 hospitals in 5 US states. Voices said 'empty', 'hollow', 'thud'. All admitted; 11 diagnosed with schizophrenia, 1 with manic-depressive psychosis; discharged as 'schizophrenia in remission'. Stay 7-52 days, average 19. Fellow patients (35 of 118) suspected them; staff did not. Follow-up: a hospital told to expect impostors flagged 41 of 193 genuine patients, though none were sent.","example":"'Pseudopatients admitted to psychiatric hospitals' is Rosenhan.","look":"Hofling hospital study","tell":"Rosenhan = fake PATIENTS, diagnostic labelling; Hofling = real NURSES, obedience to a phone doctor.","aliases":["rosenhan","pseudopatient","pseudopatients","on being sane in insane places","sane in insane places"],"lookId":"hofling-hospital"},{"id":"anna-o","name":"Anna O.","cat":"experiment","area":"clinical","who":"Josef Breuer (published with Sigmund Freud)","year":"1880-1882 (published 1895)","def":"A young woman with hysterical symptoms improved when she talked under hypnosis about the events linked to each symptom. The case that launched the 'talking cure' and catharsis.","detail":"Real name Bertha Pappenheim (later a pioneering social worker). Symptoms: paralysis, disturbed vision and speech, inability to drink. She called it 'the talking cure' and 'chimney sweeping'. Published in 'Studies on Hysteria' (Breuer & Freud, 1895). Treated by Breuer, not Freud.","example":"'The talking cure' and catharsis come from Breuer's patient Anna O.","look":"Dora","tell":"Anna O. = BREUER's patient, hysteria, catharsis; Dora = FREUD's patient, hysteria, transference.","aliases":["anna o","anna o.","bertha pappenheim","talking cure","chimney sweeping"],"lookId":"dora"},{"id":"little-hans","name":"Little Hans","cat":"experiment","area":"clinical","who":"Sigmund Freud","year":"1909","def":"Freud analysed a five-year-old boy's fear of horses as a displaced Oedipal fear of his father (castration anxiety). The first child analysis, conducted mainly through the boy's father.","detail":"'Analysis of a Phobia in a Five-Year-Old Boy'. Real name Herbert Graf; father Max Graf passed on reports. Horses' blinkers and black around the mouth were linked to the father's glasses and moustache. Behaviourists (Wolpe & Rachman 1960) reinterpreted it as conditioned fear after Hans saw a horse fall.","example":"'A boy's horse phobia explained by the Oedipus complex' is Little Hans.","look":"Little Albert","tell":"Little Hans = FREUD, horse phobia, Oedipus; Little Albert = WATSON, conditioned rat fear.","aliases":["little hans","herbert graf","horse phobia"],"lookId":"stimulus-generalization"},{"id":"rat-man","name":"Rat Man","cat":"experiment","area":"clinical","who":"Sigmund Freud","year":"1909","def":"A young lawyer with obsessional neurosis was tormented by thoughts that a punishment with rats would happen to his father and the woman he loved. Freud's main case of obsessional neurosis (OCD).","detail":"'Notes upon a Case of Obsessional Neurosis'. Real name Ernst Lanzer. The torture described involved rats boring into the anus. Freud linked it to ambivalence (love and hate) toward the father and anal-stage conflicts.","example":"'Freud's case of obsessional neurosis' is the Rat Man.","look":"Wolf Man","tell":"Rat Man = OBSESSIONS (OCD); Wolf Man = infantile neurosis, a DREAM of wolves.","aliases":["rat man","ernst lanzer","obsessional neurosis case"],"lookId":"wolf-man"},{"id":"wolf-man","name":"Wolf Man","cat":"experiment","area":"clinical","who":"Sigmund Freud","year":"1918","def":"A Russian aristocrat's childhood dream of white wolves sitting in a tree was interpreted by Freud as tied to witnessing a 'primal scene'. Freud's most detailed case history.","detail":"'From the History of an Infantile Neurosis'. Real name Sergei Pankejeff. Six or seven white wolves in a walnut tree outside the window. Later treated by Ruth Mack Brunswick; was in analysis for much of his life.","example":"'Dream of wolves in a tree and the primal scene' is the Wolf Man.","look":"Rat Man","tell":"Wolf Man = a DREAM and the primal scene (1918); Rat Man = obsessional fears about RATS (1909).","aliases":["wolf man","wolfman","pankejeff","primal scene"],"lookId":"rat-man"},{"id":"dora","name":"Dora","cat":"experiment","area":"clinical","who":"Sigmund Freud","year":"1905","def":"An 18-year-old woman with hysterical symptoms (cough, loss of voice) left analysis after about 11 weeks. Freud's analysis of her two dreams, and his later admission that he missed transference, made it a landmark case.","detail":"'Fragment of an Analysis of a Case of Hysteria'. Real name Ida Bauer. Linked her symptoms to repressed feelings about Herr K. (a family friend). Treatment 1900. Used to discuss transference and criticised by feminist writers.","example":"'Freud's hysteria case that ended early because of unrecognised transference' is Dora.","look":"Anna O.","tell":"Dora = FREUD's hysteria case (1905); Anna O. = BREUER's hysteria case (1895).","aliases":["dora","ida bauer","case of hysteria"],"lookId":"anna-o"},{"id":"law-of-effect","name":"Law of effect","cat":"law","area":"learning","who":"Edward L. Thorndike","year":"1898/1911","def":"Responses followed by satisfying consequences are stamped in; responses followed by annoying consequences are stamped out.","detail":"Came from cats in puzzle boxes (1898 dissertation, formalised in Animal Intelligence 1911); learning curves fell gradually, so Thorndike called it trial-and-error (connectionism). Later he dropped the 'annoyer' half (truncated law of effect).","example":"A cat that accidentally presses the lever and escapes to food escapes faster on each later trial.","look":"Law of exercise","tell":"Effect = consequences strengthen the S-R bond; exercise = mere repetition strengthens it.","aliases":["law of effect","thorndike's law of effect","truncated law of effect"],"lookId":"law-of-exercise"},{"id":"law-of-exercise","name":"Law of exercise","cat":"law","area":"learning","who":"Edward L. Thorndike","year":"1911","def":"S-R connections strengthen with use (practice) and weaken with disuse.","detail":"Has two parts: law of use and law of disuse. Thorndike himself largely abandoned it in the early 1930s after showing practice without feedback does not improve performance (line-drawing study).","example":"Repeating a multiplication table daily keeps it fluent; skipping it for months lets it fade.","look":"Law of effect","tell":"Exercise = repetition alone; effect = repetition plus a satisfying outcome.","aliases":["law of exercise","law of use","law of disuse","law of use and disuse"],"lookId":"law-of-effect"},{"id":"law-of-readiness","name":"Law of readiness","cat":"law","area":"learning","who":"Edward L. Thorndike","year":"1913","def":"When an organism is ready (prepared) to act, acting is satisfying and being blocked is annoying; forcing action when not ready is annoying.","detail":"Stated in Educational Psychology (1913); 'readiness' refers to a conduction unit being prepared to fire, and is the basis of the educational idea of learner readiness.","example":"A child eager to read finds reading rewarding; a child forced to read before being ready finds it aversive.","look":"Law of exercise","tell":"Readiness = preparedness/motivation before acting; exercise = practice after.","aliases":["law of readiness","thorndike's law of readiness"],"lookId":"law-of-exercise"},{"id":"premack-principle","name":"Premack principle","cat":"law","area":"learning","who":"David Premack","year":"1959","def":"A more probable (preferred) activity can be used to reinforce a less probable activity.","detail":"Reinforcement is relative, not absolute: any high-frequency behaviour can reinforce any lower-frequency one. Popularly called Grandma's rule; refined by the response-deprivation hypothesis (Timberlake & Allison 1974).","example":"'Finish your homework, then you can play cricket.'","look":"Response-deprivation hypothesis","tell":"Premack = high-probability behaviour reinforces low; response deprivation = any behaviour restricted below baseline becomes reinforcing.","aliases":["premack principle","premack's principle","grandma's rule","grandmother's rule","relativity of reinforcement"]},{"id":"matching-law","name":"Matching law","cat":"law","area":"learning","who":"Richard Herrnstein","year":"1961","def":"On concurrent schedules, the proportion of responses given to an option matches the proportion of reinforcement obtained from it.","detail":"Formula: B1/(B1+B2) = R1/(R1+R2), found with pigeons on concurrent VI-VI schedules. Deviations are called undermatching and overmatching (Baum's generalised matching law, 1974).","example":"If key A gives 75% of the food, the pigeon pecks key A about 75% of the time.","look":"Matching hypothesis","tell":"Matching law = responses match reinforcement rates (operant); matching hypothesis = partners match in attractiveness (social).","aliases":["matching law","herrnstein's matching law","herrnstein matching law","generalized matching law","generalised matching law"],"lookId":"matching-hypothesis"},{"id":"rescorla-wagner-model","name":"Rescorla-Wagner model","cat":"law","area":"learning","who":"Robert Rescorla & Allan Wagner","year":"1972","def":"Classical conditioning depends on surprise: a CS gains strength only to the extent the US is not already predicted.","detail":"Formula: delta V = alpha x beta x (lambda - sum V). Prediction error drives learning; explains blocking (Kamin 1969), overshadowing and overexpectation. Fails to explain latent inhibition.","example":"After a light already predicts shock, adding a tone to the light produces little conditioning to the tone (blocking).","look":"Contiguity theory (Pavlov/Guthrie)","tell":"Rescorla-Wagner = learning needs a prediction error (contingency); contiguity = pairing in time is enough.","aliases":["rescorla-wagner","rescorla wagner","rescorla-wagner model","rescorla-wagner theory"]},{"id":"reciprocal-inhibition","name":"Principle of reciprocal inhibition","cat":"law","area":"clinical","who":"Joseph Wolpe","year":"1958","def":"Anxiety cannot occur at the same time as an incompatible response such as relaxation, so pairing the feared stimulus with relaxation weakens anxiety.","detail":"Book: Psychotherapy by Reciprocal Inhibition (1958); basis of systematic desensitization (relaxation training, anxiety hierarchy, graded imagined exposure). The term is borrowed from Sherrington's spinal-reflex physiology.","example":"A student with exam phobia relaxes deeply while imagining steps from 'syllabus released' up to 'entering the exam hall'.","look":"Counterconditioning","tell":"Reciprocal inhibition is Wolpe's mechanism; counterconditioning is the general procedure of replacing a CR with an incompatible one.","aliases":["reciprocal inhibition","wolpe's principle","joseph wolpe's principle","principle of reciprocal inhibition"]},{"id":"drive-reduction-theory","name":"Drive-reduction theory","cat":"law","area":"learning","who":"Clark L. Hull","year":"1943","def":"Biological needs create aroused drive states, and behaviour that reduces the drive is reinforced.","detail":"From Principles of Behavior (1943); hypothetico-deductive system with sEr = sHr x D (reaction potential = habit strength x drive). Homeostasis is the goal. Cannot explain curiosity or arousal-seeking.","example":"A hungry rat learns the maze path that ends in food because eating reduces the hunger drive.","look":"Arousal theory","tell":"Drive reduction = we act to lower tension; arousal theory = we seek an optimal level, sometimes raising it.","aliases":["drive-reduction theory","drive reduction theory","drive reduction","hull's drive theory","hullian drive theory"],"lookId":"arousal-theory"},{"id":"arousal-theory","name":"Optimal arousal theory","cat":"law","area":"biological","who":"Donald Hebb; Daniel Berlyne","year":"1950s","def":"People are motivated to keep arousal at an optimal, moderate level, raising it when bored and lowering it when overstimulated.","detail":"Explains curiosity, exploration and sensation seeking that drive reduction cannot. Links to the inverted-U of the Yerkes-Dodson law; Zuckerman later measured individual differences (sensation seeking).","example":"Someone bored at home goes bungee jumping to raise arousal.","look":"Drive-reduction theory","tell":"Arousal = seek the middle, even by raising stimulation; drive reduction = always lower tension.","aliases":["arousal theory","optimal arousal theory","optimum arousal theory","optimal level of arousal"],"lookId":"drive-reduction-theory"},{"id":"yerkes-dodson-law","name":"Yerkes-Dodson law","cat":"law","area":"biological","who":"Robert Yerkes & John Dodson","year":"1908","def":"Performance improves with arousal up to an optimal point, then declines; the relationship is an inverted U.","detail":"Original study used mice learning a discrimination under electric shock. Optimal arousal is lower for difficult tasks and higher for easy, well-learned tasks.","example":"Moderate exam tension sharpens performance; panic makes a hard paper go blank.","look":"Optimal arousal theory","tell":"Yerkes-Dodson = arousal vs PERFORMANCE curve; arousal theory = MOTIVATION to keep arousal optimal.","aliases":["yerkes-dodson","yerkes dodson","dodson law","yerkes-dodson law","inverted-u hypothesis","inverted u hypothesis"],"lookId":"arousal-theory"},{"id":"opponent-process-motivation","name":"Opponent-process theory of motivation","cat":"law","area":"biological","who":"Richard Solomon & John Corbit","year":"1974","def":"Every strong emotional state (a-process) automatically triggers an opposite state (b-process) that grows stronger with repetition while the first weakens.","detail":"Explains tolerance and withdrawal in addiction and the thrill after skydiving. The b-process is slow to start, slow to decay and strengthens with use.","example":"A first-time skydiver feels terror then relief; after many jumps the fear fades and the post-jump euphoria grows.","look":"Opponent-process theory of colour vision (Hering)","tell":"Solomon & Corbit = emotions and addiction; Hering = red-green/blue-yellow colour pairs.","aliases":["opponent-process theory of motivation","opponent process theory of motivation","solomon and corbit","solomon & corbit","opponent-process theory of emotion"],"lookId":"opponent-process-colour"},{"id":"ribots-law","name":"Ribot's law","cat":"law","area":"memory","who":"Theodule Ribot","year":"1881","def":"In retrograde amnesia, recent memories are lost first and older memories are spared; memory dissolves in the reverse order of acquisition.","detail":"Also called the law of regression; describes the temporal gradient of retrograde amnesia (seen in dementia and after head injury). Also stated for bilinguals: the first language returns before later ones.","example":"A patient with Alzheimer's cannot recall last week but vividly remembers school days.","look":"Jost's law","tell":"Ribot = brain damage erases recent memories first; Jost = in normal forgetting, older memories decay more slowly.","aliases":["ribot's law","ribots law","ribot law","law of regression","temporal gradient of retrograde amnesia"],"lookId":"josts-law"},{"id":"josts-law","name":"Jost's law","cat":"law","area":"memory","who":"Adolph Jost","year":"1897","def":"Of two memories of equal strength, the older one decays more slowly and benefits more from further practice.","detail":"Two parts: (1) older memories gain more from relearning; (2) older memories lose strength more slowly. Supports distributed over massed practice.","example":"A word learnt a month ago and one learnt yesterday are recalled equally well today, but tomorrow the month-old word is more likely to survive.","look":"Ribot's law","tell":"Jost = normal forgetting rate in healthy memory; Ribot = order of loss in amnesia.","aliases":["jost's law","josts law","jost law"],"lookId":"ribots-law"},{"id":"millers-magical-number","name":"Magical number seven, plus or minus two","cat":"law","area":"memory","who":"George A. Miller","year":"1956","def":"Short-term memory span holds about 7 (range 5 to 9) items or chunks.","detail":"Paper: 'The Magical Number Seven, Plus or Minus Two' (Psychological Review, 1956). Capacity is expanded by chunking. Cowan (2001) revised the estimate to about 4 chunks.","example":"A 10-digit mobile number is remembered as three chunks: 98451 23 678 style groupings.","look":"Cowan's 4 plus or minus 1","tell":"Miller = 7 plus or minus 2 (1956); Cowan = about 4 chunks (2001).","aliases":["magical number seven","magical number 7","7 plus or minus 2","seven plus or minus two","7+/-2","7 +/- 2","7±2","miller's magical number","miller's law"]},{"id":"hicks-law","name":"Hick's law (Hick-Hyman law)","cat":"law","area":"cognitive","who":"William Hick; Ray Hyman","year":"1952/1953","def":"Choice reaction time increases logarithmically with the number of equally likely alternatives.","detail":"RT = a + b log2(n), i.e. RT rises linearly with information in bits (Hick used log2(n+1)). Doubling choices adds a constant amount of time.","example":"Picking from a menu of 16 dishes takes longer than from 4, but not four times longer.","look":"Fitts' law","tell":"Hick = time to CHOOSE among alternatives; Fitts = time to MOVE to a target.","aliases":["hick's law","hicks law","hick-hyman law","hick hyman law","hick's-hyman law","rate of gain of information"],"lookId":"fitts-law"},{"id":"fitts-law","name":"Fitts' law","cat":"law","area":"cognitive","who":"Paul Fitts","year":"1954","def":"Time to move to a target increases with distance and decreases with target size.","detail":"MT = a + b log2(2D/W); the log term is the index of difficulty in bits. Central to human factors and interface design.","example":"Big buttons placed near the thumb on a phone screen are tapped faster.","look":"Hick's law","tell":"Fitts = movement time (distance and width); Hick = decision time (number of choices).","aliases":["fitts' law","fitts law","fitt's law","fitts's law","index of difficulty"],"lookId":"hicks-law"},{"id":"pollyanna-principle","name":"Pollyanna principle","cat":"law","area":"cognitive","who":"Margaret Matlin & David Stang","year":"1978","def":"People process pleasant information more accurately and efficiently than unpleasant information.","detail":"Book: The Pollyanna Principle (1978). Pleasant items are recalled better and faster; positive words are more frequent in language. Named after the optimistic girl in Eleanor Porter's 1913 novel.","example":"Remembering a holiday mostly for its good moments and forgetting the delayed train.","look":"Optimism bias","tell":"Pollyanna = selective processing/recall of the pleasant past; optimism bias = overestimating good future outcomes for oneself.","aliases":["pollyanna principle","pollyanna effect","pollyannaism"],"lookId":"optimism-bias"},{"id":"occams-razor","name":"Occam's razor (law of parsimony)","cat":"law","area":"research","who":"William of Ockham","year":"14th century","def":"Among competing explanations, prefer the simplest one that accounts for the facts; do not multiply entities beyond necessity.","detail":"Latin: entia non sunt multiplicanda praeter necessitatem. A general scientific principle; Lloyd Morgan's canon is its comparative-psychology application.","example":"Explaining a fever by one infection instead of three rare coincident diseases.","look":"Lloyd Morgan's canon","tell":"Occam = general philosophy-of-science rule; Morgan = specifically, do not credit animals with higher mental faculties than needed.","aliases":["occam's razor","ockham's razor","occams razor","ockhams razor","law of parsimony","principle of parsimony","lex parsimoniae"],"lookId":"lloyd-morgans-canon"},{"id":"lloyd-morgans-canon","name":"Lloyd Morgan's canon","cat":"law","area":"research","who":"C. Lloyd Morgan","year":"1894","def":"Never interpret an animal's behaviour as the result of a higher mental process if it can be explained by a lower one.","detail":"Stated in An Introduction to Comparative Psychology (1894) as a reaction against Romanes' anecdotal method and anthropomorphism. Morgan's dog Tony 'opening' a gate was trial-and-error, not insight.","example":"A dog that lifts a gate latch is assumed to have learnt by trial and error, not to understand latches.","look":"Occam's razor","tell":"Morgan's canon = parsimony applied to animal minds; Occam's razor = parsimony in general.","aliases":["lloyd morgan's canon","morgan's canon","morgans canon","lloyd morgan canon","canon of parsimony"],"lookId":"occams-razor"},{"id":"webers-law","name":"Weber's law","cat":"law","area":"perception","who":"Ernst Heinrich Weber","year":"1834","def":"The just noticeable difference (JND) is a constant proportion of the original stimulus intensity, not a constant amount.","detail":"delta I / I = k, the Weber fraction. Weight is about 1/50 (2%); pitch is far finer, light coarser. Breaks down at very low and very high intensities.","example":"You notice 1 g added to a 50 g letter but not 1 g added to a 5 kg parcel.","look":"Fechner's law","tell":"Weber = the JND is a constant ratio; Fechner = sensation grows as the log of intensity (built on Weber).","aliases":["weber's law","webers law","weber law","weber fraction","weber's fraction"],"lookId":"fechners-law"},{"id":"fechners-law","name":"Fechner's law","cat":"law","area":"perception","who":"Gustav Theodor Fechner","year":"1860","def":"Perceived sensation increases with the logarithm of stimulus intensity.","detail":"S = k log I, derived by summing JNDs from Weber's law; published in Elemente der Psychophysik (1860), founding psychophysics. Fechner also devised the methods of limits, constant stimuli and adjustment.","example":"Going from 1 to 2 bulbs feels like a big jump in brightness; going from 50 to 51 bulbs is barely noticed.","look":"Stevens' power law","tell":"Fechner = logarithmic (always compressive); Stevens = power function (can expand, e.g. electric shock).","aliases":["fechner's law","fechners law","fechner law","logarithmic law","weber-fechner law","weber fechner law"],"lookId":"stevens-power-law"},{"id":"stevens-power-law","name":"Stevens' power law","cat":"law","area":"perception","who":"S. S. Stevens","year":"1957","def":"Perceived magnitude equals a power function of physical intensity.","detail":"psi = k I^n, measured by magnitude estimation. Exponent below 1 compresses (brightness about 0.33), above 1 expands (electric shock about 3.5), length about 1.","example":"Doubling an electric shock feels like far more than double the pain.","look":"Fechner's law","tell":"Stevens = power function from direct magnitude estimation; Fechner = log function from summed JNDs.","aliases":["stevens' power law","stevens power law","steven's power law","stevens's power law","power law of psychophysics","magnitude estimation"],"lookId":"fechners-law"},{"id":"emmerts-law","name":"Emmert's law","cat":"law","area":"perception","who":"Emil Emmert","year":"1881","def":"The perceived size of an afterimage is proportional to the distance of the surface it is projected onto.","detail":"Retinal image size is fixed, so size constancy scaling makes the afterimage look larger on a far wall and smaller on a near page. Used to explain the moon illusion.","example":"After staring at a bulb, the afterimage looks huge on a distant wall and tiny on your palm.","look":"Size constancy","tell":"Emmert's law = afterimage size scales with projection distance; size constancy = real objects look the same size despite distance.","aliases":["emmert's law","emmerts law","emmert law"],"lookId":"perceptual-constancy"},{"id":"specific-nerve-energies","name":"Law of specific nerve energies","cat":"law","area":"biological","who":"Johannes Muller","year":"1830s","def":"The quality of a sensation depends on which nerve is stimulated, not on what stimulates it.","detail":"Stated in Muller's Handbook of Human Physiology (1830s). Pressing on the eye produces light (phosphenes) because the optic nerve can only signal 'light'. Helmholtz extended it to specific fibre energies.","example":"Rubbing your closed eyes produces flashes of light, not a sense of touch.","look":"Doctrine of specific fibre energies (Helmholtz)","tell":"Muller = each NERVE has its own quality; Helmholtz = each FIBRE within a nerve (e.g. three cone types).","aliases":["specific nerve energies","law of specific nerve energies","doctrine of specific nerve energies","muller's law","muller's doctrine","mueller's law"]},{"id":"young-helmholtz-trichromatic","name":"Young-Helmholtz trichromatic theory","cat":"law","area":"perception","who":"Thomas Young; Hermann von Helmholtz","year":"1802/1850s","def":"Colour vision results from three receptor types sensitive to short (blue), medium (green) and long (red) wavelengths.","detail":"Young proposed it in 1802; Helmholtz developed it in the 1850s. Confirmed by microspectrophotometry of cones (1960s). Explains colour mixing and most colour blindness, but not afterimages.","example":"A screen produces every colour by mixing red, green and blue pixels.","look":"Opponent-process theory (Hering)","tell":"Trichromatic = three cone types at the retina; opponent-process = paired channels (red-green, blue-yellow) beyond the cones.","aliases":["young-helmholtz","young helmholtz","trichromatic theory","trichromatic","three-colour theory","three-color theory","tri-chromatic theory"],"lookId":"opponent-process-colour"},{"id":"opponent-process-colour","name":"Opponent-process theory of colour vision","cat":"law","area":"perception","who":"Ewald Hering","year":"1878","def":"Colour is coded by three opposing pairs: red-green, blue-yellow and black-white; one member of a pair inhibits the other.","detail":"Explains negative afterimages and why reddish-green cannot be seen. Physiologically supported by Hurvich & Jameson (1957) and opponent cells in the LGN. Modern dual-process view: trichromatic at cones, opponent beyond.","example":"After staring at a red patch, a white wall shows a green afterimage.","look":"Opponent-process theory of motivation (Solomon & Corbit)","tell":"Hering = colour pairs in vision; Solomon & Corbit = emotion pairs in addiction.","aliases":["opponent-process theory of colour","opponent process theory of color","opponent-process theory of color vision","hering's theory","hering theory","opponent colors theory","opponent-colour theory"],"lookId":"opponent-process-motivation"},{"id":"place-theory","name":"Place theory of hearing","cat":"law","area":"perception","who":"Hermann von Helmholtz; Georg von Bekesy","year":"1863/1960s","def":"Pitch is coded by the location along the basilar membrane that vibrates most.","detail":"Helmholtz proposed a resonance version (1863); Bekesy showed the travelling wave (Nobel Prize 1961). High frequencies peak near the base, low near the apex. Best explains high pitches.","example":"A high-pitched whistle maximally vibrates the base of the cochlea near the oval window.","look":"Frequency theory","tell":"Place = WHERE the membrane vibrates (high pitch); frequency = HOW FAST neurons fire (low pitch).","aliases":["place theory","place theory of hearing","place theory of pitch","travelling wave theory","traveling wave theory","resonance theory"],"lookId":"frequency-theory"},{"id":"frequency-theory","name":"Frequency theory of hearing","cat":"law","area":"perception","who":"William Rutherford","year":"1886","def":"Pitch is coded by the rate at which the basilar membrane, and auditory nerve, fires, matching the sound's frequency.","detail":"Also called the telephone theory. Limited because a neuron cannot fire above about 1000 times per second (refractory period); works for low pitches.","example":"A 100 Hz hum makes auditory neurons fire about 100 times a second.","look":"Volley principle","tell":"Frequency = one neuron matches the tone; volley = groups of neurons take turns to match higher tones.","aliases":["frequency theory","frequency theory of hearing","telephone theory","rutherford's theory","temporal theory of pitch"],"lookId":"volley-principle"},{"id":"volley-principle","name":"Volley principle","cat":"law","area":"perception","who":"Ernest Glen Wever (with Charles Bray)","year":"1930/1949","def":"Groups of auditory neurons fire in alternating squads so that together they can signal frequencies above any single neuron's limit.","detail":"Extends frequency theory up to roughly 4000 to 5000 Hz. Above that, place coding takes over.","example":"Like soldiers firing in volleys so the line keeps up a faster rate of fire than one rifle.","look":"Frequency theory","tell":"Volley = staggered firing by many neurons; frequency theory = each neuron fires at the tone's rate.","aliases":["volley principle","volley theory","wever's volley","wever and bray","wever-bray"],"lookId":"frequency-theory"},{"id":"gate-control-theory","name":"Gate-control theory of pain","cat":"law","area":"biological","who":"Ronald Melzack & Patrick Wall","year":"1965","def":"A neural 'gate' in the spinal cord opens or closes to let pain signals reach the brain.","detail":"The gate is in the substantia gelatinosa of the dorsal horn. Small (C and A-delta) fibres open it; large (A-beta) touch fibres and descending signals from the brain close it. Later extended into the neuromatrix theory.","example":"Rubbing a bumped elbow reduces the pain because touch fibres close the gate.","look":"Specificity theory of pain","tell":"Gate control = pain is modulated in the spinal cord and by the brain; specificity = dedicated pain receptors send a fixed signal.","aliases":["gate control theory","gate-control theory","gate control","melzack and wall","melzack & wall","melzack-wall"]},{"id":"law-of-pragnanz","name":"Law of Pragnanz","cat":"law","area":"perception","who":"Max Wertheimer; Kurt Koffka (Gestalt school)","year":"1923","def":"We perceive stimuli in the simplest, most regular and stable form possible.","detail":"The master Gestalt principle of 'good figure' or simplicity; the other grouping laws (proximity, similarity, closure, continuity, common fate) are special cases. Wertheimer listed the laws of organisation in 1923; Koffka elaborated in 1935.","example":"The Olympic rings are seen as five overlapping circles, not a tangle of odd shapes.","look":"Law of closure","tell":"Pragnanz = overall simplest interpretation; closure = specifically filling in gaps.","aliases":["law of pragnanz","pragnanz","prägnanz","law of good figure","law of simplicity","law of good form"],"roots":"German Pragnanz = conciseness, pithiness","lookId":"gestalt-closure"},{"id":"gestalt-proximity","name":"Law of proximity","cat":"law","area":"perception","who":"Max Wertheimer (Gestalt)","year":"1923","def":"Elements close together are perceived as a group.","detail":"One of the Gestalt laws of perceptual organisation; spatial nearness overrides other cues in simple displays.","example":"Dots spaced as xx xx xx are seen as three pairs.","look":"Law of similarity","tell":"Proximity = grouped by nearness; similarity = grouped by looking alike.","aliases":["law of proximity","principle of proximity","gestalt proximity"],"lookId":"gestalt-similarity"},{"id":"gestalt-similarity","name":"Law of similarity","cat":"law","area":"perception","who":"Max Wertheimer (Gestalt)","year":"1923","def":"Elements that look alike (colour, shape, size) are perceived as belonging together.","detail":"Gestalt grouping law; in an evenly spaced grid, rows of alternating colours are seen as rows or columns depending on colour.","example":"Players in the same jersey colour are seen as one team.","look":"Law of proximity","tell":"Similarity = alike features group; proximity = nearby elements group.","aliases":["law of similarity","principle of similarity","gestalt similarity"],"lookId":"gestalt-proximity"},{"id":"gestalt-closure","name":"Law of closure","cat":"law","area":"perception","who":"Max Wertheimer (Gestalt)","year":"1923","def":"We fill in gaps to perceive incomplete figures as complete wholes.","detail":"Gestalt law; related to illusory (subjective) contours such as the Kanizsa triangle.","example":"A circle drawn with small gaps is still seen as a circle.","look":"Law of continuity","tell":"Closure = fill gaps into a whole shape; continuity = follow smooth lines.","aliases":["law of closure","principle of closure","gestalt closure"],"lookId":"gestalt-continuity"},{"id":"gestalt-continuity","name":"Law of good continuation","cat":"law","area":"perception","who":"Max Wertheimer (Gestalt)","year":"1923","def":"Elements arranged along a smooth line or curve are seen as belonging together; we prefer continuous paths over abrupt changes.","detail":"Gestalt law also called continuity; explains why crossing lines are seen as two smooth lines rather than four segments meeting at a point.","example":"Two crossing curves in an X are seen as two continuous lines.","look":"Law of closure","tell":"Continuity = follow the smoothest path; closure = complete a gap.","aliases":["law of continuity","law of good continuation","good continuation","principle of continuity","gestalt continuity"],"lookId":"gestalt-closure"},{"id":"gestalt-common-fate","name":"Law of common fate","cat":"law","area":"perception","who":"Max Wertheimer (Gestalt)","year":"1923","def":"Elements moving together in the same direction are perceived as a group.","detail":"Gestalt law based on motion; grouping by shared movement overrides static grouping cues.","example":"A flock of birds flying together is seen as one unit.","look":"Law of similarity","tell":"Common fate = grouped by shared MOTION; similarity = grouped by shared APPEARANCE.","aliases":["law of common fate","common fate","principle of common fate"],"lookId":"gestalt-similarity"},{"id":"bell-magendie-law","name":"Bell-Magendie law","cat":"law","area":"biological","who":"Charles Bell & Francois Magendie","year":"1811/1822","def":"Dorsal (posterior) spinal roots carry sensory input; ventral (anterior) roots carry motor output.","detail":"Bell (1811) described ventral roots as motor; Magendie (1822) showed dorsal roots are sensory. Mnemonic: DAVE = Dorsal Afferent, Ventral Efferent.","example":"Cutting a dorsal root abolishes feeling in a limb but leaves movement intact.","look":"Law of specific nerve energies","tell":"Bell-Magendie = direction (sensory in dorsally, motor out ventrally); Muller = quality of sensation depends on the nerve.","aliases":["bell-magendie law","bell magendie law","bell-magendie","law of roots","law of spinal roots"],"lookId":"specific-nerve-energies"},{"id":"all-or-none-law","name":"All-or-none law","cat":"law","area":"biological","who":"Henry Bowditch (heart, 1871); Edgar Adrian (nerve, 1914)","year":"1871/1914","def":"A neuron (or heart muscle) either fires at full strength or not at all; a stimulus above threshold does not produce a bigger action potential.","detail":"Bowditch showed it in cardiac muscle (1871), Keith Lucas in skeletal muscle fibres, and Adrian in nerve fibres. Intensity is coded by firing rate and number of neurons, not spike size.","example":"Pressing a light switch harder does not make the light brighter.","look":"Graded potentials","tell":"All-or-none = action potentials are fixed in size; graded potentials (postsynaptic) vary with stimulus strength.","aliases":["all-or-none law","all or none law","all-or-none principle","all or none principle","or none law","all-or-nothing law"]},{"id":"dales-principle","name":"Dale's principle","cat":"law","area":"biological","who":"Henry Dale","year":"1935","def":"A neuron releases the same neurotransmitter(s) at all of its synaptic terminals.","detail":"Suggested by Dale in 1935 and named 'Dale's principle' by John Eccles (1950s). Modern version: the same set of transmitters at every terminal, allowing for co-transmission (e.g. a peptide with a classical transmitter).","example":"A motor neuron releases acetylcholine at every muscle fibre it contacts.","look":"Hebb's rule","tell":"Dale = one neuron, one chemical identity at all terminals; Hebb = synapses strengthen when neurons fire together.","aliases":["dale's principle","dales principle","dale's law","dale principle"],"lookId":"hebbs-rule"},{"id":"hebbs-rule","name":"Hebb's rule (Hebbian learning)","cat":"law","area":"biological","who":"Donald Hebb","year":"1949","def":"When neuron A repeatedly helps fire neuron B, the connection from A to B strengthens.","detail":"From The Organization of Behavior (1949); proposed cell assemblies and phase sequences. Summarised as 'cells that fire together wire together' (a later paraphrase, Carla Shatz 1992). Physiological basis: long-term potentiation (Bliss & Lomo 1973).","example":"Practising a guitar chord strengthens the circuits that fire together to produce it.","look":"Dale's principle","tell":"Hebb = how synapses change with use (learning); Dale = what transmitter a neuron releases.","aliases":["hebb's rule","hebbs rule","hebbian learning","hebb's law","hebb's postulate","hebbian rule","fire together wire together","cell assembly","cell assemblies"],"lookId":"dales-principle"},{"id":"equipotentiality","name":"Equipotentiality principle","cat":"law","area":"biological","who":"Karl Lashley","year":"1929","def":"Any part of a cortical area can take over the function of any other part of that area.","detail":"From Brain Mechanisms and Intelligence (1929), based on rats learning mazes after cortical lesions; Lashley failed to find a localised engram ('In search of the engram', 1950). Distinct from equipotentiality in conditioning (any CS can be paired with any US), challenged by Garcia's preparedness findings.","example":"A rat with a lesion in one part of visual cortex still relearns the maze because surviving cortex takes over.","look":"Law of mass action","tell":"Equipotentiality = which part is lost does not matter; mass action = how much is lost does matter.","aliases":["equipotentiality","equipotentiality hypothesis","principle of equipotentiality","lashley's equipotentiality","equipotentiality principle"],"lookId":"mass-action"},{"id":"mass-action","name":"Law of mass action","cat":"law","area":"biological","who":"Karl Lashley","year":"1929","def":"Learning and memory depend on the total amount of cortex available; the bigger the lesion, the greater the impairment.","detail":"Partner principle to equipotentiality in Brain Mechanisms and Intelligence (1929). Deficit is proportional to lesion size, not location (for complex learning in rats).","example":"Rats losing 50% of cortex made far more maze errors than rats losing 10%, wherever the lesion was.","look":"Equipotentiality principle","tell":"Mass action = AMOUNT of cortex lost matters; equipotentiality = LOCATION does not.","aliases":["law of mass action","mass action","principle of mass action","lashley's mass action"],"lookId":"equipotentiality"},{"id":"kennard-principle","name":"Kennard principle","cat":"law","area":"developmental","who":"Margaret Kennard","year":"1930s","def":"Brain damage early in life produces less lasting impairment than the same damage in adulthood, because the young brain is more plastic.","detail":"Based on motor-cortex lesions in infant vs adult monkeys (1936 onward). Now known to be oversimplified: some very early damage (e.g. prenatal, or to certain regions) causes worse outcomes (early vulnerability).","example":"A child who loses the left hemisphere early can still develop near-normal language; an adult cannot.","look":"Critical period hypothesis","tell":"Kennard = recovery from brain DAMAGE is better when young; critical period = a time window for normal LEARNING of a skill such as language.","aliases":["kennard principle","kennard effect","kennard's principle"],"lookId":"critical-period-hypothesis"},{"id":"kindling-hypothesis","name":"Kindling hypothesis","cat":"law","area":"biological","who":"Graham Goddard (epilepsy); Robert Post (mood disorders)","year":"1967/1992","def":"Repeated sub-threshold stimulation progressively sensitises the brain so that later episodes need less trigger, eventually arising spontaneously.","detail":"Goddard found daily weak electrical stimulation of rat amygdala eventually produced full seizures. Post (1992) applied it to mood: early episodes follow stress, later episodes occur with little or no stressor; rationale for anticonvulsant mood stabilisers.","example":"A first depressive episode follows a job loss; by the fifth episode, depression returns with no clear stressor.","look":"Diathesis-stress model","tell":"Kindling = episodes themselves lower the threshold for future ones; diathesis-stress = a fixed vulnerability plus a stressor.","aliases":["kindling hypothesis","kindling","kindling model","kindling effect","stress sensitization","post's kindling"],"lookId":"diathesis-stress-model"},{"id":"dopamine-hypothesis","name":"Dopamine hypothesis of schizophrenia","cat":"law","area":"clinical","who":"Arvid Carlsson; Jacques van Rossum","year":"1960s","def":"Schizophrenia (especially positive symptoms) results from excess dopamine activity.","detail":"Evidence: antipsychotics block D2 receptors, potency correlates with D2 affinity (Seeman, Creese & Snyder 1970s); amphetamine can produce psychosis. Revised version (Davis 1991): mesolimbic excess gives positive symptoms, mesocortical deficit gives negative symptoms.","example":"Long-term amphetamine abuse can produce paranoid hallucinations resembling schizophrenia.","look":"Glutamate (NMDA) hypothesis","tell":"Dopamine = too much DA (positive symptoms); glutamate = NMDA hypofunction (PCP/ketamine produce positive and negative symptoms).","aliases":["dopamine hypothesis","dopamine hypothesis of schizophrenia","dopamine theory of schizophrenia","revised dopamine hypothesis"]},{"id":"monoamine-hypothesis","name":"Monoamine hypothesis of depression","cat":"law","area":"clinical","who":"Joseph Schildkraut (catecholamine); Alec Coppen (serotonin)","year":"1965","def":"Depression results from a deficiency of monoamines (norepinephrine, serotonin, dopamine) in the brain.","detail":"Schildkraut's catecholamine hypothesis (1965) and the serotonin version (Coppen 1967). Supported by reserpine depleting monoamines and by MAOIs and tricyclics raising them. Problem: antidepressants raise levels within hours but take 2 to 4 weeks to work.","example":"Reserpine, which depletes monoamines, was observed to induce depression in some hypertensive patients.","look":"Dopamine hypothesis","tell":"Monoamine = too LITTLE amines causes depression; dopamine hypothesis = too MUCH DA causes schizophrenia.","aliases":["monoamine hypothesis","monoamine theory","catecholamine hypothesis","serotonin hypothesis","amine hypothesis","biogenic amine hypothesis"],"lookId":"dopamine-hypothesis"},{"id":"diathesis-stress-model","name":"Diathesis-stress model","cat":"law","area":"clinical","who":"Paul Meehl; Joseph Zubin & Bonnie Spring","year":"1962/1977","def":"A disorder develops when a pre-existing vulnerability (diathesis) is triggered by environmental stress.","detail":"Meehl (1962) proposed inherited schizotaxia plus environment; Zubin & Spring (1977) formalised the vulnerability-stress model. The greater the diathesis, the less stress needed.","example":"Of two siblings with a family history of depression, the one who faces a bereavement develops depression.","look":"Biopsychosocial model (Engel)","tell":"Diathesis-stress = vulnerability x stress interaction; biopsychosocial = broad framework of three interacting levels (Engel 1977).","aliases":["diathesis-stress","diathesis stress","diathesis-stress model","stress-diathesis","vulnerability-stress model","stress-vulnerability model"],"roots":"Greek diathesis = disposition"},{"id":"general-adaptation-syndrome","name":"General adaptation syndrome","cat":"law","area":"biological","who":"Hans Selye","year":"1936/1956","def":"The body responds to any prolonged stressor in three stages: alarm, resistance and exhaustion.","detail":"First reported in Nature (1936) from rats exposed to varied noxious agents; popularised in The Stress of Life (1956). The response is non-specific (same for any stressor). Selye also coined eustress and distress.","example":"Long exam preparation: initial panic (alarm), months of coping (resistance), then illness after results (exhaustion).","look":"Fight-or-flight response (Cannon)","tell":"GAS = three-stage long-term response (Selye); fight-or-flight = immediate sympathetic emergency reaction (Cannon 1915/1929).","aliases":["general adaptation syndrome","g.a.s.","selye's gas","selye's general adaptation syndrome","alarm resistance exhaustion"]},{"id":"james-lange-theory","name":"James-Lange theory of emotion","cat":"law","area":"biological","who":"William James & Carl Lange","year":"1884/1885","def":"Emotion is the perception of bodily changes; we feel afraid because we tremble.","detail":"Sequence: stimulus, bodily arousal, then felt emotion. Criticised by Cannon (1927): viscera are too slow and insensitive, and similar arousal occurs across emotions.","example":"'We are sad because we cry, not cry because we are sad.'","look":"Cannon-Bard theory","tell":"James-Lange = arousal CAUSES emotion; Cannon-Bard = arousal and emotion occur SIMULTANEOUSLY.","aliases":["james-lange","james lange","james-lange theory","james lange theory","peripheral theory of emotion"],"lookId":"cannon-bard-theory"},{"id":"cannon-bard-theory","name":"Cannon-Bard theory of emotion","cat":"law","area":"biological","who":"Walter Cannon & Philip Bard","year":"1927","def":"An emotional stimulus triggers bodily arousal and conscious emotion at the same time, independently.","detail":"The thalamus sends signals simultaneously to the cortex (feeling) and to the body (arousal). Also called the thalamic or emergency theory; Bard's work with decorticate cats supported it.","example":"Seeing a snake, the heart races and fear is felt at the same moment.","look":"James-Lange theory","tell":"Cannon-Bard = simultaneous, thalamus-driven; James-Lange = bodily change first.","aliases":["cannon-bard","cannon bard","cannon-bard theory","thalamic theory","thalamic theory of emotion","central theory of emotion"],"lookId":"james-lange-theory"},{"id":"schachter-singer-theory","name":"Schachter-Singer two-factor theory","cat":"law","area":"social","who":"Stanley Schachter & Jerome Singer","year":"1962","def":"Emotion = physiological arousal plus a cognitive label for that arousal.","detail":"Epinephrine study: uninformed participants injected with adrenaline took on the mood of a euphoric or angry confederate. Related to misattribution of arousal (Dutton & Aron 1974 bridge study).","example":"A racing heart after coffee is felt as anxiety in a waiting room but excitement at a party.","look":"Lazarus' cognitive appraisal theory","tell":"Schachter-Singer = arousal first, then a label; Lazarus = appraisal of the event comes first and produces the emotion.","aliases":["schachter-singer","schachter singer","two-factor theory of emotion","two factor theory of emotion","singer's theory","schachter's theory","cognitive arousal theory","jukebox theory"],"lookId":"lazarus-appraisal"},{"id":"lazarus-appraisal","name":"Cognitive appraisal theory","cat":"law","area":"social","who":"Richard Lazarus","year":"1966/1984","def":"Emotion and stress depend on how a person evaluates (appraises) an event, not on the event itself.","detail":"Primary appraisal (is it relevant: harm, threat, challenge?), secondary appraisal (can I cope?), and reappraisal. Lazarus & Folkman (1984) linked it to problem-focused vs emotion-focused coping. Debated Zajonc on whether cognition must precede emotion.","example":"Two students see the same tough paper; one appraises it as a threat and panics, the other as a challenge and feels energised.","look":"Zajonc's primacy of affect","tell":"Lazarus = cognition (appraisal) always precedes emotion; Zajonc = emotion can come before and without cognition.","aliases":["cognitive appraisal","appraisal theory","lazarus appraisal","lazarus' theory","lazarus theory","primary appraisal","secondary appraisal","cognitive-mediational theory"],"lookId":"zajonc-primacy-of-affect"},{"id":"zajonc-primacy-of-affect","name":"Primacy of affect hypothesis","cat":"law","area":"social","who":"Robert Zajonc","year":"1980/1984","def":"Emotional reactions can occur before, and independently of, cognitive processing.","detail":"Paper: 'Feeling and thinking: Preferences need no inferences' (1980). Evidence from the mere exposure effect with subliminal stimuli. Supported neurally by LeDoux's thalamus-amygdala 'low road'.","example":"Feeling instantly uneasy about a stranger before you can say why.","look":"Lazarus' cognitive appraisal theory","tell":"Zajonc = affect first, no thinking needed; Lazarus = appraisal must come first.","aliases":["primacy of affect","affective primacy","zajonc's primacy","preferences need no inferences","zajonc-lazarus debate"],"lookId":"lazarus-appraisal"},{"id":"facial-feedback-hypothesis","name":"Facial feedback hypothesis","cat":"law","area":"social","who":"Silvan Tomkins; Carroll Izard; tested by Fritz Strack et al.","year":"1962/1988","def":"Facial expressions feed back to the brain and influence the emotion we feel.","detail":"Rooted in Darwin and James; developed by Tomkins (1962) and Izard (1970s). Strack, Martin & Stepper (1988) pen-in-teeth (smile) vs pen-in-lips study found cartoons rated funnier; a 2016 multi-lab replication failed, so effects are small.","example":"Holding a pen between your teeth (forcing a smile) makes cartoons seem funnier.","look":"James-Lange theory","tell":"Facial feedback = the FACE specifically shapes emotion; James-Lange = bodily/visceral arousal in general causes emotion.","aliases":["facial feedback hypothesis","facial feedback","facial-feedback","pen in mouth","pen-in-mouth","strack martin stepper"],"lookId":"james-lange-theory"},{"id":"universality-hypothesis","name":"Universality hypothesis of facial expressions","cat":"law","area":"social","who":"Paul Ekman & Wallace Friesen (after Darwin 1872)","year":"1971","def":"Basic emotions are expressed and recognised through the same facial expressions in all cultures.","detail":"Darwin proposed it in The Expression of the Emotions in Man and Animals (1872). Ekman & Friesen's study of the isolated Fore of Papua New Guinea supported six basic emotions: happiness, sadness, anger, fear, surprise, disgust. Display rules vary by culture.","example":"A villager with no media exposure correctly identifies a photo of a disgusted face.","look":"Display rules","tell":"Universality = the expressions themselves are shared; display rules = cultural norms about when to show them.","aliases":["universality hypothesis","universal hypothesis","universality of facial expressions","universal facial expressions","ekman's universality","basic emotions hypothesis"]},{"id":"frustration-aggression-hypothesis","name":"Frustration-aggression hypothesis","cat":"law","area":"social","who":"John Dollard, Leonard Doob, Neal Miller, O. H. Mowrer & Robert Sears","year":"1939","def":"Frustration (blocking of a goal) always leads to some form of aggression, and aggression is always caused by frustration.","detail":"From the Yale group's book Frustration and Aggression (1939). Miller (1941) softened it: frustration produces various responses, aggression being one. Berkowitz (1989) reformulated it: frustration causes aggression via negative affect, aided by aggressive cues (weapons effect). Explains displacement and scapegoating.","example":"Stuck in traffic and late for an exam, a driver honks and shouts at others.","look":"Displacement (Freud)","tell":"Frustration-aggression = goal blocking produces aggression; displacement = redirecting that aggression to a safer target.","aliases":["frustration-aggression","frustration aggression","frustration-aggression hypothesis","frustration aggression hypothesis","dollard","frustration-aggression theory"]},{"id":"contact-hypothesis","name":"Contact hypothesis","cat":"law","area":"social","who":"Gordon Allport","year":"1954","def":"Prejudice between groups decreases through contact, but only under the right conditions.","detail":"From The Nature of Prejudice (1954). Four conditions: equal status, common goals, intergroup cooperation, and support of authorities/law. Pettigrew & Tropp (2006) meta-analysis confirmed it. Applied in Aronson's jigsaw classroom.","example":"Mixed-caste hostel roommates working as a team on a project become less prejudiced.","look":"Superordinate goals (Sherif)","tell":"Allport = contact under four conditions; Sherif = shared goals neither group can reach alone (Robbers Cave).","aliases":["contact hypothesis","intergroup contact hypothesis","intergroup contact theory","allport's contact hypothesis","contact theory"],"lookId":"robbers-cave"},{"id":"matching-hypothesis","name":"Matching hypothesis","cat":"law","area":"social","who":"Elaine Walster (Hatfield) et al.","year":"1966","def":"People tend to choose romantic partners of roughly similar physical attractiveness to themselves.","detail":"Walster, Aronson, Abrahams & Rottman's 1966 computer-dance study actually found everyone preferred the most attractive date; later studies (Berscheid et al. 1971; Murstein 1972 couples) supported matching in actual pairings.","example":"Couples in wedding photos are usually rated as similarly attractive.","look":"Matching law (Herrnstein)","tell":"Matching hypothesis = partners match in attractiveness; matching law = responses match reinforcement rates.","aliases":["matching hypothesis","matching phenomenon","walster's matching","attractiveness matching"],"lookId":"matching-law"},{"id":"social-facilitation-drive","name":"Drive theory of social facilitation","cat":"law","area":"social","who":"Robert Zajonc","year":"1965","def":"The mere presence of others raises arousal, which strengthens the dominant (most likely) response: performance improves on easy tasks and worsens on hard ones.","detail":"Resolved conflicting findings since Triplett (1898, cyclists and fishing reels). Cottrell (1968) said arousal comes from evaluation apprehension; Sanders proposed distraction-conflict.","example":"An expert batsman plays better in a packed stadium; a beginner gets out cheaply.","look":"Social loafing (Latane)","tell":"Social facilitation = others watching your individual performance; social loafing = effort drops when pooled in a group.","aliases":["zajonc's drive theory","social facilitation","drive theory of social facilitation","mere presence","dominant response","social facilitation effect"],"lookId":"social-loafing"},{"id":"holmes-rahe-life-events","name":"Life events approach (Social Readjustment Rating Scale)","cat":"law","area":"clinical","who":"Thomas Holmes & Richard Rahe","year":"1967","def":"Major life changes, whether good or bad, demand readjustment and raise the risk of illness.","detail":"The SRRS lists 43 life events weighted in life change units (LCU): death of spouse 100, divorce 73, marriage 50. Over 300 LCU in a year is linked to high illness risk. Lazarus later argued daily hassles predict health better.","example":"A year with marriage, a job change and moving city adds up to a high LCU score.","look":"Daily hassles (Lazarus)","tell":"Holmes & Rahe = big life events; Lazarus = small daily hassles and uplifts.","aliases":["holmes and rahe","holmes & rahe","holmes-rahe","srrs","social readjustment rating scale","life change units","life events theory","life events scale"]},{"id":"sapir-whorf-hypothesis","name":"Sapir-Whorf hypothesis (linguistic relativity)","cat":"law","area":"cognitive","who":"Edward Sapir & Benjamin Lee Whorf","year":"1940s","def":"The language we speak shapes how we think and perceive the world.","detail":"Strong form (linguistic determinism): language determines thought. Weak form (linguistic relativity): language influences thought. Classic example: Hopi time, 'Eskimo snow words' (exaggerated). Berlin & Kay's (1969) and Heider/Rosch's Dani colour studies challenged the strong form.","example":"Speakers of languages with separate words for light and dark blue (Russian) distinguish those shades slightly faster.","look":"Piaget's view (thought precedes language)","tell":"Whorf = language shapes thought; Piaget = thought develops first and language maps onto it.","aliases":["sapir-whorf","sapir whorf","whorfian hypothesis","linguistic relativity","linguistic relativity hypothesis","linguistic determinism","whorf hypothesis"]},{"id":"critical-period-hypothesis","name":"Critical period hypothesis (language)","cat":"law","area":"developmental","who":"Eric Lenneberg","year":"1967","def":"Language is acquired most easily during a biologically fixed window, roughly from age 2 to puberty, after which full native-like acquisition is very hard.","detail":"From Biological Foundations of Language (1967); linked to lateralisation completing at puberty. Case of Genie (found at 13) supports it. Concept parallels imprinting (Lorenz) in animals; 'sensitive period' is the softer version.","example":"Genie, isolated until 13, learnt words but never mastered grammar.","look":"Kennard principle","tell":"Critical period = window for normal learning; Kennard = better recovery from early brain damage.","aliases":["critical period hypothesis","critical period","lenneberg","sensitive period hypothesis","critical period for language"],"lookId":"kennard-principle"},{"id":"pleasure-principle","name":"Pleasure principle","cat":"law","area":"personality","who":"Sigmund Freud","year":"1911","def":"The id seeks immediate gratification of impulses and avoidance of pain, regardless of reality.","detail":"Freud's 'Formulations on the Two Principles of Mental Functioning' (1911). Operates through primary process thinking (wish-fulfilling images, dreams). Revisited in Beyond the Pleasure Principle (1920).","example":"A hungry infant screams until fed, with no capacity to wait.","look":"Reality principle","tell":"Pleasure principle = id, gratify NOW; reality principle = ego, delay until realistic.","aliases":["pleasure principle","pleasure-principle","lustprinzip"],"lookId":"reality-principle"},{"id":"reality-principle","name":"Reality principle","cat":"law","area":"personality","who":"Sigmund Freud","year":"1911","def":"The ego delays gratification until a realistic, socially acceptable way of satisfying the need is found.","detail":"Operates through secondary process thinking (logical, reality-tested problem solving). Paired with the pleasure principle in Freud's 1911 'two principles' paper.","example":"A hungry student waits until the lecture ends to eat rather than eating in class.","look":"Pleasure principle","tell":"Reality = ego, delay and plan; pleasure = id, immediate satisfaction.","aliases":["reality principle","reality-principle","realitatsprinzip"],"lookId":"pleasure-principle"},{"id":"prosopagnosia","name":"Prosopagnosia","cat":"term","area":"perception","who":"Joachim Bodamer (named it)","year":"1947","roots":"prosopon (Greek, face) + a- (not) + gnosis (knowing) = not knowing faces","def":"Inability to recognise familiar faces despite intact vision and intact recognition of other objects.","detail":"Lesion in the fusiform gyrus (fusiform face area) of the occipitotemporal cortex, usually bilateral or right-sided. Patients identify people by voice, gait or clothes.","example":"A man fails to recognise his own wife until she speaks: which agnosia?","look":"Capgras syndrome","tell":"Prosopagnosia: cannot recognise the face at all. Capgras: recognises the face but insists the person is an impostor.","aliases":["prosopagnosia","face blindness","face agnosia"],"lookId":"capgras-syndrome"},{"id":"visual-agnosia","name":"Visual agnosia","cat":"term","area":"perception","who":"Sigmund Freud (coined 'agnosia'); Heinrich Lissauer split it into apperceptive and associative (1890)","year":"1891","roots":"a- (not) + gnosis (Greek, knowing) = not knowing (what is seen)","def":"Failure to recognise objects by sight even though basic vision, language and intellect are intact.","detail":"Object can still be recognised by touch or sound, which rules out a naming (aphasic) problem. Lesion in the ventral 'what' stream (occipitotemporal).","example":"Patient cannot name a key on sight but names it at once when it is placed in the hand.","look":"Optic aphasia","tell":"Visual agnosia: object not recognised (cannot mime its use). Optic aphasia: object recognised (can mime its use) but cannot be named from sight.","aliases":["visual agnosia","object agnosia","visual object agnosia","psychic blindness","mindblindness"]},{"id":"apperceptive-agnosia","name":"Apperceptive agnosia","cat":"term","area":"perception","who":"Heinrich Lissauer","year":"1890","roots":"ad- (Latin, towards) + percipere (to perceive) = failure at the perceiving stage","def":"Visual agnosia in which the percept itself is never properly formed, so the person cannot copy or match shapes.","detail":"Early stage of perception fails; typically diffuse posterior damage such as carbon monoxide poisoning (patient DF, Milner and Goodale).","example":"Cannot copy a simple drawing of a house or match two identical shapes.","look":"Associative agnosia","tell":"Apperceptive: cannot COPY the drawing. Associative: copies it perfectly but still cannot say what it is.","aliases":["apperceptive agnosia","apperceptive visual agnosia"],"lookId":"associative-agnosia"},{"id":"associative-agnosia","name":"Associative agnosia","cat":"term","area":"perception","who":"Heinrich Lissauer","year":"1890","roots":"associare (Latin, to join) = failure to join the percept to its meaning","def":"Visual agnosia in which perception is intact but the percept cannot be linked to stored knowledge, so the object is not recognised.","detail":"Lissauer's 'perception stripped of its meaning' (Teuber). Usually bilateral occipitotemporal lesions.","example":"Draws an accurate copy of an anchor, then says 'I don't know what this is'.","look":"Apperceptive agnosia","tell":"Associative: good copy, no meaning. Apperceptive: cannot even copy.","aliases":["associative agnosia","associative visual agnosia"],"lookId":"apperceptive-agnosia"},{"id":"astereognosis","name":"Astereognosis","cat":"term","area":"perception","who":"","year":"","roots":"a- (not) + stereos (Greek, solid) + gnosis (knowing) = not knowing solid objects","def":"Inability to recognise an object by touch alone (eyes closed) despite intact basic sensation.","detail":"Tactile agnosia; lesion in the contralateral parietal cortex (somatosensory association area).","example":"With eyes closed, a coin in the right hand cannot be identified: which lobe?","look":"Agraphaesthesia","tell":"Astereognosis: cannot identify an OBJECT by touch. Agraphaesthesia: cannot identify a NUMBER traced on the skin.","aliases":["astereognosis","astereognosia","tactile agnosia"]},{"id":"anosognosia","name":"Anosognosia","cat":"term","area":"perception","who":"Joseph Babinski (named it)","year":"1914","roots":"a- (not) + nosos (Greek, disease) + gnosis (knowing) = not knowing one's disease","def":"Lack of awareness of, or denial of, one's own neurological deficit.","detail":"Classically denial of left hemiplegia after right parietal stroke; often with left neglect. Also seen in Anton syndrome and Wernicke aphasia.","example":"A patient with a paralysed left arm insists he can clap: term?","look":"Anosodiaphoria","tell":"Anosognosia: denies the deficit. Anosodiaphoria: admits it but does not care.","aliases":["anosognosia","denial of illness","unawareness of deficit"]},{"id":"simultanagnosia","name":"Simultanagnosia","cat":"term","area":"perception","who":"Wolpert (named it)","year":"1924","roots":"simul (Latin, at the same time) + a- (not) + gnosis (knowing) = cannot know things together","def":"Inability to perceive more than one object, or the whole of a scene, at a time.","detail":"Dorsal form from bilateral parieto-occipital lesions; one of the three components of Balint syndrome.","example":"Shown the 'Cookie Theft' picture, the patient describes only one item, never the whole scene.","look":"Balint syndrome","tell":"Simultanagnosia is one symptom; Balint is the triad (simultanagnosia + optic ataxia + oculomotor apraxia).","aliases":["simultanagnosia","simultagnosia","simultaneous agnosia"],"lookId":"balint-syndrome"},{"id":"alexia","name":"Alexia","cat":"term","area":"cognitive","who":"Joseph Jules Dejerine (alexia without agraphia)","year":"1892","roots":"a- (not) + lexis (Greek, word; linked to Latin legere, to read) = without reading","def":"Acquired loss of the ability to read in someone who previously could.","detail":"Pure alexia (alexia without agraphia): left occipital lesion plus splenium of corpus callosum; patient writes but cannot read what he wrote. Alexia with agraphia: left angular gyrus (Dejerine 1891).","example":"After a left PCA stroke a man can write a letter but cannot read it back.","look":"Dyslexia","tell":"Alexia is ACQUIRED (brain damage after literacy); dyslexia is DEVELOPMENTAL.","aliases":["alexia","pure alexia","alexia without agraphia","word blindness","acquired dyslexia"],"lookId":"dyslexia"},{"id":"agraphia","name":"Agraphia","cat":"term","area":"cognitive","who":"","year":"","roots":"a- (not) + graphein (Greek, to write) = without writing","def":"Acquired loss of the ability to write, not due to weakness or incoordination of the hand.","detail":"Often with aphasia; left angular gyrus lesions give alexia with agraphia; also a component of Gerstmann syndrome.","example":"One of the four features of Gerstmann syndrome.","look":"Dysgraphia","tell":"Agraphia: acquired loss after brain damage. Dysgraphia: developmental difficulty learning to write.","aliases":["agraphia","acquired agraphia"]},{"id":"acalculia","name":"Acalculia","cat":"term","area":"cognitive","who":"Salomon Henschen (coined)","year":"1919","roots":"a- (not) + calculus (Latin, pebble used for counting) = without calculating","def":"Acquired inability to perform simple arithmetic.","detail":"Classic lesion: left (dominant) angular gyrus / parietal lobe; part of Gerstmann syndrome.","example":"After a left parietal stroke a shopkeeper can no longer add up a bill.","look":"Dyscalculia","tell":"Acalculia: acquired. Dyscalculia: developmental learning disorder.","aliases":["acalculia","acquired acalculia"],"lookId":"dyscalculia"},{"id":"ideomotor-apraxia","name":"Ideomotor apraxia","cat":"term","area":"cognitive","who":"Hugo Liepmann","year":"1900","roots":"idea + motor + a- (not) + praxis (Greek, action) = idea intact, movement fails","def":"Inability to carry out a skilled movement on command or by imitation, although the idea is known and the act may occur spontaneously.","detail":"Most common apraxia; left inferior parietal (supramarginal) lesions or their connections. Tested by pantomime ('show me how you brush your teeth').","example":"Cannot pretend to wave goodbye when asked, yet waves spontaneously when leaving.","look":"Ideational apraxia","tell":"Ideomotor: knows WHAT to do, cannot do it on command. Ideational: has lost the IDEA or sequence of the act.","aliases":["ideomotor apraxia","ideo-motor apraxia","limb apraxia"],"lookId":"ideational-apraxia"},{"id":"ideational-apraxia","name":"Ideational apraxia","cat":"term","area":"cognitive","who":"Hugo Liepmann","year":"1900","roots":"idea + a- (not) + praxis (Greek, action) = loss of the idea of the action","def":"Inability to plan or sequence a multi-step action or to use objects correctly, due to loss of the concept of the act.","detail":"Associated with left parietal or diffuse damage (dementia). The patient may do each step but in the wrong order.","example":"Asked to make tea, puts the cup on the stove and pours milk into the kettle.","look":"Ideomotor apraxia","tell":"Ideational = the plan is lost (wrong order/wrong use). Ideomotor = the plan is fine but execution on command fails.","aliases":["ideational apraxia","conceptual apraxia"],"lookId":"ideomotor-apraxia"},{"id":"constructional-apraxia","name":"Constructional apraxia","cat":"term","area":"cognitive","who":"Karl Kleist (named it)","year":"","roots":"construere (Latin, to build) + a- (not) + praxis (action) = cannot build","def":"Inability to draw, copy or assemble parts into a whole (e.g., copying a cube or arranging blocks).","detail":"Parietal lesions of either side; more severe with right parietal damage (spatial errors), left gives simplified drawings. Tested by clock drawing, Bender Gestalt, WAIS block design.","example":"A patient's clock drawing has all the numbers crowded on one side.","look":"Dressing apraxia","tell":"Constructional: cannot assemble or copy shapes. Dressing: cannot orient clothes to the body (right parietal).","aliases":["constructional apraxia","constructive apraxia"]},{"id":"brocas-aphasia","name":"Broca's aphasia","cat":"term","area":"cognitive","who":"Paul Broca","year":"1861","roots":"a- (not) + phasis (Greek, speech) = without speech","def":"Non-fluent, effortful, telegraphic speech with relatively preserved comprehension; also called expressive or motor aphasia.","detail":"Lesion in the left inferior frontal gyrus (Brodmann 44, 45). Agrammatism, poor repetition, patient is aware and frustrated; often right hemiparesis. Broca's patient Leborgne said only 'tan'.","example":"'Walk... dog... park.' Understands questions, struggles to answer.","look":"Wernicke's aphasia","tell":"Broca: broken speech, good understanding. Wernicke: fluent nonsense, poor understanding.","aliases":["broca's aphasia","brocas aphasia","broca aphasia","expressive aphasia","motor aphasia","non-fluent aphasia","nonfluent aphasia"],"lookId":"wernickes-aphasia"},{"id":"wernickes-aphasia","name":"Wernicke's aphasia","cat":"term","area":"cognitive","who":"Carl Wernicke","year":"1874","roots":"a- (not) + phasis (Greek, speech) = without (meaningful) speech","def":"Fluent but meaningless speech with poor comprehension; also called receptive or sensory aphasia.","detail":"Lesion in the posterior left superior temporal gyrus (Brodmann 22). Paraphasias, neologisms ('jargon aphasia'), poor repetition, patient often unaware of errors.","example":"Speaks rapidly with normal rhythm, but says 'the flimber went to the dorket'.","look":"Broca's aphasia","tell":"Wernicke: words flow, sense does not; Broca: sense is there, words do not flow.","aliases":["wernicke's aphasia","wernickes aphasia","wernicke aphasia","receptive aphasia","sensory aphasia","fluent aphasia","jargon aphasia"],"lookId":"brocas-aphasia"},{"id":"conduction-aphasia","name":"Conduction aphasia","cat":"term","area":"cognitive","who":"Carl Wernicke (predicted it)","year":"1874","roots":"conducere (Latin, to lead together) + aphasia = speech failure from a broken connection","def":"Fluent aphasia with good comprehension but disproportionately poor repetition.","detail":"Lesion of the arcuate fasciculus / supramarginal gyrus, disconnecting Wernicke's from Broca's area. Phonemic paraphasias with repeated self-correction attempts (conduite d'approche).","example":"Understands and speaks fairly well but cannot repeat 'no ifs, ands or buts'.","look":"Transcortical sensory aphasia","tell":"Conduction: repetition is the ONE thing lost. Transcortical: repetition is the ONE thing kept.","aliases":["conduction aphasia","associative aphasia"],"lookId":"transcortical-sensory-aphasia"},{"id":"global-aphasia","name":"Global aphasia","cat":"term","area":"cognitive","who":"","year":"","roots":"globus (Latin, sphere, whole) + aphasia = total loss of language","def":"Severe loss of all language functions: expression, comprehension, repetition, reading and writing.","detail":"Large left perisylvian lesion covering Broca's and Wernicke's areas, usually a left middle cerebral artery stroke.","example":"Stroke patient neither speaks nor understands, may utter only a stereotyped syllable.","look":"Mixed transcortical aphasia","tell":"Global: repetition also lost. Mixed transcortical (isolation of speech area): everything lost EXCEPT repetition.","aliases":["global aphasia","total aphasia"],"lookId":"transcortical-motor-aphasia"},{"id":"transcortical-motor-aphasia","name":"Transcortical motor aphasia","cat":"term","area":"cognitive","who":"Ludwig Lichtheim (Wernicke-Lichtheim model)","year":"1885","roots":"trans (across) + cortex + motor + aphasia = motor aphasia from damage beyond the core speech area","def":"Non-fluent speech with good comprehension and strikingly preserved repetition.","detail":"Lesion anterior or superior to Broca's area (ACA-MCA watershed, supplementary motor area), sparing the perisylvian loop.","example":"Barely speaks spontaneously but repeats long sentences perfectly.","look":"Broca's aphasia","tell":"Both are non-fluent; Broca cannot repeat, transcortical motor CAN.","aliases":["transcortical motor aphasia"],"lookId":"brocas-aphasia"},{"id":"transcortical-sensory-aphasia","name":"Transcortical sensory aphasia","cat":"term","area":"cognitive","who":"Ludwig Lichtheim (Wernicke-Lichtheim model)","year":"1885","roots":"trans (across) + cortex + sensory + aphasia = sensory aphasia from damage beyond the core speech area","def":"Fluent speech with poor comprehension but preserved repetition, often echolalic.","detail":"Posterior watershed lesion (temporo-parieto-occipital junction) sparing Wernicke's area itself. Seen in Alzheimer's disease.","example":"Repeats the examiner's question word for word without understanding it.","look":"Wernicke's aphasia","tell":"Both fluent with poor comprehension; Wernicke cannot repeat, transcortical sensory CAN (often echoes).","aliases":["transcortical sensory aphasia"],"lookId":"wernickes-aphasia"},{"id":"anomic-aphasia","name":"Anomic aphasia","cat":"term","area":"cognitive","who":"","year":"","roots":"a- (not) + onoma (Greek, name) + aphasia = aphasia of names","def":"Fluent aphasia whose main deficit is word-finding, with good comprehension and repetition.","detail":"Least localising aphasia (angular gyrus, temporal lobe, or any recovering aphasia). Circumlocution: 'the thing you write with'.","example":"Speech is fluent but full of 'thing' and 'you know, that one'.","look":"Anomia","tell":"Anomia is a symptom found in every aphasia; anomic aphasia is the syndrome where it is the only major deficit.","aliases":["anomic aphasia","nominal aphasia","amnestic aphasia","amnesic aphasia"],"lookId":"anomia"},{"id":"dysarthria","name":"Dysarthria","cat":"term","area":"biological","who":"","year":"","roots":"dys- (Greek, bad) + arthroun (to articulate) = faulty articulation","def":"Motor speech disorder causing slurred or poorly articulated speech; language itself is intact.","detail":"Due to weakness or incoordination of speech muscles (cerebellar 'scanning' speech, bulbar palsy, Parkinson's). Reading, writing and comprehension are normal.","example":"A cerebellar patient speaks in slurred, irregular syllables but writes a perfect sentence.","look":"Aphasia","tell":"Dysarthria: the mouth fails (articulation). Aphasia: the language system fails (words, grammar, meaning).","aliases":["dysarthria","anarthria","slurred speech"],"lookId":"brocas-aphasia"},{"id":"anomia","name":"Anomia","cat":"term","area":"cognitive","who":"","year":"","roots":"a- (not) + onoma (Greek, name) = without names","def":"Difficulty finding or naming words, especially nouns.","detail":"Present in nearly all aphasias and in Alzheimer's disease; tested with the Boston Naming Test.","example":"Shown a watch, says 'it tells you the time' but cannot say 'watch'.","look":"Anomic aphasia","tell":"Anomia = the symptom. Anomic aphasia = a whole aphasia type defined by it.","aliases":["anomia","dysnomia","word-finding difficulty","word finding difficulty"],"lookId":"anomic-aphasia"},{"id":"echolalia","name":"Echolalia","cat":"term","area":"clinical","who":"","year":"","roots":"echo (Greek, repeated sound) + lalia (talk) = echoed talk","def":"Automatic, meaningless repetition of words or phrases spoken by another person.","detail":"Seen in catatonia, autism, transcortical aphasias, Tourette's, latah, dementia.","example":"Asked 'What is your name?', the patient replies 'What is your name?'","look":"Palilalia","tell":"Echolalia echoes OTHERS' words; palilalia repeats one's OWN words.","aliases":["echolalia","echophrasia"],"lookId":"palilalia"},{"id":"palilalia","name":"Palilalia","cat":"term","area":"clinical","who":"Alexandre-Achille Souques (named it)","year":"1908","roots":"palin (Greek, again) + lalia (talk) = talking again","def":"Involuntary repetition of one's own words or phrases, often with increasing speed and decreasing volume.","detail":"Seen in Parkinson's disease, post-encephalitic states, Tourette's, Pick's disease. Fish separates it from logoclonia (repeating the last syllable).","example":"'I want to go home, home, home, home...'","look":"Echolalia","tell":"Palilalia = own words repeated; echolalia = examiner's words repeated.","aliases":["palilalia","palilogia"],"lookId":"echolalia"},{"id":"neologism","name":"Neologism","cat":"term","area":"clinical","who":"","year":"","roots":"neos (Greek, new) + logos (word) = new word","def":"A new word invented by the patient, whose meaning is not readily understood by others.","detail":"Typical of schizophrenia and Wernicke's (jargon) aphasia. Fish distinguishes it from word approximation (metonym), where ordinary words are used in an unusual way.","example":"Patient calls a pen a 'glimbo'.","look":"Metonym (word approximation)","tell":"Neologism invents a new word; metonym misuses an existing one ('hand shoes' for gloves).","aliases":["neologism","neologisms"]},{"id":"word-salad","name":"Word salad","cat":"term","area":"clinical","who":"","year":"","roots":"English metaphor: words tossed together like a salad","def":"Incoherent jumble of words and phrases with no logical or grammatical connection.","detail":"Most severe form of formal thought disorder in schizophrenia (also called schizophasia, verbigeration-like incoherence); breakdown occurs WITHIN the sentence.","example":"'Sky pencil mother running blue the ate'.","look":"Derailment","tell":"Derailment: each sentence makes sense but ideas slip between sentences. Word salad: even single sentences are scrambled.","aliases":["word salad","schizophasia","incoherence"],"lookId":"derailment"},{"id":"perseveration","name":"Perseveration","cat":"term","area":"cognitive","who":"","year":"","roots":"per (Latin, through) + severare (to persist) = persisting beyond the point","def":"Inappropriate repetition of a previous response (word, idea or act) after the stimulus has changed.","detail":"Hallmark of frontal lobe damage (dorsolateral prefrontal cortex); seen as perseverative errors on the Wisconsin Card Sorting Test. Also in dementia and schizophrenia.","example":"Asked 'What day is it?' then 'Where are you?', answers 'Monday' to both.","look":"Stereotypy","tell":"Perseveration repeats the LAST response to a NEW question; stereotypy repeats an act regardless of any question.","aliases":["perseveration","perseverative errors"]},{"id":"confabulation","name":"Confabulation","cat":"term","area":"memory","who":"","year":"","roots":"con (Latin, together) + fabula (story) = making up a story","def":"Unintentional filling of memory gaps with false or distorted recollections, which the patient believes.","detail":"Classic in Korsakoff syndrome, also Anton syndrome and frontal lesions; 'honest lying' because there is no intent to deceive.","example":"A Korsakoff patient who has been in hospital all week describes yesterday's trip to the market.","look":"Pseudologia fantastica","tell":"Confabulation: no intent, fills memory gaps. Pseudologia fantastica: elaborate pathological lying, usually for admiration or gain.","aliases":["confabulation","confabulating","honest lying"]},{"id":"anterograde-amnesia","name":"Anterograde amnesia","cat":"term","area":"memory","who":"","year":"","roots":"ante (Latin, before/forward) + gradi (to step) + a- (not) + mnesis (Greek, memory) = no memory going forward","def":"Inability to form new long-term memories after the onset of the injury or illness.","detail":"Medial temporal lobe (hippocampus) or diencephalic damage. Patient H.M. (Scoville and Milner 1957) after bilateral medial temporal lobectomy; procedural learning (mirror drawing) spared.","example":"H.M. could not remember the doctor he had met five minutes earlier.","look":"Retrograde amnesia","tell":"ANTEROgrade = can't make new memories (forward). RETROgrade = lost old memories (backward).","aliases":["anterograde amnesia","antegrade amnesia","pure anterograde amnesia","dense anterograde amnesia","severe anterograde amnesia"],"lookId":"retrograde-amnesia"},{"id":"retrograde-amnesia","name":"Retrograde amnesia","cat":"term","area":"memory","who":"","year":"","roots":"retro (Latin, backward) + gradi (to step) + a- (not) + mnesis (memory) = memory loss going backward","def":"Loss of memory for events that occurred before the onset of the injury or illness.","detail":"Follows Ribot's law (temporal gradient): recent memories are lost first, remote ones best preserved. Common after head injury and ECT.","example":"After a car crash, a man cannot recall the week before the accident.","look":"Anterograde amnesia","tell":"Retrograde = past erased; anterograde = future not recorded.","aliases":["retrograde amnesia","global retrograde amnesia","profound retrograde amnesia"],"lookId":"anterograde-amnesia"},{"id":"dissociative-amnesia","name":"Dissociative amnesia","cat":"term","area":"clinical","who":"","year":"","roots":"dis (apart) + sociare (Latin, to join) + amnesia = memory split off from awareness","def":"Inability to recall important autobiographical information, usually traumatic or stressful, not explained by ordinary forgetting or organic disease.","detail":"Localised, selective or generalised; procedural and general knowledge preserved. DSM-5 places dissociative fugue as a specifier of it.","example":"After witnessing her house burn, a woman cannot recall that entire day but knows who she is.","look":"Dissociative fugue","tell":"Amnesia: forgets but stays put. Fugue: forgets AND travels away, sometimes with a new identity.","aliases":["dissociative amnesia","psychogenic amnesia","functional amnesia","hysterical amnesia"],"lookId":"dissociative-fugue"},{"id":"transient-global-amnesia","name":"Transient global amnesia","cat":"term","area":"memory","who":"C. Miller Fisher and Raymond Adams","year":"1964","roots":"transire (Latin, to pass) + globus (whole) + amnesia = passing total amnesia","def":"Sudden, temporary (under 24 hours) anterograde amnesia with repetitive questioning, personal identity preserved.","detail":"Middle-aged or older adults, often after exertion, cold water or emotion; hippocampal (CA1) dysfunction; resolves fully, with a permanent gap for the episode.","example":"A 60-year-old repeatedly asks 'What are we doing here?' for six hours, then recovers.","look":"Dissociative amnesia","tell":"TGA: loses NEW learning, keeps identity, organic, under 24 h. Dissociative: loses PERSONAL past, often identity, psychogenic.","aliases":["transient global amnesia","tga"],"lookId":"dissociative-amnesia"},{"id":"korsakoff-syndrome","name":"Korsakoff syndrome","cat":"term","area":"memory","who":"Sergei Korsakoff","year":"1887","roots":"Eponym: Sergei Sergeievich Korsakoff, Russian psychiatrist","def":"Chronic amnestic syndrome with severe anterograde (and retrograde) amnesia and confabulation, due to thiamine (vitamin B1) deficiency.","detail":"Usually chronic alcoholism; damage to mammillary bodies and dorsomedial thalamus. Immediate recall (digit span) and intellect relatively preserved.","example":"A chronic drinker cannot remember new staff names and invents stories to fill the gaps.","look":"Wernicke encephalopathy","tell":"Wernicke = ACUTE triad (confusion, ophthalmoplegia, ataxia), reversible with thiamine. Korsakoff = CHRONIC amnesia + confabulation.","aliases":["korsakoff syndrome","korsakoff's syndrome","korsakoffs syndrome","korsakoff psychosis","korsakoff's psychosis","amnestic syndrome","alcohol-induced amnesia"],"lookId":"wernicke-korsakoff-syndrome"},{"id":"wernicke-korsakoff-syndrome","name":"Wernicke-Korsakoff syndrome","cat":"term","area":"biological","who":"Carl Wernicke (encephalopathy, 1881); Sergei Korsakoff (psychosis, 1887)","year":"1881","roots":"Eponyms: Wernicke (acute encephalopathy) + Korsakoff (chronic amnesia)","def":"Thiamine-deficiency continuum: acute Wernicke encephalopathy that, if untreated, leaves chronic Korsakoff amnesia.","detail":"Wernicke triad: global confusion, ophthalmoplegia (nystagmus, lateral rectus palsy) and ataxia. Treat with parenteral thiamine BEFORE glucose. Lesions around the third ventricle, mammillary bodies.","example":"Confused alcoholic with nystagmus and a wide-based gait: what to give first?","look":"Korsakoff syndrome","tell":"Wernicke-Korsakoff names the whole continuum; Korsakoff alone is just the chronic amnestic end-state.","aliases":["wernicke-korsakoff syndrome","wernicke korsakoff syndrome","wernicke encephalopathy","wernicke's encephalopathy","wernickes encephalopathy"],"lookId":"korsakoff-syndrome"},{"id":"kluver-bucy-syndrome","name":"Kluver-Bucy syndrome","cat":"term","area":"biological","who":"Heinrich Kluver and Paul Bucy","year":"1937","roots":"Eponym: Heinrich Kluver (psychologist) + Paul Bucy (neurosurgeon)","def":"Syndrome after bilateral anterior temporal lobe (amygdala) damage: placidity, hyperorality, hypersexuality, visual agnosia and hypermetamorphosis.","detail":"First produced in rhesus monkeys by bilateral temporal lobectomy. Loss of fear is from the amygdala. Human causes: herpes simplex encephalitis, frontotemporal dementia.","example":"Monkeys put everything in their mouths, lose fear of snakes and attempt sex with inappropriate objects.","look":"Frontal lobe syndrome","tell":"Kluver-Bucy: TEMPORAL (amygdala), hyperorality + loss of fear. Frontal syndrome: disinhibition, apathy, poor planning.","aliases":["kluver-bucy syndrome","kluver bucy syndrome","kluver-bucy","kluver bucy","klüver-bucy syndrome"],"lookId":"frontal-lobe-syndrome"},{"id":"gerstmann-syndrome","name":"Gerstmann syndrome","cat":"term","area":"cognitive","who":"Josef Gerstmann","year":"1924","roots":"Eponym: Josef Gerstmann, Austrian neurologist","def":"Tetrad of finger agnosia, right-left disorientation, agraphia and acalculia.","detail":"Lesion of the dominant (left) angular gyrus, inferior parietal lobule.","example":"Patient cannot name his fingers, confuses left and right, cannot write or calculate: lesion site?","look":"Balint syndrome","tell":"Gerstmann: LEFT angular gyrus, 4 Fs (fingers, flip L-R, writing, figures). Balint: BILATERAL parieto-occipital, visual triad.","aliases":["gerstmann syndrome","gerstmann's syndrome","gerstmanns syndrome","angular gyrus syndrome"],"lookId":"balint-syndrome"},{"id":"balint-syndrome","name":"Balint syndrome","cat":"term","area":"perception","who":"Rezso Balint","year":"1909","roots":"Eponym: Rezso (Rudolph) Balint, Hungarian neurologist","def":"Triad of simultanagnosia, optic ataxia (cannot reach accurately under vision) and oculomotor apraxia (psychic paralysis of gaze).","detail":"Bilateral parieto-occipital (dorsal stream) lesions, e.g., watershed infarcts, posterior cortical atrophy.","example":"Patient sees only one object at a time and misses when reaching for a cup he can see.","look":"Gerstmann syndrome","tell":"Balint = visual-spatial triad, both parieto-occipital lobes. Gerstmann = language-number tetrad, left angular gyrus.","aliases":["balint syndrome","balint's syndrome","balints syndrome","balint-holmes syndrome"],"lookId":"gerstmann-syndrome"},{"id":"anton-syndrome","name":"Anton syndrome","cat":"term","area":"perception","who":"Gabriel Anton","year":"1899","roots":"Eponym: Gabriel Anton, Austrian neuropsychiatrist","def":"Cortical blindness in which the patient denies being blind and confabulates visual descriptions.","detail":"Bilateral occipital lobe damage (often bilateral posterior cerebral artery strokes); a form of anosognosia (Anton-Babinski syndrome).","example":"A blind patient bumps into furniture yet insists the room is just dark.","look":"Charles Bonnet syndrome","tell":"Anton: blind but DENIES blindness. Charles Bonnet: visually impaired, sees vivid hallucinations but KNOWS they are unreal.","aliases":["anton syndrome","anton's syndrome","antons syndrome","anton-babinski syndrome","visual anosognosia","cortical blindness denial"],"lookId":"charles-bonnet-syndrome"},{"id":"charles-bonnet-syndrome","name":"Charles Bonnet syndrome","cat":"term","area":"perception","who":"Charles Bonnet (described his grandfather); named by Georges de Morsier","year":"1760","roots":"Eponym: Charles Bonnet, Swiss naturalist","def":"Complex visual hallucinations in people with visual loss, with insight that the images are not real and no psychiatric illness.","detail":"Common in elderly with macular degeneration or cataract; 'release' hallucinations from deafferented visual cortex. Images are often small people, faces, patterns.","example":"An 80-year-old with macular degeneration sees tiny people in costume but knows they are not there.","look":"Anton syndrome","tell":"Charles Bonnet: insight preserved. Anton: insight lost (denies blindness).","aliases":["charles bonnet syndrome","charles bonnet","bonnet syndrome","visual release hallucinations"],"lookId":"anton-syndrome"},{"id":"hemispatial-neglect","name":"Hemispatial neglect","cat":"term","area":"perception","who":"","year":"","roots":"hemi (Greek, half) + spatium (Latin, space) + neglect = ignoring half of space","def":"Failure to attend or respond to stimuli on the side opposite a brain lesion, not explained by sensory or motor loss.","detail":"Most often left neglect after right inferior parietal / temporoparietal junction damage. Tested with line bisection, cancellation tasks, clock drawing; may eat only the right half of the plate.","example":"Patient shaves only the right side of his face and draws a clock with numbers only on the right.","look":"Hemianopia","tell":"Hemianopia: a visual field cut; patient knows and turns head to compensate. Neglect: an attention failure; patient is unaware half the world exists.","aliases":["hemispatial neglect","unilateral neglect","hemineglect","spatial neglect","visual neglect","neglect syndrome","hemi-inattention"]},{"id":"alien-hand-syndrome","name":"Alien hand syndrome","cat":"term","area":"biological","who":"Kurt Goldstein (first described); named 'main etrangere' by Brion and Jedynak","year":"1908","roots":"alienus (Latin, belonging to another) + hand","def":"A hand performs complex, purposeful movements that the person did not intend and cannot control.","detail":"Lesions of the corpus callosum (split brain), supplementary motor area or medial frontal cortex; also corticobasal degeneration. Intermanual conflict: one hand undoes what the other does.","example":"The left hand unbuttons the shirt the right hand has just buttoned.","look":"Somatoparaphrenia","tell":"Alien hand: hand acts on its own will. Somatoparaphrenia: delusion that the limb belongs to someone else.","aliases":["alien hand syndrome","alien hand","anarchic hand","alien limb syndrome","dr strangelove syndrome"]},{"id":"capgras-syndrome","name":"Capgras syndrome","cat":"term","area":"clinical","who":"Joseph Capgras and Jean Reboul-Lachaux","year":"1923","roots":"Eponym: Joseph Capgras; original name 'l'illusion des sosies' (illusion of doubles)","def":"Delusion that a familiar person (often a spouse or parent) has been replaced by an identical-looking impostor.","detail":"Delusional misidentification syndrome; seen in schizophrenia, dementia, brain injury. Explained by loss of the emotional (autonomic) response to a familiar face with intact recognition.","example":"'This woman looks exactly like my wife, but she is an impostor.'","look":"Fregoli syndrome","tell":"Capgras: familiar person is a STRANGER in disguise (impostor). Fregoli: strangers are a FAMILIAR person in disguise.","aliases":["capgras syndrome","capgras","capgras delusion","capgras's syndrome","illusion of doubles","illusion des sosies","impostor delusion"],"lookId":"fregoli-syndrome"},{"id":"fregoli-syndrome","name":"Fregoli syndrome","cat":"term","area":"clinical","who":"Paul Courbon and Gabriel Fail","year":"1927","roots":"Eponym: Leopoldo Fregoli, Italian quick-change actor","def":"Delusion that different strangers are actually one familiar person (usually a persecutor) who keeps changing disguise.","detail":"Delusional misidentification syndrome, opposite of Capgras; often persecutory. Seen in schizophrenia and organic lesions.","example":"'The nurse, the postman and the waiter are all my neighbour in disguise, following me.'","look":"Capgras syndrome","tell":"Fregoli: many faces, ONE familiar person behind them. Capgras: one familiar face, an impostor behind it.","aliases":["fregoli syndrome","fregoli","fregoli delusion","illusion of fregoli"],"lookId":"capgras-syndrome"},{"id":"intermetamorphosis","name":"Syndrome of intermetamorphosis","cat":"term","area":"clinical","who":"Paul Courbon and J. Tusques","year":"1932","roots":"inter (Latin, between) + metamorphosis (Greek, change of form) = changing forms between people","def":"Delusion that people swap identities with one another, changing both appearance and personality.","detail":"Rare delusional misidentification syndrome; the patient sees the physical resemblance change, unlike Fregoli where appearance stays different.","example":"'My doctor just turned into my brother; look, his face changed.'","look":"Fregoli syndrome","tell":"Intermetamorphosis: patient SEES the outer appearance change. Fregoli: appearance stays different, only the inner identity is believed the same.","aliases":["intermetamorphosis","syndrome of intermetamorphosis","delusion of intermetamorphosis"],"lookId":"fregoli-syndrome"},{"id":"cotard-syndrome","name":"Cotard syndrome","cat":"term","area":"clinical","who":"Jules Cotard","year":"1880","roots":"Eponym: Jules Cotard; original name 'delire de negation' (delusion of negation)","def":"Nihilistic delusion that one is dead, rotting, has lost organs or blood, or does not exist.","detail":"Classically in severe psychotic depression of the elderly; also schizophrenia and organic states. May paradoxically include delusions of immortality.","example":"'I have no stomach, my intestines have rotted, I am already dead.'","look":"Capgras syndrome","tell":"Cotard: the SELF is dead or non-existent. Capgras: OTHERS are impostors.","aliases":["cotard syndrome","cotard's syndrome","cotards syndrome","cotard delusion","walking corpse syndrome","delire de negation","nihilistic delusion"],"lookId":"capgras-syndrome"},{"id":"othello-syndrome","name":"Othello syndrome","cat":"term","area":"clinical","who":"John Todd and Kenneth Dewhurst (named it)","year":"1955","roots":"Eponym: Shakespeare's Othello, who killed his wife from false jealousy","def":"Delusion (or overvalued idea) that one's sexual partner is unfaithful; morbid or delusional jealousy.","detail":"Strongly associated with alcohol dependence; also paranoid states and organic brain disease. Checking, interrogating, searching for 'evidence'; risk of violence to the partner.","example":"A chronic drinker inspects his wife's underwear daily for proof of infidelity.","look":"De Clerambault syndrome","tell":"Othello: 'my partner is cheating on me'. De Clerambault: 'a famous person is secretly in love with me'.","aliases":["othello syndrome","othello's syndrome","morbid jealousy","delusional jealousy","pathological jealousy","conjugal paranoia"],"lookId":"de-clerambault-syndrome"},{"id":"de-clerambault-syndrome","name":"De Clerambault syndrome","cat":"term","area":"clinical","who":"Gaetan Gatian de Clerambault","year":"1921","roots":"Eponym: G. G. de Clerambault, French psychiatrist; erotomania = eros (love) + mania","def":"Erotomania: the delusion that another person, usually of higher social status, is secretly in love with the patient.","detail":"Classically a woman about an older, more prominent man; the patient interprets ordinary acts as coded signals. A delusional disorder subtype in DSM-5.","example":"A woman believes a film star sends her secret love messages through his interviews.","look":"Othello syndrome","tell":"De Clerambault: delusion of being LOVED. Othello: delusion of being BETRAYED.","aliases":["de clerambault syndrome","de clerambault's syndrome","de clérambault syndrome","de clérambault's syndrome","clerambault syndrome","erotomania","erotomanic delusion","psychose passionelle"],"lookId":"othello-syndrome"},{"id":"ekbom-syndrome","name":"Ekbom syndrome","cat":"term","area":"clinical","who":"Karl-Axel Ekbom","year":"1938","roots":"Eponym: Karl-Axel Ekbom, Swedish neurologist","def":"Delusional parasitosis: fixed belief that one's skin is infested with insects or parasites despite no evidence.","detail":"A somatic delusional disorder; patients bring specimens in a box ('matchbox sign'). Ekbom's name is also on restless legs syndrome (Willis-Ekbom disease), a classic trap.","example":"Woman brings skin flakes in a matchbox as 'proof' of the bugs under her skin.","look":"Formication","tell":"Formication is a tactile SENSATION of insects crawling; Ekbom is the fixed DELUSION of infestation.","aliases":["ekbom syndrome","ekbom's syndrome","ekboms syndrome","delusional parasitosis","delusional infestation","dermatozoic delusion"],"lookId":"formication"},{"id":"folie-a-deux","name":"Folie a deux","cat":"term","area":"clinical","who":"Charles Lasegue and Jules Falret","year":"1877","roots":"French: folie (madness) + a deux (for two) = madness shared by two","def":"Shared delusion transferred from a dominant, primarily psychotic person to a closely associated, usually dependent person.","detail":"Also called induced delusional disorder (ICD-10) or shared psychotic disorder. Close, isolated relationship; separating the secondary person often leads to recovery.","example":"An isolated sister comes to share her brother's belief that the neighbours are poisoning them.","look":"Mass psychogenic illness","tell":"Folie a deux: a fixed delusion passed within a close pair. Mass psychogenic illness: physical symptoms spreading through a group.","aliases":["folie a deux","folie à deux","shared psychotic disorder","induced delusional disorder","shared delusional disorder","folie imposee","communicated insanity"]},{"id":"ganser-syndrome","name":"Ganser syndrome","cat":"term","area":"clinical","who":"Sigbert Ganser","year":"1898","roots":"Eponym: Sigbert Ganser, German psychiatrist","def":"Dissociative condition marked by approximate answers (vorbeireden), clouding of consciousness, pseudohallucinations and conversion symptoms.","detail":"First described in prisoners awaiting trial. Answers show the question was understood ('How many legs does a cow have?' 'Three'). Classified under dissociative disorders.","example":"A prisoner says 2 + 2 = 5 and that a horse has five legs.","look":"Malingering","tell":"Ganser: approximate answers produced in a dissociative state. Malingering: conscious faking for an obvious external gain.","aliases":["ganser syndrome","ganser's syndrome","gansers syndrome","prison psychosis","syndrome of approximate answers","vorbeireden","approximate answers"]},{"id":"munchausen-syndrome","name":"Munchausen syndrome","cat":"term","area":"clinical","who":"Richard Asher","year":"1951","roots":"Eponym: Baron von Munchausen, 18th-century teller of tall tales","def":"Severe chronic factitious disorder: deliberate feigning or producing of illness to assume the sick role, with no external reward.","detail":"Hospital wandering, pseudologia fantastica, multiple surgical scars; DSM-5 'factitious disorder imposed on self'.","example":"A man travels from hospital to hospital with dramatic fake abdominal pain and many laparotomy scars.","look":"Malingering","tell":"Munchausen: wants the SICK ROLE (internal motive). Malingering: wants money, leave or drugs (external motive).","aliases":["munchausen syndrome","munchausen's syndrome","münchausen syndrome","factitious disorder","factitious disorder imposed on self","hospital addiction syndrome"]},{"id":"munchausen-by-proxy","name":"Munchausen syndrome by proxy","cat":"term","area":"clinical","who":"Roy Meadow","year":"1977","roots":"Munchausen + proxy (Latin procuratio, acting on behalf of another)","def":"A caregiver, usually a mother, fabricates or induces illness in a dependent person (usually a child) to gain attention through them.","detail":"DSM-5: factitious disorder imposed on another; the diagnosis goes to the perpetrator. A form of child abuse.","example":"A mother adds salt to her infant's feeds to cause repeated hospital admissions.","look":"Munchausen syndrome","tell":"Plain Munchausen: harms SELF. By proxy: harms ANOTHER.","aliases":["munchausen syndrome by proxy","munchausen by proxy","msbp","factitious disorder imposed on another","fabricated or induced illness"],"lookId":"munchausen-syndrome"},{"id":"couvade-syndrome","name":"Couvade syndrome","cat":"term","area":"clinical","who":"W. H. Trethowan and M. F. Conlon (named the syndrome)","year":"1965","roots":"French couver (to brood, to hatch)","def":"Expectant father experiences pregnancy-like symptoms (nausea, abdominal pain, weight gain) during his partner's pregnancy.","detail":"Sympathetic pregnancy; not delusional, symptoms resolve after delivery. Named after ritual couvade customs in some cultures.","example":"A man gets morning sickness and toothache through his wife's first trimester.","look":"Pseudocyesis","tell":"Couvade: a MAN gets symptoms of his partner's real pregnancy. Pseudocyesis: a WOMAN believes and shows signs of pregnancy without being pregnant.","aliases":["couvade syndrome","couvade","sympathetic pregnancy"]},{"id":"dhat-syndrome","name":"Dhat syndrome","cat":"term","area":"clinical","who":"N. N. Wig (coined the term)","year":"1960","roots":"Sanskrit dhatu (essential bodily constituent, 'elixir') = semen loss syndrome","def":"Culture-bound syndrome of the Indian subcontinent: anxiety and weakness attributed to loss of semen in urine, nocturnal emission or masturbation.","detail":"Symptoms: fatigue, weakness, anxiety, depression, sexual dysfunction. Listed in ICD-10 (F48.8) and the DSM-5 glossary of cultural concepts of distress.","example":"A young man from rural India complains of weakness because he sees 'whitish discharge' in his urine.","look":"Koro","tell":"Dhat: fear of LOSING SEMEN (weakness). Koro: fear of the PENIS RETRACTING (death).","aliases":["dhat syndrome","dhat","semen loss syndrome","jiryan","sukra prameha","shen-k'uei","shen kuei"],"lookId":"koro"},{"id":"koro","name":"Koro","cat":"term","area":"clinical","who":"","year":"","roots":"Malay/Javanese, possibly from kura (tortoise), the head retracting into the shell","def":"Culture-bound acute anxiety that the penis (or vulva, nipples) will retract into the body and cause death.","detail":"South and East Asia (suo yang in China); epidemics reported in Assam and West Bengal, India. Sufferers may tie or clamp the penis to stop retraction.","example":"Panicked men hold their penis to prevent it shrinking into the abdomen during an epidemic.","look":"Dhat syndrome","tell":"Koro = retraction fear, acute panic. Dhat = semen-loss fear, chronic weakness.","aliases":["koro","suo yang","genital retraction syndrome","shook yang"],"lookId":"dhat-syndrome"},{"id":"amok","name":"Amok","cat":"term","area":"clinical","who":"","year":"","roots":"Malay mengamuk (to rush in a frenzy); source of 'running amok'","def":"Culture-bound dissociative episode: brooding followed by a sudden outburst of violent, often homicidal behaviour, then exhaustion and amnesia.","detail":"Classically in Malay men after a perceived insult. Seen as a culture-bound syndrome in the DSM-IV glossary.","example":"After brooding for days, a man suddenly attacks everyone around him and later remembers nothing.","look":"Latah","tell":"Amok: violent frenzy (men). Latah: exaggerated startle with echo-behaviour (women).","aliases":["amok","amuck","running amok","mata elap"],"lookId":"latah"},{"id":"latah","name":"Latah","cat":"term","area":"clinical","who":"","year":"","roots":"Malay latah (ticklish, jumpy)","def":"Culture-bound hypersensitivity to sudden fright, with echolalia, echopraxia, command obedience and coprolalia in a trance-like state.","detail":"Mostly middle-aged women in Malaysia and Indonesia; similar to the 'jumping Frenchmen of Maine'.","example":"Startled by a shout, a woman repeats the words and copies the gestures of the person who startled her.","look":"Amok","tell":"Latah = startle plus echo-behaviour. Amok = frenzy plus violence.","aliases":["latah","jumping frenchmen of maine","myriachit"],"lookId":"amok"},{"id":"diogenes-syndrome","name":"Diogenes syndrome","cat":"term","area":"clinical","who":"A. N. G. Clark, G. D. Mankikar and I. Gray","year":"1975","roots":"Eponym: Diogenes of Sinope, Greek philosopher who lived in a barrel (ironically not a hoarder)","def":"Extreme self-neglect in old age: domestic squalor, hoarding (syllogomania), social withdrawal and refusal of help.","detail":"Senile squalor syndrome; often with frontal lobe dysfunction, dementia or personality traits; not a DSM diagnosis.","example":"An elderly recluse lives among piles of rubbish and rotting food and refuses all services.","look":"Hoarding disorder","tell":"Diogenes: self-neglect and squalor in the elderly. Hoarding disorder: difficulty discarding possessions, any age, self-care may be intact.","aliases":["diogenes syndrome","diogenes","senile squalor syndrome","senile breakdown","syllogomania"]},{"id":"allostasis","name":"Allostasis and allostatic load","cat":"term","area":"biological","who":"Peter Sterling and Joseph Eyer (allostasis, 1988); Bruce McEwen and Eliot Stellar (allostatic load, 1993)","year":"1988","roots":"allos (Greek, other, variable) + stasis (standing) = stability through change","def":"Allostasis: achieving stability by actively changing physiological set points to meet demands. Allostatic load: the cumulative wear and tear from repeated or chronic stress responses.","detail":"McEwen's model links chronic HPA-axis and sympathetic activation to hypertension, obesity, immune suppression and hippocampal damage.","example":"A caregiver under years of stress develops high blood pressure and memory problems: the cost is called?","look":"Homeostasis","tell":"Homeostasis keeps a FIXED set point. Allostasis CHANGES the set point; allostatic load is its long-term price.","aliases":["allostasis","allostatic load","allostatic overload"],"lookId":"homeostasis"},{"id":"homeostasis","name":"Homeostasis","cat":"term","area":"biological","who":"Walter B. Cannon (coined); concept from Claude Bernard's 'milieu interieur'","year":"1926","roots":"homoios (Greek, similar, same) + stasis (standing) = staying the same","def":"Maintenance of a stable internal environment (temperature, glucose, fluid) through self-regulating feedback.","detail":"Cannon popularised it in 'The Wisdom of the Body' (1932). Basis of drive-reduction theory (Hull) in motivation.","example":"Shivering when cold and sweating when hot to keep body temperature near 37 C.","look":"Allostasis","tell":"Homeostasis: constancy at one set point. Allostasis: stability through changing set points.","aliases":["homeostasis","homeostatic","milieu interieur"],"lookId":"allostasis"},{"id":"reactance","name":"Psychological reactance","cat":"term","area":"social","who":"Jack Brehm","year":"1966","roots":"re- (Latin, back) + agere (to act) = acting back against pressure","def":"Motivational state aroused when a person feels their freedom is threatened, leading them to resist or do the opposite.","detail":"Explains the 'forbidden fruit' effect and the boomerang effect of heavy-handed persuasion; basis of reverse psychology.","example":"Teenagers told 'Do not read this book' become more eager to read it.","look":"Cognitive dissonance","tell":"Reactance: pushing back against a threat to FREEDOM. Dissonance: discomfort from INCONSISTENT beliefs or acts.","aliases":["reactance","psychological reactance","reactance theory","boomerang effect"],"lookId":"cognitive-dissonance"},{"id":"alexithymia","name":"Alexithymia","cat":"term","area":"personality","who":"Peter Sifneos (coined)","year":"1973","roots":"a- (not) + lexis (word) + thymos (Greek, emotion) = no words for feelings","def":"Difficulty identifying, describing and distinguishing one's own emotions, with an externally oriented, concrete thinking style.","detail":"Linked to psychosomatic disorders, somatisation, autism, PTSD and substance use. Measured by the Toronto Alexithymia Scale (TAS-20).","example":"A patient with chronic headaches answers 'How do you feel?' only with 'my head hurts'.","look":"Anhedonia","tell":"Alexithymia: cannot NAME feelings. Anhedonia: cannot FEEL pleasure.","aliases":["alexithymia","alexithymic","no words for feelings"],"lookId":"anhedonia"},{"id":"anhedonia","name":"Anhedonia","cat":"term","area":"clinical","who":"Theodule Ribot (coined)","year":"1896","roots":"an- (not) + hedone (Greek, pleasure) = without pleasure","def":"Inability to experience pleasure from activities normally found enjoyable.","detail":"Core symptom of depression (with low mood) and a negative symptom of schizophrenia; anticipatory vs consummatory anhedonia; linked to reward circuitry (dopamine, nucleus accumbens).","example":"A former cricket fan no longer enjoys watching matches or eating his favourite food.","look":"Avolition","tell":"Anhedonia: no PLEASURE. Avolition: no DRIVE to start.","aliases":["anhedonia","anhedonic","loss of pleasure"],"lookId":"avolition"},{"id":"avolition","name":"Avolition","cat":"term","area":"clinical","who":"","year":"","roots":"a- (not) + volitio (Latin, will) = without will","def":"Reduced ability to initiate and persist in goal-directed activities.","detail":"Negative symptom of schizophrenia (one of the 5 As: alogia, affective flattening, avolition, anhedonia, asociality). Psychiatric term.","example":"A man with schizophrenia sits at home all day, not washing or looking for work, though able to.","look":"Abulia","tell":"Avolition: psychiatric term, negative symptom. Abulia: neurological term, frontal/basal ganglia damage.","aliases":["avolition","apathy-avolition","amotivation"],"lookId":"abulia"},{"id":"abulia","name":"Abulia","cat":"term","area":"biological","who":"","year":"","roots":"a- (not) + boule (Greek, will, decision) = without will","def":"Lack of will or initiative with slowed, reduced spontaneous behaviour and speech.","detail":"Neurological sign of frontal lobe, anterior cingulate or basal ganglia damage; its extreme form is akinetic mutism.","example":"After a bilateral anterior cerebral artery stroke, a patient answers only after long delays and never starts activity.","look":"Avolition","tell":"Abulia: neurological lesion term. Avolition: schizophrenia negative-symptom term.","aliases":["abulia","aboulia","lack of will"],"lookId":"avolition"},{"id":"akathisia","name":"Akathisia","cat":"term","area":"biological","who":"Ladislav Haskovec (coined)","year":"1901","roots":"a- (not) + kathisis (Greek, sitting) = inability to sit","def":"Subjective inner restlessness with an urge to move, causing pacing, fidgeting and inability to sit still.","detail":"Most common extrapyramidal side effect of antipsychotics (especially high-potency); linked to suicidality; treated with propranolol, dose reduction or benzodiazepines.","example":"After starting haloperidol, a patient keeps shifting his legs and pacing the ward.","look":"Restless legs syndrome","tell":"Akathisia: drug-induced, whole-body restlessness, any time. Restless legs: legs, worse at night lying down, relieved by moving.","aliases":["akathisia","acathisia"]},{"id":"tardive-dyskinesia","name":"Tardive dyskinesia","cat":"term","area":"biological","who":"","year":"","roots":"tardus (Latin, late) + dys- (bad) + kinesis (Greek, movement) = late-appearing abnormal movement","def":"Late-onset involuntary choreoathetoid movements, mainly of the mouth, tongue and face, after long-term antipsychotic use.","detail":"Lip smacking, tongue protrusion, chewing; attributed to dopamine receptor supersensitivity; rated with AIMS; may be irreversible; VMAT2 inhibitors (valbenazine) treat it.","example":"After 10 years on typical antipsychotics, a woman constantly smacks her lips and rolls her tongue.","look":"Acute dystonia","tell":"Tardive dyskinesia: LATE (years), rhythmic oral movements. Acute dystonia: EARLY (hours-days), sustained spasm (torticollis, oculogyric crisis).","aliases":["tardive dyskinesia","tardive dyskinesias","orofacial dyskinesia"]},{"id":"catalepsy","name":"Catalepsy","cat":"term","area":"clinical","who":"","year":"","roots":"kata (Greek, down) + lepsis (seizing) = seized, held fixed","def":"Maintenance of a posture, often an odd one, for a long time against gravity.","detail":"Catatonic motor sign; in Fish, catalepsy is the abnormal maintenance of posture, and waxy flexibility is the feeling of plastic resistance as the limb is moved into it.","example":"A catatonic patient holds his arm raised in the air for an hour.","look":"Cataplexy","tell":"Catalepsy: rigid posture HELD (catatonia). Cataplexy: sudden muscle tone LOST with emotion (narcolepsy).","aliases":["catalepsy","cataleptic","posturing"],"lookId":"cataplexy"},{"id":"waxy-flexibility","name":"Waxy flexibility","cat":"term","area":"clinical","who":"","year":"","roots":"Latin flexibilitas cerea: cera (wax) = bendable like soft wax","def":"Limbs can be moulded into any position, with a feeling of plastic resistance like bending a wax candle, and then stay there.","detail":"Catatonic sign; closely linked to catalepsy (the posture then maintained). Seen in catatonic schizophrenia, mood disorders, NMS-like organic states.","example":"The examiner lifts the patient's arm, feels slight even resistance, and the arm stays where placed.","look":"Catalepsy","tell":"Waxy flexibility describes how the limb FEELS when moved; catalepsy describes the posture being HELD.","aliases":["waxy flexibility","flexibilitas cerea","cerea flexibilitas"],"lookId":"catalepsy"},{"id":"cataplexy","name":"Cataplexy","cat":"term","area":"biological","who":"","year":"","roots":"kata (Greek, down) + plexis (striking) = struck down","def":"Sudden, brief loss of muscle tone triggered by strong emotion (often laughter), with consciousness preserved.","detail":"Pathognomonic of narcolepsy type 1 (loss of orexin/hypocretin neurons in the hypothalamus); an intrusion of REM atonia into wakefulness.","example":"Every time he laughs at a joke, his knees buckle and he drops to the floor, fully aware.","look":"Catalepsy","tell":"CataPLEXY: Plunge (tone lost, narcolepsy). CataLEPSY: Locked posture (catatonia).","aliases":["cataplexy","cataplectic attack"],"lookId":"catalepsy"},{"id":"echopraxia","name":"Echopraxia","cat":"term","area":"clinical","who":"","year":"","roots":"echo (repeated) + praxis (Greek, action) = echoed action","def":"Automatic imitation of another person's movements or gestures.","detail":"Seen in catatonia, Tourette's, latah, frontal lobe lesions; a form of automatic obedience.","example":"The examiner scratches his head and the patient immediately does the same.","look":"Echolalia","tell":"Echopraxia copies ACTIONS; echolalia copies WORDS.","aliases":["echopraxia","echopraxis","echokinesis"],"lookId":"echolalia"},{"id":"mitgehen","name":"Mitgehen","cat":"term","area":"clinical","who":"","year":"","roots":"German mit (with) + gehen (to go) = going with","def":"Extreme form of automatic obedience: the patient's body moves in the direction of the slightest pressure from the examiner, even when told to resist.","detail":"Catatonic sign ('anglepoise lamp' sign); the extreme of mitmachen, in which the body can be put in any position and returns afterwards.","example":"A fingertip touch makes the patient's arm rise, despite instructions to resist.","look":"Mitmachen","tell":"Mitmachen: lets you place the limb, then it returns. Mitgehen: the limb follows the lightest touch, like an anglepoise lamp.","aliases":["mitgehen","anglepoise lamp sign"]},{"id":"negativism","name":"Negativism","cat":"term","area":"clinical","who":"","year":"","roots":"negare (Latin, to deny) = motiveless refusal","def":"Motiveless resistance to all instructions or attempts to be moved; active negativism does the opposite of what is asked.","detail":"Catatonic sign. Passive negativism: does not comply; active: does the opposite (asked to open eyes, shuts them tighter).","example":"Asked to stand, the patient sits down harder; offered a hand, he pulls his away.","look":"Gegenhalten","tell":"Negativism: resists ALL instructions (catatonia). Gegenhalten: opposes passive limb movement with equal force (frontal/organic).","aliases":["negativism","active negativism","passive negativism"]},{"id":"depersonalization","name":"Depersonalization","cat":"term","area":"clinical","who":"Ludovic Dugas (coined)","year":"1898","roots":"de- (removal) + persona (Latin, person, self) = loss of the sense of self","def":"Feeling that one's self is unreal, detached, or that one is an outside observer of one's own body or mind, with intact reality testing.","detail":"Feels 'as if' (not delusional); common in anxiety, depression, fatigue, epilepsy; DSM-5 depersonalization/derealization disorder.","example":"'I feel like a robot, watching myself from outside.'","look":"Derealization","tell":"DePERSONalization = the PERSON (self) feels unreal. DeREALization = the outside world feels unreal.","aliases":["depersonalization","depersonalisation","depersonalization disorder","depersonalization-derealization disorder"],"lookId":"derealization"},{"id":"derealization","name":"Derealization","cat":"term","area":"clinical","who":"","year":"","roots":"de- (removal) + realis (Latin, actual) = loss of reality of the surroundings","def":"Feeling that the external world is unreal, dreamlike, distant, foggy or lifeless, with intact reality testing.","detail":"Often co-occurs with depersonalization; in anxiety, panic attacks, temporal lobe epilepsy, drug use.","example":"'Everything around me looks like a film set, flat and artificial.'","look":"Depersonalization","tell":"Derealization: the WORLD feels unreal. Depersonalization: the SELF feels unreal.","aliases":["derealization","derealisation"],"lookId":"depersonalization"},{"id":"hypnagogic-hallucination","name":"Hypnagogic hallucination","cat":"term","area":"clinical","who":"","year":"","roots":"hypnos (Greek, sleep) + agogos (leading) = leading into sleep","def":"Hallucination occurring while falling asleep.","detail":"Common in healthy people and not by themselves pathological; frequent in narcolepsy (with sleep paralysis and cataplexy).","example":"As she drifts off, a woman hears someone call her name.","look":"Hypnopompic hallucination","tell":"HypnaGOgic: GOing to sleep. HypnoPOMPic: POPping awake.","aliases":["hypnagogic hallucination","hypnagogic hallucinations","hypnagogic"],"lookId":"hypnopompic-hallucination"},{"id":"hypnopompic-hallucination","name":"Hypnopompic hallucination","cat":"term","area":"clinical","who":"","year":"","roots":"hypnos (Greek, sleep) + pompos (sending away) = sending away sleep","def":"Hallucination occurring while waking up.","detail":"Like hypnagogic hallucinations, common in normal people and in narcolepsy; Frederic Myers coined the term.","example":"On waking, a man sees a figure standing by the bed that vanishes as he fully wakes.","look":"Hypnagogic hallucination","tell":"Hypnopompic = waking up; hypnagogic = falling asleep.","aliases":["hypnopompic hallucination","hypnopompic hallucinations","hypnopompic"],"lookId":"hypnagogic-hallucination"},{"id":"pseudohallucination","name":"Pseudohallucination","cat":"term","area":"clinical","who":"Victor Kandinsky (classic description)","year":"1885","roots":"pseudes (Greek, false) + hallucination = false hallucination","def":"A vivid perception-like experience that lacks the substantiality of a true percept and is experienced in inner subjective space ('in the mind').","detail":"Jaspers: figurative, not concrete; located in inner space. Common in grief, dissociative states, personality disorders. Insight is usually present.","example":"A widow 'hears' her husband's voice inside her head, clearly not out in the room.","look":"Hallucination","tell":"True hallucination: in OUTER space, as real as a percept. Pseudohallucination: in INNER space, lacking full reality.","aliases":["pseudohallucination","pseudohallucinations","pseudo-hallucination","pseudo hallucination"],"lookId":"hypnagogic-hallucination"},{"id":"illusion","name":"Illusion","cat":"term","area":"perception","who":"Jean-Etienne Esquirol (distinguished it from hallucination)","year":"","roots":"illudere (Latin, to mock, deceive) = deceived perception","def":"Misperception or misinterpretation of a REAL external stimulus.","detail":"Fish's three types: completion illusion (inattention), affect illusion (mood-driven), pareidolia (vivid images from vague stimuli like clouds). Common in delirium and normal people.","example":"In a dark room, a frightened child sees a coat on a hook as a burglar.","look":"Hallucination","tell":"Illusion: a real stimulus, misread. Hallucination: no external stimulus at all ('perception without an object', Esquirol).","aliases":["illusion","illusions","affect illusion","completion illusion","pareidolia"],"lookId":"hypnagogic-hallucination"},{"id":"reflex-hallucination","name":"Reflex hallucination","cat":"term","area":"perception","who":"","year":"","roots":"reflectere (Latin, to bend back) + hallucination = hallucination reflected into another sense","def":"A real stimulus in one sensory modality produces a hallucination in a different modality.","detail":"A morbid form of synaesthesia (Fish, Sims). Seen in schizophrenia and drug states.","example":"Every time the patient hears a door slam, he feels a pain in his head.","look":"Functional hallucination","tell":"Reflex: stimulus in one SENSE, hallucination in ANOTHER. Functional: stimulus and hallucination in the SAME sense, perceived together.","aliases":["reflex hallucination","reflex hallucinations"],"lookId":"functional-hallucination"},{"id":"functional-hallucination","name":"Functional hallucination","cat":"term","area":"perception","who":"","year":"","roots":"functio (Latin, performance) + hallucination = hallucination triggered by a functioning stimulus","def":"A real stimulus triggers a hallucination in the same modality, and both are perceived at the same time.","detail":"The hallucination appears only while the stimulus is present, and is not a distortion of it (unlike an illusion). Seen in schizophrenia.","example":"The patient hears voices only when the tap is running, and hears both the water and the voices.","look":"Reflex hallucination","tell":"Functional: same modality, both heard together. Reflex: crosses into a different modality.","aliases":["functional hallucination","functional hallucinations"],"lookId":"reflex-hallucination"},{"id":"extracampine-hallucination","name":"Extracampine hallucination","cat":"term","area":"perception","who":"Eugen Bleuler (named it)","year":"","roots":"extra (Latin, outside) + campus (field) = outside the sensory field","def":"Hallucination experienced outside the limits of the relevant sensory field.","detail":"Seen in schizophrenia, epilepsy and organic states; also in healthy people while falling asleep.","example":"A patient 'sees' a man standing behind his head, or hears voices from another city.","look":"Autoscopy","tell":"Extracampine: perceived OUTSIDE the possible sensory field. Autoscopy: seeing one's own double.","aliases":["extracampine hallucination","extracampine hallucinations","extracampine"]},{"id":"formication","name":"Formication","cat":"term","area":"perception","who":"","year":"","roots":"formica (Latin, ant) = feeling of ants crawling","def":"Tactile hallucination of insects crawling on or under the skin.","detail":"Classic with cocaine ('cocaine bugs', Magnan's sign), amphetamines and alcohol withdrawal / delirium tremens.","example":"A cocaine user scratches his arms raw, feeling bugs under the skin.","look":"Ekbom syndrome","tell":"Formication = the crawling SENSATION (tactile hallucination). Ekbom = the fixed DELUSION of infestation.","aliases":["formication","cocaine bugs","magnan's sign","magnan sign"],"lookId":"ekbom-syndrome"},{"id":"thought-insertion","name":"Thought insertion","cat":"term","area":"clinical","who":"Kurt Schneider (first-rank symptom)","year":"","roots":"inserere (Latin, to put in) = thoughts put into the mind","def":"Delusional experience that thoughts which are not one's own are being placed into one's mind by an outside agency.","detail":"Schneiderian first-rank symptom of schizophrenia (thought alienation). The thought itself may be ordinary; what matters is it is felt as alien.","example":"'The thought to kill the cat is not mine; the TV station put it into my head.'","look":"Obsession","tell":"Thought insertion: thought is NOT MINE, put in from outside. Obsession: thought is MINE, though unwanted and resisted.","aliases":["thought insertion","inserted thoughts"]},{"id":"thought-withdrawal","name":"Thought withdrawal","cat":"term","area":"clinical","who":"Kurt Schneider (first-rank symptom)","year":"","roots":"withdraw = thoughts taken out of the mind","def":"Delusional experience that one's thoughts are being removed from the mind by an outside agency.","detail":"Schneiderian first-rank symptom; often accompanies thought block, which is its observable sign.","example":"'My mind went blank because the aliens took my thoughts away.'","look":"Thought block","tell":"Thought block: the observed sudden stop. Thought withdrawal: the delusional explanation that someone removed them.","aliases":["thought withdrawal","thought deprivation"],"lookId":"thought-block"},{"id":"thought-broadcasting","name":"Thought broadcasting","cat":"term","area":"clinical","who":"Kurt Schneider (first-rank symptom)","year":"","roots":"broadcast = thoughts spread out to others","def":"Delusional experience that one's thoughts are diffusing out of the mind so that others know or share them.","detail":"Schneiderian first-rank symptom; Fish calls it thought diffusion.","example":"'Everyone on the bus knows what I am thinking because my thoughts leak out.'","look":"Thought echo","tell":"Broadcasting: others know my thoughts. Thought echo (gedankenlautwerden): I hear my own thoughts spoken aloud.","aliases":["thought broadcasting","thought broadcast","thought diffusion"]},{"id":"passivity-phenomena","name":"Passivity phenomena","cat":"term","area":"clinical","who":"Kurt Schneider (first-rank symptoms)","year":"","roots":"passivus (Latin, capable of suffering, acted upon) = being acted upon","def":"Experiences that one's feelings, impulses, actions or bodily sensations are controlled or imposed by an external force (made experiences).","detail":"Schneiderian first-rank symptoms: made feelings, made impulses, made volitional acts, somatic passivity. Indicates loss of ego boundaries in schizophrenia.","example":"'My arm moved to hit him; the machine controlled it, not me.'","look":"Thought insertion","tell":"Passivity = control of FEELINGS, IMPULSES, ACTS or body. Thought insertion = the thought-specific form of alien control.","aliases":["passivity phenomena","passivity phenomenon","passivity experiences","made acts","made feelings","made impulses","made volition","somatic passivity","delusion of control"],"lookId":"thought-insertion"},{"id":"circumstantiality","name":"Circumstantiality","cat":"term","area":"clinical","who":"","year":"","roots":"circum (Latin, around) + stare (to stand) = standing around the point","def":"Speech that is slow to reach the point because of unnecessary detail, but eventually gets there.","detail":"Seen in epilepsy, obsessional personality, intellectual disability, organic states, and normal people.","example":"Asked his age, he describes his birth, the hospital and his school, then finally says '45'.","look":"Tangentiality","tell":"Circumstantial: gets THERE eventually. Tangential: never gets there.","aliases":["circumstantiality","circumstantial speech","circumstantial thinking"],"lookId":"tangentiality"},{"id":"tangentiality","name":"Tangentiality","cat":"term","area":"clinical","who":"","year":"","roots":"tangere (Latin, to touch) = touching the point and flying off","def":"Replies that are obliquely related or irrelevant to the question, never reaching the point.","detail":"Formal thought disorder in schizophrenia and mania.","example":"Asked 'Where do you live?', answers 'Living is hard, life is a journey, journeys need trains.'","look":"Circumstantiality","tell":"Tangentiality never returns to the goal; circumstantiality takes a detour but arrives.","aliases":["tangentiality","tangential speech","tangential thinking"],"lookId":"circumstantiality"},{"id":"flight-of-ideas","name":"Flight of ideas","cat":"term","area":"clinical","who":"","year":"","roots":"English: ideas taking flight, rushing from one to the next","def":"Rapid speech with quick jumps between ideas linked by chance associations, rhymes, puns or distracting stimuli.","detail":"Characteristic of mania, with pressure of speech; the links between ideas are understandable, the goal is lost.","example":"'I went to the bank, bank of the river, river of life, life is a song, sing with me!'","look":"Derailment","tell":"Flight of ideas: fast, links are understandable (sounds, puns), in mania. Derailment: links are not understandable, in schizophrenia.","aliases":["flight of ideas"],"lookId":"derailment"},{"id":"derailment","name":"Derailment (knight's move thinking)","cat":"term","area":"clinical","who":"","year":"","roots":"de- (off) + rail = thought going off the rails; knight's move = an L-shaped chess jump","def":"Train of thought slides off onto an obliquely related or unrelated idea without logical connection.","detail":"Loosening of association (Bleuler) in schizophrenia; Fish's 'knight's move thinking'. Unlike flight of ideas, the connections cannot be followed.","example":"'I like curry. The prime minister ran up the hill of silver ladders.'","look":"Flight of ideas","tell":"Derailment: odd, unfollowable jumps (schizophrenia). Flight of ideas: fast but followable jumps (mania).","aliases":["derailment","knight's move thinking","knights move thinking","knight's move","loosening of association","loosening of associations","loose associations","asyndesis"],"lookId":"flight-of-ideas"},{"id":"clang-association","name":"Clang association","cat":"term","area":"clinical","who":"","year":"","roots":"clang (English, resonant sound) = linking by sound","def":"Thoughts and words linked by their sound (rhymes, puns) rather than their meaning.","detail":"Typical of mania (part of flight of ideas); also schizophrenia.","example":"'I am the king, sing, ring, bring me a thing.'","look":"Flight of ideas","tell":"Clang association is one TYPE of link (sound); flight of ideas is the overall rapid shifting pattern.","aliases":["clang association","clang associations","clanging","clang"],"lookId":"flight-of-ideas"},{"id":"thought-block","name":"Thought block","cat":"term","area":"clinical","who":"","year":"","roots":"English: thought stream blocked","def":"Sudden interruption of the train of thought, leaving a blank, before the thought is complete.","detail":"Typical of schizophrenia; the patient may explain it as thought withdrawal. Must be distinguished from ordinary losing the thread in anxiety or fatigue.","example":"Mid-sentence the patient stops dead, then says 'My mind just went empty.'","look":"Thought withdrawal","tell":"Block = the sudden stop seen by others. Withdrawal = the delusion that someone took the thoughts.","aliases":["thought block","thought blocking","blocking"],"lookId":"thought-withdrawal"},{"id":"overvalued-idea","name":"Overvalued idea","cat":"term","area":"clinical","who":"Carl Wernicke (described)","year":"","roots":"over + valuere (Latin, to be worth) = an idea given excess value","def":"A plausible, emotionally charged belief that dominates a person's life, held with more intensity than reason justifies but not with delusional certainty.","detail":"Understandable in terms of the person's background; seen in anorexia nervosa, body dysmorphic disorder, morbid jealousy, hypochondriasis.","example":"An anorexic girl's conviction that she must be thin, which rules her whole life.","look":"Delusion","tell":"Overvalued idea: understandable, culturally plausible, can be shaken a little. Delusion: false, unshakeable, out of keeping with culture.","aliases":["overvalued idea","overvalued ideas","over-valued idea"],"lookId":"capgras-syndrome"},{"id":"delusional-perception","name":"Delusional perception","cat":"term","area":"clinical","who":"Kurt Schneider (first-rank symptom)","year":"","roots":"delusion + perception = a normal perception given delusional meaning","def":"A normal perception that is suddenly given a private, delusional significance with no logical link.","detail":"Two-membered: normal percept, then unrelated delusional meaning. Schneiderian first-rank symptom, a primary delusion.","example":"'When I saw the traffic light turn red, I knew I was the chosen saviour.'","look":"Delusional mood","tell":"Delusional perception: a specific percept, then sudden meaning. Delusional mood (Wahnstimmung): vague feeling that something strange is going on, before any meaning.","aliases":["delusional perception","delusional percept","wahnwahrnehmung"]},{"id":"dysmorphophobia","name":"Dysmorphophobia","cat":"term","area":"clinical","who":"Enrico Morselli (coined)","year":"1891","roots":"dys- (bad) + morphe (Greek, shape) + phobos (fear) = fear of being misshapen","def":"Preoccupation with an imagined or slight defect in physical appearance.","detail":"Now body dysmorphic disorder (DSM-5 obsessive-compulsive and related disorders); mirror checking, cosmetic surgery seeking; muscle dysmorphia subtype.","example":"A good-looking young man is convinced his nose is grotesque and checks it for hours.","look":"Hypochondriasis","tell":"Dysmorphophobia: fear of looking UGLY. Hypochondriasis: fear of being ILL.","aliases":["dysmorphophobia","body dysmorphic disorder","bdd","imagined ugliness"]},{"id":"la-belle-indifference","name":"La belle indifference","cat":"term","area":"clinical","who":"","year":"","roots":"French: 'beautiful indifference'","def":"Inappropriate lack of concern about a seemingly serious disability.","detail":"Classically linked with conversion disorder, but not diagnostic: it also occurs in organic illness and stoical patients (DSM-5 says it is not specific).","example":"A woman with sudden paralysis of both legs chats cheerfully, unbothered.","look":"Anosognosia","tell":"La belle indifference: aware of the deficit but unconcerned (conversion). Anosognosia: unaware of the deficit (right parietal).","aliases":["la belle indifference","la belle indifférence","belle indifference"],"lookId":"anosognosia"},{"id":"somatization","name":"Somatization","cat":"term","area":"clinical","who":"Wilhelm Stekel (coined)","year":"","roots":"soma (Greek, body) + -ization = turning distress into bodily symptoms","def":"Expression of psychological distress as multiple physical symptoms without adequate organic explanation.","detail":"Old 'somatization disorder' (Briquet's syndrome): many symptoms across several organ systems over years; DSM-5 now somatic symptom disorder.","example":"A woman has had headaches, stomach pain, back pain and palpitations for years, with normal tests.","look":"Conversion","tell":"Somatization: MANY bodily complaints (pain, GI, sexual). Conversion: a NEUROLOGICAL symptom (paralysis, blindness, fits).","aliases":["somatization","somatisation","somatization disorder","briquet's syndrome","briquet syndrome","somatic symptom disorder"],"lookId":"conversion"},{"id":"conversion","name":"Conversion","cat":"term","area":"clinical","who":"Sigmund Freud (coined, with Breuer)","year":"","roots":"convertere (Latin, to turn around) = psychic conflict turned into a bodily symptom","def":"Loss or alteration of motor or sensory function suggesting neurological disease, not explained by it, linked to psychological conflict.","detail":"DSM-5 functional neurological symptom disorder; primary gain (conflict kept out of awareness) and secondary gain; signs inconsistent with anatomy (Hoover's sign, glove anaesthesia).","example":"After a violent quarrel, a woman suddenly cannot move her right arm; reflexes are normal.","look":"Somatization","tell":"Conversion: neurological-type symptom. Somatization: many vague bodily symptoms.","aliases":["conversion","conversion disorder","hysterical conversion","functional neurological symptom disorder","dissociative motor disorder"],"lookId":"somatization"},{"id":"dissociation","name":"Dissociation","cat":"term","area":"clinical","who":"Pierre Janet","year":"1889","roots":"dis (apart) + sociare (Latin, to join) = coming apart","def":"Disruption of the normal integration of consciousness, memory, identity, perception or motor control.","detail":"Janet's 'desagregation'; includes dissociative amnesia, fugue, identity disorder, depersonalization, trance and possession states.","example":"Under extreme stress a soldier feels he is watching events from outside his body.","look":"Repression","tell":"Repression (Freud): content pushed DOWN into the unconscious. Dissociation (Janet): content split off SIDEWAYS into a separate stream.","aliases":["dissociation","dissociative","dissociative disorder","desagregation"]},{"id":"dissociative-fugue","name":"Dissociative fugue","cat":"term","area":"clinical","who":"","year":"","roots":"fuga (Latin, flight) = flight away","def":"Sudden purposeful travel away from home with inability to recall one's past, sometimes with confusion about or a new identity.","detail":"Precipitated by stress; DSM-5 specifier of dissociative amnesia, ICD-10 F44.1. Appears normal to observers; ends abruptly with amnesia for the fugue.","example":"A bankrupt businessman is found weeks later in another city working under a new name.","look":"Dissociative amnesia","tell":"Fugue = amnesia + travel (+ new identity). Plain amnesia = no travel.","aliases":["dissociative fugue","fugue","psychogenic fugue","fugue state"],"lookId":"dissociative-amnesia"},{"id":"trichotillomania","name":"Trichotillomania","cat":"term","area":"clinical","who":"Francois Hallopeau (coined)","year":"1889","roots":"thrix, trichos (Greek, hair) + tillein (to pull) + mania (madness) = hair-pulling madness","def":"Recurrent pulling out of one's own hair, causing hair loss, with repeated attempts to stop.","detail":"DSM-5 obsessive-compulsive and related disorder; tension before, relief after; may eat the hair (trichophagia) causing a trichobezoar. Treated by habit reversal.","example":"A girl has bald patches on her scalp from pulling hair while studying.","look":"Excoriation disorder","tell":"Trichotillomania pulls HAIR; excoriation (dermatillomania) picks SKIN.","aliases":["trichotillomania","hair-pulling disorder","hair pulling disorder","trichotillosis"]},{"id":"pica","name":"Pica","cat":"term","area":"developmental","who":"","year":"","roots":"pica (Latin, magpie, a bird that eats anything)","def":"Persistent eating of non-nutritive, non-food substances (soil, chalk, paper, hair) for at least one month.","detail":"Linked to iron or zinc deficiency, pregnancy, intellectual disability, autism; diagnosed only if developmentally inappropriate (usually after age 2). Geophagia = eating earth.","example":"A 6-year-old with anaemia repeatedly eats wall plaster and mud.","look":"Rumination disorder","tell":"Pica: eats NON-FOOD. Rumination: regurgitates and re-chews ordinary FOOD.","aliases":["pica","geophagia","geophagy"]},{"id":"enuresis","name":"Enuresis","cat":"term","area":"developmental","who":"","year":"","roots":"en (Greek, in) + ourein (to urinate) = urinating in (bed, clothes)","def":"Repeated voiding of urine into bed or clothes at age 5 or older (developmental age), not due to a medical condition.","detail":"Nocturnal (most common, bedwetting), diurnal, or mixed; primary vs secondary. Bell-and-pad alarm (Mowrer, classical conditioning) is the most effective treatment; desmopressin for short-term use.","example":"A 7-year-old boy still wets the bed several nights a week.","look":"Encopresis","tell":"EnURESIS = URINE, age 5. EnCOPRESIS = faeces (kopros), age 4.","aliases":["enuresis","nocturnal enuresis","bedwetting","bed wetting","bed-wetting"],"lookId":"encopresis"},{"id":"encopresis","name":"Encopresis","cat":"term","area":"developmental","who":"","year":"","roots":"en (Greek, in) + kopros (faeces) = faeces in (clothes)","def":"Repeated passage of faeces in inappropriate places at age 4 or older, not due to a medical condition.","detail":"Most often with constipation and overflow incontinence; may follow stress or coercive toilet training.","example":"A 6-year-old repeatedly soils his pants at school.","look":"Enuresis","tell":"Encopresis = stool (age 4). Enuresis = urine (age 5).","aliases":["encopresis","faecal soiling","fecal soiling","soiling"],"lookId":"enuresis"},{"id":"akinetopsia","name":"Akinetopsia","cat":"term","area":"perception","who":"Josef Zihl, D. von Cramon and N. Mai (patient L.M.)","year":"1983","roots":"a- (not) + kinesis (Greek, movement) + opsis (seeing) = not seeing motion","def":"Inability to perceive motion; the world appears as a series of still frames.","detail":"Bilateral lesion of area V5/MT (middle temporal). Patient L.M. could not pour tea because the liquid seemed frozen.","example":"A woman cannot cross a road because cars seem to jump from far away to right beside her.","look":"Achromatopsia","tell":"AKINETopsia = no MOTION (V5). ACHROMatopsia = no COLOUR (V4).","aliases":["akinetopsia","motion blindness","cerebral akinetopsia"],"lookId":"achromatopsia"},{"id":"achromatopsia","name":"Achromatopsia","cat":"term","area":"perception","who":"","year":"","roots":"a- (not) + chroma (Greek, colour) + opsis (seeing) = not seeing colour","def":"Cerebral loss of colour vision; the world appears in shades of grey.","detail":"Lesion of area V4 (lingual and fusiform gyri, ventral occipitotemporal). Distinct from retinal colour blindness. Sacks' 'colour-blind painter' case.","example":"After a stroke an artist sees everything 'like a black-and-white television'.","look":"Akinetopsia","tell":"Achromatopsia: colour lost (V4). Akinetopsia: motion lost (V5).","aliases":["achromatopsia","cerebral achromatopsia","cortical colour blindness"],"lookId":"akinetopsia"},{"id":"ataxia","name":"Ataxia","cat":"term","area":"biological","who":"","year":"","roots":"a- (not) + taxis (Greek, order, arrangement) = lack of order","def":"Lack of coordination of voluntary movements, without muscle weakness.","detail":"Cerebellar (wide-based gait, intention tremor, dysdiadochokinesia), sensory (positive Romberg) or vestibular. Part of the Wernicke triad.","example":"A drunk man cannot walk heel-to-toe and misses his nose on finger-nose testing.","look":"Apraxia","tell":"Ataxia: movements are UNCOORDINATED (cerebellum). Apraxia: coordination fine but SKILLED, purposeful acts cannot be planned (parietal/frontal).","aliases":["ataxia","cerebellar ataxia","sensory ataxia","ataxic gait"],"lookId":"ideomotor-apraxia"},{"id":"chorea","name":"Chorea","cat":"term","area":"biological","who":"","year":"","roots":"choreia (Greek, dance) = dancing movements","def":"Brief, irregular, jerky, non-repetitive involuntary movements that flit from one body part to another.","detail":"Basal ganglia (caudate) disorder: Huntington's disease (autosomal dominant CAG repeat), Sydenham chorea (rheumatic fever, 'St Vitus dance').","example":"A 40-year-old with a family history shows fidgety, dance-like jerks and personality change.","look":"Athetosis","tell":"Chorea: FAST, jerky, dancing. Athetosis: SLOW, writhing, snake-like.","aliases":["chorea","huntington's chorea","sydenham chorea","st vitus dance","choreiform movements","choreoathetosis"],"lookId":"athetosis"},{"id":"athetosis","name":"Athetosis","cat":"term","area":"biological","who":"William Hammond (named it)","year":"1871","roots":"a- (not) + thetos (Greek, fixed, placed) = without a fixed position","def":"Slow, continuous, writhing movements, especially of the hands and fingers.","detail":"Basal ganglia (putamen) damage; seen in athetoid cerebral palsy (kernicterus). Often mixed with chorea (choreoathetosis).","example":"A child with cerebral palsy has slow, twisting finger movements he cannot keep still.","look":"Chorea","tell":"Athetosis is slow and writhing; chorea is quick and dance-like.","aliases":["athetosis","athetoid movements","athetoid cerebral palsy"],"lookId":"chorea"},{"id":"hemiballismus","name":"Hemiballismus","cat":"term","area":"biological","who":"","year":"","roots":"hemi (Greek, half) + ballismos (jumping, throwing) = flinging of one side","def":"Violent, wide-amplitude, flinging movements of the limbs on one side of the body.","detail":"Lesion (often lacunar stroke) of the contralateral subthalamic nucleus.","example":"After a small stroke, an old man's left arm suddenly flings out wildly: which nucleus?","look":"Chorea","tell":"Hemiballismus: large FLINGING movements, one side, subthalamic nucleus. Chorea: smaller dance-like jerks, caudate.","aliases":["hemiballismus","hemiballism","ballismus","ballism"],"lookId":"chorea"},{"id":"mutism","name":"Mutism","cat":"term","area":"clinical","who":"","year":"","roots":"mutus (Latin, silent, dumb)","def":"Complete absence of speech in a conscious person.","detail":"Causes: catatonia, severe depression, conversion, selective mutism (child speaks at home but not at school), akinetic mutism (frontal/ACC lesions), aphasia.","example":"A 6-year-old talks freely at home but never speaks a word at school: which disorder?","look":"Aphonia","tell":"Mutism: no SPEECH at all. Aphonia: speech attempted but no VOICE, only whisper (often conversion or laryngeal).","aliases":["mutism","selective mutism","elective mutism","akinetic mutism"]},{"id":"anosmia","name":"Anosmia","cat":"term","area":"biological","who":"","year":"","roots":"an- (not) + osme (Greek, smell) = without smell","def":"Complete loss of the sense of smell.","detail":"Causes: head injury (shearing of olfactory fibres at the cribriform plate), early Parkinson's and Alzheimer's, Kallmann syndrome, viral infection (COVID-19), Foster Kennedy syndrome (olfactory groove meningioma).","example":"After falling on the back of his head, a cook can no longer smell food.","look":"Parosmia","tell":"Anosmia: smell ABSENT. Parosmia: smell DISTORTED. Phantosmia: smell with no source.","aliases":["anosmia","loss of smell","hyposmia"]},{"id":"dyslexia","name":"Dyslexia","cat":"term","area":"developmental","who":"Rudolf Berlin (coined)","year":"1887","roots":"dys- (Greek, bad, difficult) + lexis (word) = difficulty with words","def":"Developmental difficulty in accurate or fluent word reading and spelling despite adequate intelligence and teaching.","detail":"DSM-5 specific learning disorder with impairment in reading; core deficit is phonological processing; more common in boys; left temporoparietal under-activation.","example":"A bright 9-year-old reverses letters and reads far below his grade level.","look":"Alexia","tell":"Dyslexia: DEVELOPMENTAL (never learned well). Alexia: ACQUIRED (lost after brain damage).","aliases":["dyslexia","developmental dyslexia","specific reading disorder","reading disability"],"lookId":"alexia"},{"id":"dyscalculia","name":"Dyscalculia","cat":"term","area":"developmental","who":"","year":"","roots":"dys- (difficult) + calculus (Latin, pebble for counting) = difficulty with calculation","def":"Developmental difficulty in number sense, arithmetic facts and calculation despite adequate intelligence and teaching.","detail":"DSM-5 specific learning disorder with impairment in mathematics; intraparietal sulcus implicated.","example":"A 10-year-old with normal IQ still counts on fingers for 3 + 4.","look":"Acalculia","tell":"Dyscalculia: developmental. Acalculia: acquired after brain damage.","aliases":["dyscalculia","developmental dyscalculia","specific arithmetic disorder","mathematics disorder"],"lookId":"acalculia"},{"id":"frontal-lobe-syndrome","name":"Frontal lobe syndrome","cat":"term","area":"biological","who":"","year":"","roots":"frons (Latin, forehead) + syndrome (Greek, running together)","def":"Personality and behavioural change after frontal lobe damage: disinhibition, apathy, poor planning, perseveration and poor judgement.","detail":"Orbitofrontal damage gives disinhibition and facetiousness (Witzelsucht, moria); dorsolateral gives dysexecutive syndrome, perseveration; medial gives apathy, abulia. Classic case: Phineas Gage (Harlow).","example":"After a tamping iron passed through his frontal lobe, Phineas Gage became rude, impulsive and 'no longer Gage'.","look":"Kluver-Bucy syndrome","tell":"Frontal: disinhibition, poor planning. Kluver-Bucy: bilateral temporal, hyperorality, placidity, visual agnosia.","aliases":["frontal lobe syndrome","frontal syndrome","dysexecutive syndrome","witzelsucht","moria","prefrontal syndrome"],"lookId":"kluver-bucy-syndrome"}];
